async function showPasswordRecoveryFlow(){if(state.passwordRecoveryShown||!session)return;state.passwordRecoveryShown=true;if(document.getElementById('appView')?.classList.contains('hidden'))await bootstrap();if(!session||!me()){state.passwordRecoveryShown=false;return}modal(`<div class="section-head"><div><div class="eyebrow">Seguridad</div><h3>Crear nueva contraseña</h3><div class="small">El enlace es válido. Define ahora tu nueva contraseña de acceso.</div></div></div><div class="form-grid" style="margin-top:12px"><div class="span2"><label>Nueva contraseña</label><div class="password-field"><input id="recoveryPass1" type="password" autocomplete="new-password" minlength="8"><button id="recoveryPass1Toggle" class="password-toggle" type="button" aria-pressed="false" onclick="toggleRecoveryPassword('recoveryPass1','recoveryPass1Toggle')">Mostrar</button></div></div><div class="span2"><label>Repetir contraseña</label><div class="password-field"><input id="recoveryPass2" type="password" autocomplete="new-password" minlength="8"><button id="recoveryPass2Toggle" class="password-toggle" type="button" aria-pressed="false" onclick="toggleRecoveryPassword('recoveryPass2','recoveryPass2Toggle')">Mostrar</button></div></div></div><div class="actions" style="margin-top:14px"><button class="primary" onclick="saveRecoveredPassword()">Guardar nueva contraseña</button></div>`)}
async function saveRecoveredPassword(){const a=document.getElementById('recoveryPass1')?.value||'',b=document.getElementById('recoveryPass2')?.value||'';if(a.length<8)return notifyMsg('La contraseña debe tener al menos 8 caracteres.','warn');if(a!==b)return notifyMsg('Las dos contraseñas no coinciden.','warn');const {error}=await sb.auth.updateUser({password:a});if(error)return notifyMsg(loginErrorText(error),'bad');history.replaceState({},document.title,location.pathname+location.search.replace(/([?&])type=(recovery|invite)(&|$)/i,(m,p1,p2,p3)=>p3&&p1==='?'?'?':p1).replace(/[?&]$/,'')||location.pathname);closeModal();notifyMsg('Contraseña actualizada correctamente.','info')}
