function askConfirm({title='Confirmar',message='',confirmText='Confirmar',danger=false,requireText=''}){return new Promise(resolve=>{const need=requireText?String(requireText):'';modal(`<div class="section-head"><div><div class="eyebrow">Confirmación</div><h3>${esc(title)}</h3></div></div><div class="note" style="margin-top:12px">${esc(message)}</div>${need?`<div style="margin-top:12px"><label>Escribe <b>${esc(need)}</b> para continuar</label><input id="confirmPhrase" autocomplete="off"></div>`:''}<div class="actions" style="margin-top:14px"><button class="${danger?'danger':'primary'}" id="confirmAccept">${esc(confirmText)}</button><button class="secondary" id="confirmCancel">Cancelar</button></div>`);const ok=document.getElementById('confirmAccept'),cancel=document.getElementById('confirmCancel');ok.onclick=()=>{if(need&&document.getElementById('confirmPhrase').value.trim()!==need)return notifyMsg('La confirmación escrita no coincide.','warn');closeModal();resolve(true)};cancel.onclick=()=>{closeModal();resolve(false)}})}
const HELP_CONTENT={
  computable:{title:'Hora computable',body:'La hora real nunca se modifica. Para calcular jornada se aplica el horario programado: entrar antes o salir después queda registrado, pero ese exceso no suma. Llegar tarde, salir antes y las paradas personales sí reducen el tiempo computable.'},
  estimate:{title:'Tiempo estimado de tarea',body:'Es el tiempo previsto para realizar la tarea. El reloj real sigue registrándose. Si el responsable agota el tiempo autorizado, debe explicar el motivo antes de continuar o completar.'},
  reminder:{title:'Recordatorio',body:'Minutos antes del inicio o vencimiento en los que Totus mostrará el aviso. Las alarmas dependen del volumen, mute y permisos de notificaciones del dispositivo.'},
  recurrence:{title:'Tarea recurrente',body:'Permite repetir una tarea cada X horas, días o semanas. Puedes limitarla por fecha y por número total de ejecuciones. Un valor 0 en número de ejecuciones significa sin límite.'},
  personal_break:{title:'Parada personal',body:'Cigarro, llamada personal, WhatsApp personal, recado u otra pausa no laboral. NO COMPUTA como trabajo, detiene el reloj de tarea y queda registrada con inicio, final, duración y motivo.'},
  work_interrupt:{title:'Interrupción laboral',body:'Motivo laboral que obliga a dejar temporalmente la tarea: cliente, proveedor, incidencia, llamada de trabajo, etc. Sigue COMPUTANDO como jornada, pero se detiene el reloj de la tarea para que su duración no quede falseada.'},
  monthly_target:{title:'Objetivo mensual',body:'Es la referencia de horas ordinarias del mes. Por defecto son 160 h, pero administración puede cambiarlo por empleado y mes. Las horas que superan el objetivo aparecen separadas como adicionales.'},
  purchase_store:{title:'Compra directa en tienda',body:'Se toma el PVP marcado en tienda y se aplica automáticamente el descuento configurado para empleados. Por defecto: PVP −10 %. No se consulta Totus Pricing.'},
  purchase_supplier:{title:'Compra en pedido a proveedor',body:'El empleado paga el coste de proveedor más IVA y Recargo de Equivalencia, más los costes directos por unidad que correspondan. La empresa no aplica margen.'},
  direct_cost:{title:'Costes directos por unidad',body:'Gastos atribuibles directamente a cada unidad de esa compra, por ejemplo transporte prorrateado. Se suman después de calcular coste + IVA + RE.'},
  reports:{title:'Informes',body:'Selecciona empleado, fechas y tienda. Cada botón genera un informe específico; “Informe completo CSV” combina jornada, tareas, tiempos, interrupciones, paradas y compras del rango.'},
  signature:{title:'Firma del informe',body:'La firma queda asociada al empleado, al período y a la huella digital del contenido del informe. Si cambian los datos, la huella deja de coincidir con lo firmado.'},
  library:{title:'Biblioteca interna',body:'Zona para protocolos, tutoriales y documentación del equipo. Administración puede editar, archivar y restaurar. Los empleados solo ven contenido activo. Las versiones de archivos se conservan para trazabilidad.'},
  expected_break:{title:'Tiempo previsto de parada',body:'Referencia configurada por administración para cada tipo de parada personal. Totus compara ese valor con la duración real y con la media histórica del empleado.'},
  unassigned:{title:'Trabajado sin asignar',body:'Tiempo computable de jornada que no está cubierto por relojes de tareas ni por interrupciones laborales registradas. Sirve para detectar trabajo real que no se ha asociado a una actividad concreta.'}
};
function helpIcon(key,label='Ayuda'){return `<button type="button" class="help-btn" title="${esc(label)}" aria-label="${esc(label)}" onclick="event.preventDefault();event.stopPropagation();showHelp('${key}')">?</button>`}
function helpLabel(text,key){return `${esc(text)} ${helpIcon(key,'Qué significa '+text)}`}
function showHelp(key){const h=HELP_CONTENT[key];if(!h)return;modal(`<div class="section-head"><div><div class="eyebrow">Ayuda</div><h3>${esc(h.title)}</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="help-body">${esc(h.body)}</div>`)}
function modal(inner){document.body.classList.add('modal-open');document.getElementById('modalHost').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal" role="dialog" aria-modal="true" aria-label="Ventana de Totus">${inner}</div></div>`;requestAnimationFrame(()=>{const host=document.getElementById('modalHost'),focus=host.querySelector('input:not([disabled]),select:not([disabled]),textarea:not([disabled])')||host.querySelector('button:not([disabled])');focus?.focus({preventScroll:true})})}
function closeModal(){document.body.classList.remove('modal-open');document.getElementById('modalHost').innerHTML=''}
function requiredReasonModal({eyebrow='Confirmación',title,description='',placeholder='Describe el motivo…',confirmLabel='Confirmar',minLength=5,onConfirm}){state.pendingReasonAction=onConfirm;state.pendingReasonMinLength=minLength;modal(`<div class="section-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h3>${esc(title)}</h3>${description?`<div class="small">${esc(description)}</div>`:''}</div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid" style="margin-top:12px"><div class="span2"><label for="requiredReason">Motivo · obligatorio</label><textarea id="requiredReason" rows="4" placeholder="${esc(placeholder)}" aria-describedby="requiredReasonHelp"></textarea><div class="small" id="requiredReasonHelp">Escribe al menos ${minLength} caracteres. El motivo quedará registrado en el histórico.</div></div></div><div class="actions" style="margin-top:14px"><button class="secondary" onclick="closeModal()">Volver</button><button class="primary" onclick="submitRequiredReason()">${esc(confirmLabel)}</button></div>`)}
async function submitRequiredReason(){const reason=(document.getElementById('requiredReason')?.value||'').trim(),min=Number(state.pendingReasonMinLength||5),fn=state.pendingReasonAction;if(reason.length<min)return notifyMsg(`Indica un motivo de al menos ${min} caracteres.`,'warn');state.pendingReasonAction=null;state.pendingReasonMinLength=null;closeModal();if(typeof fn==='function')await fn(reason)}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('modalHost')?.children.length)closeModal()})
function downloadCsv(name,headers,rows){const q=s=>'"'+String(s??'').replace(/"/g,'""')+'"',csv='\ufeff'+[headers,...rows].map(r=>r.map(q).join(';')).join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}

/* Control laboral y tareas reforzado */

db.locations=db.locations||[];db.breaks=db.breaks||[];db.attendanceAudit=db.attendanceAudit||[];db.overruns=db.overruns||[];db.taskAudit=db.taskAudit||[];db.adminAudit=db.adminAudit||[];
state.calendarLocationId=state.calendarLocationId||'all';state.auditOpen=state.auditOpen||false;

function locationById(id){return db.locations.find(x=>x.id===id)||null}
function locationName(id){return locationById(id)?.name||'Sin tienda'}
function breakName(t){return breakType(t)?.label||db.breaks.find(x=>x.break_type===t)?.break_label||t||'Pausa personal'}
function openPersonalBreak(uid=me()?.id){return db.breaks.find(x=>x.user_id===uid&&!x.ended_at)||null}
function effectiveStart(e){return e.effective_clock_in||e.clock_in}
function attendanceRealMinutes(e,now=new Date()){const b=e.clock_out||now;return Math.max(0,(new Date(b)-new Date(e.clock_in))/60000)}
function taskAuthorizedMinutes(t,uid=t.assigned_to){return Number(t.estimated_minutes||0)+db.overruns.filter(x=>x.task_id===t.id&&x.user_id===uid).reduce((a,x)=>a+Number(x.extension_minutes||0),0)}
function taskElapsedMinutes(t,uid=t.assigned_to){return taskWorkedSeconds(t.id,uid)/60}
function taskOverrunState(t){const est=Number(t.estimated_minutes||0);if(est<=0)return{enabled:false,elapsed:taskElapsedMinutes(t),allowed:0,left:null,over:false};const elapsed=taskElapsedMinutes(t),allowed=taskAuthorizedMinutes(t),left=allowed-elapsed;return{enabled:true,elapsed,allowed,left,over:left<=0}}
