async function bootstrap(){
 try{
  await loadDb();
  if(!me()){await sb.auth.signOut();session=null;setLoginStatus('Tu cuenta no está autorizada en Totus Central. Contacta con administración.','bad');return}
  document.getElementById('loginView').classList.add('hidden');document.getElementById('appView').classList.remove('hidden');
  paintUser();state.scheduleUserId=me().id;state.purchaseUserId=me().id;state.historyUserId=me().id;state.timeUserId=me().id;goRoot('tasks','mine');startLoops();
 }catch(e){console.error(e);setLoginStatus('Totus no ha podido cargar los datos principales. Revisa la conexión e inténtalo de nuevo.','bad')}
}
function initSignatureCanvas(){const c=document.getElementById('signatureCanvas');if(!c)return;const rect=c.getBoundingClientRect(),ratio=Math.max(1,window.devicePixelRatio||1);c.width=Math.round(rect.width*ratio);c.height=Math.round(210*ratio);c.style.height='210px';const ctx=c.getContext('2d');ctx.scale(ratio,ratio);ctx.lineWidth=2.3;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#102632';let drawing=false,last=null;const pt=e=>{const r=c.getBoundingClientRect(),q=e.touches?.[0]||e;return{x:q.clientX-r.left,y:q.clientY-r.top}};const start=e=>{e.preventDefault();drawing=true;last=pt(e)};const move=e=>{if(!drawing)return;e.preventDefault();const cur=pt(e);ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(cur.x,cur.y);ctx.stroke();last=cur;state.signatureInk=true};const end=e=>{if(drawing)e?.preventDefault?.();drawing=false;last=null};c.addEventListener('pointerdown',start);c.addEventListener('pointermove',move);window.addEventListener('pointerup',end,{once:false});c.addEventListener('touchstart',start,{passive:false});c.addEventListener('touchmove',move,{passive:false});c.addEventListener('touchend',end,{passive:false})}
function clearSignaturePad(){const c=document.getElementById('signatureCanvas');if(!c)return;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);state.signatureInk=false}
async function saveWorkSignature(){const f=reportFilter(),uid=me().id,c=document.getElementById('signatureCanvas');if(!c||!state.signatureInk)return notifyMsg('Firma primero dentro del recuadro.','warn');if(!isFullCalendarMonth(f.from,f.to))return notifyMsg('Selecciona el mes completo.','warn');const totals=periodHourTotals(uid,f.from,f.to),digest=await reportDigest(uid,f.from,f.to),signature=c.toDataURL('image/png');const {error}=await sb.rpc('sign_work_report',{p_period_start:f.from,p_period_end:f.to,p_report_digest:digest,p_signature_data:signature,p_ordinary_minutes:Math.round(totals.ordinary),p_additional_minutes:Math.round(totals.additional),p_total_minutes:Math.round(totals.worked)});if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderTasks();notifyMsg('Registro mensual firmado y guardado.','info')}
function printOfficialWorkReport(uidArg=''){const f=reportFilter(),uid=uidArg||f.uid||me().id;if(!uid)return notifyMsg('Selecciona un empleado.','warn');const totals=periodHourTotals(uid,f.from,f.to),[rangeStart,rangeEnd]=reportRangeBounds(f.from,f.to),sig=latestSignature(uid,f.from,f.to),u=person(uid),rows=totals.rows.sort((a,b)=>new Date(a.clock_in)-new Date(b.clock_in)),rowIds=new Set(rows.map(e=>e.id)),breakRows=db.breaks.filter(b=>b.user_id===uid&&rowIds.has(b.attendance_entry_id)&&!b.counts_as_work&&intervalMinutesWithin(b.started_at,b.ended_at,rangeStart,rangeEnd)>0).sort((a,b)=>new Date(a.started_at)-new Date(b.started_at)),w=window.open('','_blank','width=1200,height=850');if(!w)return notifyMsg('El navegador ha bloqueado la ventana de impresión.','warn');const body=rows.map(e=>`<tr><td>${esc(attendanceDayLabel(e.clock_in))}</td><td>${esc(locationName(e.location_id))}</td><td>${esc(dt(e.clock_in))}</td><td>${esc(e.clock_out?dt(e.clock_out):'Abierto')}</td><td>${esc(dt(effectiveStart(e)))}</td><td>${esc(e.clock_out?dt(effectiveEnd(e)):'')}</td><td>${Math.round(clampedBreakMinutesForEntry(e,rangeStart,rangeEnd))}</td><td>${Math.round(attendanceNetMinutesBetween(e,rangeStart,rangeEnd))}</td><td>${esc(e.notes||'')}</td></tr>`).join(''),breakBody=breakRows.map(b=>{const e=db.attendance.find(x=>x.id===b.attendance_entry_id);return `<tr><td>${esc(attendanceDayLabel(b.started_at))}</td><td>${esc(locationName(e?.location_id))}</td><td>${esc(b.break_label||breakName(b.break_type))}</td><td>NO COMPUTA</td><td>${esc(dt(b.started_at))}</td><td>${esc(b.ended_at?dt(b.ended_at):'Abierta')}</td><td>${Math.round(intervalMinutesWithin(b.started_at,b.ended_at,rangeStart,rangeEnd))}</td><td>${esc(b.notes||'')}</td></tr>`}).join('');w.document.write(`<html><head><title>Registro de jornada · ${esc(u?.name||'')}</title><style>body{font-family:Arial,sans-serif;color:#111;padding:24px}h1,h2{margin:0}.meta{margin:6px 0 16px;color:#444}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:16px 0}.box{border:1px solid #bbb;padding:10px}.box b{display:block;font-size:18px}table{width:100%;border-collapse:collapse;margin-top:8px}th,td{border:1px solid #bbb;padding:6px;font-size:9px;text-align:left}.section{margin-top:20px}.sign{margin-top:24px;border:1px solid #bbb;padding:12px;min-height:140px;display:flex;align-items:center;gap:20px}.sign img{max-width:280px;max-height:110px}.digest{font-size:8px;word-break:break-all;color:#555}.warning{font-size:10px;margin-top:14px;color:#555}</style></head><body><h1>Registro de jornada</h1><div class="meta"><b>${esc(u?.name||'')}</b> · ${esc(f.from)} → ${esc(f.to)} · Todas las tiendas en las que se prestó servicio</div><div class="summary"><div class="box">Objetivo mensual<b>${esc(fmtHours(totals.target))}</b></div><div class="box">Horas ordinarias<b>${esc(fmtHours(totals.ordinary))}</b></div><div class="box">Horas adicionales<b>${esc(fmtHours(totals.additional))}</b></div><div class="box">Total computado<b>${esc(fmtHours(totals.worked))}</b></div></div><table><thead><tr><th>Día</th><th>Tienda</th><th>Entrada real</th><th>Salida real</th><th>Entrada computable</th><th>Salida computable</th><th>Paradas min</th><th>Computado min</th><th>Notas</th></tr></thead><tbody>${body}</tbody></table><div class="section"><h2>Paradas personales no computables</h2><table><thead><tr><th>Día</th><th>Tienda</th><th>Motivo</th><th>Tipo</th><th>Inicio</th><th>Fin</th><th>Min.</th><th>Nota</th></tr></thead><tbody>${breakBody||'<tr><td colspan="8">Sin paradas personales en el periodo.</td></tr>'}</tbody></table></div><div class="sign">${sig?`<img src="${sig.signature_data}"><div><b>Firmado ${esc(dt(sig.signed_at))}</b><div class="digest">SHA-256 ${esc(sig.report_digest)}</div></div>`:'<div><b>Firma del trabajador:</b><div style="height:90px;width:300px;border-bottom:1px solid #555"></div><div>Fecha: __________________</div></div>'}</div><div class="warning">Este registro refleja íntegramente las horas computadas del periodo, incluidas las horas adicionales cuando existan, las tiendas de prestación del servicio y las paradas personales no computables.</div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}

function taskTimeAuditHtml(uid){const rows=db.taskTimeAudit.filter(x=>x.user_id===uid).slice(0,300);return `<details class="audit-details" style="margin-top:12px"><summary>Log de tiempos de tarea · ${rows.length} eventos</summary><div class="card audit-card"><div class="section-head"><div><h3>Trazabilidad de tiempos</h3><div class="small">Correcciones y cambios; el histórico no se elimina.</div></div><div class="actions"><button class="secondary" onclick="exportTaskTimeAudit('${uid}')">Exportar</button><button class="secondary" onclick="printTaskTimeAudit('${uid}')">Imprimir</button></div></div><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Fecha</th><th>Tarea</th><th>Acción</th><th>Actor</th><th>Motivo</th><th>Cambio</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${dt(a.created_at)}</td><td>${esc(db.tasks.find(t=>t.id===a.task_id)?.title||'')}</td><td>${esc(a.action)}</td><td>${esc(person(a.actor_user_id)?.name||'Sistema')}</td><td>${esc(a.reason||'')}</td><td class="small">${esc(jsonSummary(a.new_data))}</td></tr>`).join('')||'<tr><td colspan="6" class="small">Sin eventos.</td></tr>'}</tbody></table></div></div></details>`}
function exportTaskTimeAudit(uid){downloadCsv('log_tiempos_tarea.csv',['Empleado','Fecha','Tarea','Acción','Actor','Motivo','Antes','Después'],db.taskTimeAudit.filter(x=>x.user_id===uid).map(a=>[person(uid)?.name||'',a.created_at,db.tasks.find(t=>t.id===a.task_id)?.title||'',a.action,person(a.actor_user_id)?.name||'Sistema',a.reason||'',jsonSummary(a.old_data),jsonSummary(a.new_data)]))}
function printTaskTimeAudit(uid){printSimpleLog(`Log de tiempos · ${person(uid)?.name||''}`,['Fecha','Tarea','Acción','Actor','Motivo','Antes','Después'],db.taskTimeAudit.filter(x=>x.user_id===uid).map(a=>[a.created_at,db.tasks.find(t=>t.id===a.task_id)?.title||'',a.action,person(a.actor_user_id)?.name||'Sistema',a.reason||'',jsonSummary(a.old_data),jsonSummary(a.new_data)]))}
function printTaskTimes(uid){printSimpleLog(`Tiempos de tarea · ${person(uid)?.name||''}`,['Tarea','Tienda','Inicio','Fin','Minutos','Notas'],db.taskTimes.filter(x=>x.user_id===uid).map(x=>{const t=db.tasks.find(t=>t.id===x.task_id);return[t?.title||'',locationName(t?.location_id),x.started_at,x.stopped_at||'',Math.round(elapsedSec(x.started_at,x.stopped_at)/60),x.notes||'']}))}
function editTaskTime(id){if(!isAdmin())return;const x=db.taskTimes.find(v=>v.id===id);if(!x)return;const t=db.tasks.find(t=>t.id===x.task_id);modal(`<div class="section-head"><div><div class="eyebrow">Corrección administrativa</div><h3>${esc(t?.title||'Tiempo de tarea')}</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid" style="margin-top:12px"><div class="span2"><label>Inicio</label><input id="tteIn" type="datetime-local" value="${inputDT(x.started_at)}"></div><div class="span2"><label>Fin</label><input id="tteOut" type="datetime-local" value="${inputDT(x.stopped_at)}"></div><div class="span4"><label>Motivo obligatorio</label><input id="tteReason" placeholder="Por qué se corrige este tiempo"></div><div class="span4"><label>Notas</label><input id="tteNotes" value="${esc(x.notes||'')}"></div></div><div class="actions" style="margin-top:12px"><button class="primary" onclick="saveTaskTimeEdit('${id}')">Guardar corrección</button></div>`)}
async function saveTaskTimeEdit(id){const reason=document.getElementById('tteReason').value.trim(),start=isoFromInput(document.getElementById('tteIn').value),stop=isoFromInput(document.getElementById('tteOut').value),notes=document.getElementById('tteNotes').value.trim();if(reason.length<5)return notifyMsg('Indica un motivo de al menos 5 caracteres.','warn');if(!start||!stop||new Date(stop)<new Date(start))return notifyMsg('Revisa inicio y fin.','warn');const {error}=await sb.rpc('task_time_admin_update',{p_id:id,p_started_at:start,p_stopped_at:stop,p_reason:reason,p_notes:notes});if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderTasks();notifyMsg('Tiempo corregido con auditoría.')}

function purchaseUserScope(){return isAdmin()?(state.purchaseUserId||''):me().id}
function purchaseRows(uid=purchaseUserScope()){return db.purchases.filter(x=>!uid||x.user_id===uid)}
function renderPurchasesModule(){const m=document.getElementById('main');if(state.sub==='purchase-history')m.innerHTML=purchaseHistoryHtml();else if(state.sub==='purchase-reports')m.innerHTML=purchaseReportsHtml();else if(state.sub==='purchase-audit')m.innerHTML=purchaseAuditHtml();else m.innerHTML=purchaseOverviewHtml();tick()}
function purchaseUserSelect(uid){if(!isAdmin())return'';return `<div style="min-width:250px"><label>Empleado</label><select onchange="state.purchaseUserId=this.value;renderPurchasesModule()"><option value="">Todos</option>${db.people.filter(p=>p.role!=='invitado').map(p=>`<option value="${p.id}" ${uid===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>`}
function purchaseAlerts(rows){const now=Date.now(),oldPending=rows.filter(x=>x.status==='pending'&&(now-new Date(x.created_at))/86400000>3),missingRef=rows.filter(x=>x.status!=='cancelled'&&(!x.external_reference||x.purchase_kind==='supplier_order'&&!x.source_name)),cancelled=rows.filter(x=>x.status==='cancelled'),corrected=db.purchaseAudit.filter(a=>a.action==='financial_correction'&&rows.some(p=>p.id===a.purchase_id));return `<div class="grid g2"><div class="card"><h3>Alertas de control</h3><div class="list"><div class="row"><div class="grow">Pendientes > 3 días</div><span class="badge ${oldPending.length?'badb':'ok'}">${oldPending.length}</span></div><div class="row"><div class="grow">Sin referencia/proveedor suficiente</div><span class="badge ${missingRef.length?'warnb':'ok'}">${missingRef.length}</span></div><div class="row"><div class="grow">Canceladas</div><span class="badge ${cancelled.length?'warnb':'ok'}">${cancelled.length}</span></div><div class="row"><div class="grow">Correcciones económicas auditadas</div><span class="badge ${corrected.length?'warnb':'ok'}">${corrected.length}</span></div></div></div><div class="card"><h3>Regla de conservación</h3><div class="note">Las compras <b>no se eliminan</b>. Si una compra no procede, el administrador la cancela con motivo. Cada alta, corrección y cambio de estado queda en auditoría.</div></div></div>`}
function purchaseOverviewHtml(){const uid=purchaseUserScope(),rows=purchaseRows(uid),rules=db.settings.employee_purchase_rules||{vat_pct:21,re_pct:5.2,store_discount_pct:10},u=uid?person(uid):null;const total=rows.filter(x=>x.status!=='cancelled').reduce((a,x)=>a+Number(x.total||0),0);return `<div class="head"><div><div class="eyebrow">Compras</div><h1>Control de compras del equipo</h1><p>Módulo independiente de Tareas y de Pricing. No consulta catálogo, costes ni productos de Totus Pricing.</p></div>${purchaseUserSelect(uid)}</div><div class="stats"><div class="stat"><small>Registros</small><strong>${rows.length}</strong></div><div class="stat"><small>Pendientes</small><strong>${rows.filter(x=>x.status==='pending').length}</strong></div><div class="stat"><small>Canceladas</small><strong>${rows.filter(x=>x.status==='cancelled').length}</strong></div><div class="stat"><small>Importe no cancelado</small><strong>${money(total)}</strong></div></div>${purchaseAlerts(rows)}${canRegisterPurchase()?`<div class="card" style="margin-top:12px"><div class="section-head"><div><h3>Nueva compra${u?' · '+esc(u.name):''}</h3><div class="small">Un empleado solo registra compras propias. El admin puede registrar para cualquier miembro.</div></div></div>${purchaseForm(uid||me().id,rules)}</div>`:`<div class="note" style="margin-top:12px"><b>Solo lectura.</b> Tu perfil puede consultar compras e informes, pero no registrar operaciones.</div>`}${purchaseLocalLogHtml()}`}
function purchaseForm(uid,rules){const loc=db.locations[0]?.id||'';return `<div class="purchase-form"><div class="form-section"><div class="form-section-title"><b>1 · Compra</b><span>Qué, dónde y cuándo</span></div><div class="form-grid"><div class="span2"><label>Producto / concepto · obligatorio</label><input id="buyName" placeholder="Nombre o referencia"></div><div><label>Tienda donde se imputa · obligatoria</label><select id="buyLocation"><option value="">Selecciona…</option>${db.locations.map(l=>`<option value="${l.id}" ${l.id===loc?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div><div><label>Fecha de compra</label><input id="buyDate" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="span2"><label>Tipo de compra</label><select id="buyKind" onchange="purchaseKindChanged()"><option value="store_stock">Compra directa en tienda · -${rules.store_discount_pct||10}% PVP</option><option value="supplier_order">Adquirido en pedido a proveedor · coste + impuestos</option></select></div><div><label>Cantidad</label><input id="buyQty" type="number" min="0.001" step="0.001" value="1" oninput="calcPurchasePreview()"></div></div></div><div class="form-section"><div class="form-section-title"><b>2 · Precio</b><span id="buyFormulaTitle">Compra directa · PVP − ${rules.store_discount_pct||10}%</span></div><div class="form-grid"><div id="buyPvpWrap" class="span2"><label>${helpLabel('PVP marcado en tienda','purchase_store')}</label><input id="buyPvp" inputmode="decimal" placeholder="0,00" oninput="calcPurchasePreview()"></div><div id="buyCostWrap" class="hidden"><label>${helpLabel('Coste proveedor sin IVA/RE','purchase_supplier')}</label><input id="buyCost" inputmode="decimal" placeholder="0,00" oninput="calcPurchasePreview()"></div><div id="buyExtraWrap" class="hidden"><label>${helpLabel('Costes directos / ud','direct_cost')}</label><input id="buyExtra" inputmode="decimal" value="0" oninput="calcPurchasePreview()"></div><div id="buySupplierWrap" class="hidden span2"><label>Proveedor · obligatorio</label><input id="buySupplier" placeholder="Nombre del proveedor"></div><div class="price-preview"><small>Precio empleado / ud</small><strong id="buyUnitPreviewText">0,00 €</strong><input id="buyUnitPreview" class="sr-only" tabindex="-1" disabled value="0,00 €"></div><div class="price-preview total"><small>Total</small><strong id="buyTotalPreviewText">0,00 €</strong><input id="buyTotalPreview" class="sr-only" tabindex="-1" disabled value="0,00 €"></div></div><div class="formula-note" id="buyFormulaNote">PVP × ${(1-Number(rules.store_discount_pct||10)/100).toFixed(2).replace('.',',')} = precio empleado.</div></div><div class="form-section"><div class="form-section-title"><b>3 · Justificante y pago</b><span>Datos para identificar la operación</span></div><div class="form-grid"><div class="span2"><label id="buyRefLabel">Ticket / referencia de tienda · obligatorio</label><input id="buyRef" placeholder="Nº ticket o referencia"></div><div><label>Método de pago · obligatorio</label><select id="buyPayment"><option value="">Selecciona…</option><option value="cash">Efectivo</option><option value="card">Tarjeta</option><option value="transfer">Transferencia</option><option value="other">Otro</option></select></div><div class="span4"><label>Notas / detalle</label><input id="buyNotes" placeholder="Observaciones, motivo, detalles…"></div></div></div><div class="actions sticky-actions"><button class="primary" onclick="savePurchase('${uid}')">Registrar compra</button></div></div>`}
function purchaseKindChanged(){const rules=db.settings.employee_purchase_rules||{vat_pct:21,re_pct:5.2,store_discount_pct:10},sup=document.getElementById('buyKind').value==='supplier_order';['buyCostWrap','buyExtraWrap','buySupplierWrap'].forEach(id=>document.getElementById(id)?.classList.toggle('hidden',!sup));document.getElementById('buyPvpWrap')?.classList.toggle('hidden',sup);const lab=document.getElementById('buyRefLabel'),ref=document.getElementById('buyRef'),title=document.getElementById('buyFormulaTitle'),note=document.getElementById('buyFormulaNote');if(lab)lab.textContent=sup?'Factura / pedido de proveedor · obligatorio':'Ticket / referencia de tienda · obligatorio';if(ref)ref.placeholder=sup?'Nº factura o pedido proveedor':'Nº ticket o referencia';if(title)title.textContent=sup?`Pedido proveedor · coste + ${Number(rules.vat_pct||21).toLocaleString('es-ES')}% IVA + ${Number(rules.re_pct||5.2).toLocaleString('es-ES')}% RE`:`Compra directa · PVP − ${Number(rules.store_discount_pct||10).toLocaleString('es-ES')}%`;if(note)note.textContent=sup?'Coste × (1 + IVA + RE) + costes directos por unidad = precio empleado.':`PVP × ${(1-Number(rules.store_discount_pct||10)/100).toFixed(2).replace('.',',')} = precio empleado.`;calcPurchasePreview()}
function calcPurchasePreview(){const rules=db.settings.employee_purchase_rules||{vat_pct:21,re_pct:5.2,store_discount_pct:10},kind=document.getElementById('buyKind')?.value||'store_stock',qty=Math.max(0,Number(document.getElementById('buyQty')?.value||0)),unit=kind==='store_stock'?n(document.getElementById('buyPvp')?.value)*(1-Number(rules.store_discount_pct||10)/100):n(document.getElementById('buyCost')?.value)*(1+(Number(rules.vat_pct||21)+Number(rules.re_pct||5.2))/100)+Math.max(0,n(document.getElementById('buyExtra')?.value)),total=unit*qty,unitText=money(unit),totalText=money(total);if(document.getElementById('buyUnitPreview'))document.getElementById('buyUnitPreview').value=unitText;if(document.getElementById('buyTotalPreview'))document.getElementById('buyTotalPreview').value=totalText;if(document.getElementById('buyUnitPreviewText'))document.getElementById('buyUnitPreviewText').textContent=unitText;if(document.getElementById('buyTotalPreviewText'))document.getElementById('buyTotalPreviewText').textContent=totalText;return{kind,qty,unit,total}}
async function savePurchase(uid){if(!canRegisterPurchase())return notifyMsg('Tu perfil es de solo lectura.','warn');if(uid!==me().id&&!isAdmin())return;const c=calcPurchasePreview(),name=document.getElementById('buyName').value.trim(),location_id=document.getElementById('buyLocation').value,purchase_date=document.getElementById('buyDate').value,ref=document.getElementById('buyRef').value.trim(),supplier=document.getElementById('buySupplier')?.value.trim()||'';const payment=document.getElementById('buyPayment').value;if(!name||!location_id||!purchase_date)return notifyMsg('Producto, tienda y fecha son obligatorios.','warn');if(ref.length<2)return notifyMsg('Ticket, pedido o referencia es obligatorio.','warn');if(!payment)return notifyMsg('Indica el método de pago.','warn');if(c.qty<=0||c.unit<=0)return notifyMsg('Cantidad y precio deben ser mayores que cero.','warn');if(c.kind==='supplier_order'&&!supplier)return notifyMsg('Indica el proveedor.','warn');const row={user_id:uid,item_name:name,purchase_kind:c.kind,quantity:c.qty,location_id,purchase_date,source_name:c.kind==='supplier_order'?supplier:null,external_reference:ref||null,payment_method:payment,pvp_unit:c.kind==='store_stock'?n(document.getElementById('buyPvp').value):null,supplier_net_cost:c.kind==='supplier_order'?n(document.getElementById('buyCost').value):null,extra_unit_cost:c.kind==='supplier_order'?Math.max(0,n(document.getElementById('buyExtra').value)):0,status:'pending',notes:document.getElementById('buyNotes').value.trim(),created_by:me().id};const {error}=await sb.from('employee_purchases').insert(row);if(error)return notifyMsg(error.message,'bad');await reloadTeamData();renderPurchasesModule();notifyMsg('Compra registrada y auditada.')}
function purchaseHistoryHtml(){const uid=purchaseUserScope(),rows=purchaseRows(uid);return `<div class="head"><div><div class="eyebrow">Compras</div><h1>Historial íntegro</h1><p>Los registros no se borran. Las cancelaciones y correcciones quedan visibles.</p></div>${purchaseUserSelect(uid)}</div><div class="card"><div class="section-head"><h3>${rows.length} registros</h3><div class="actions"><button class="secondary" onclick="exportPurchases('${uid}')">Exportar CSV</button><button class="secondary" onclick="printPurchases('${uid}')">Imprimir</button></div></div><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Fecha</th><th>Empleado</th><th>Tienda</th><th>Producto</th><th>Tipo</th><th>Proveedor/ref.</th><th>Cant.</th><th>Precio ud.</th><th>Total</th><th>Estado</th><th>Notas</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.purchase_date||'')}<div class="small">Alta ${dt(p.created_at)}</div></td><td>${esc(person(p.user_id)?.name||'')}</td><td>${esc(locationName(p.location_id))}</td><td><b>${esc(p.item_name)}</b></td><td>${p.purchase_kind==='store_stock'?'Tienda':'Proveedor'}</td><td>${esc(p.source_name||'')}${p.external_reference?`<div class="small">${esc(p.external_reference)}</div>`:''}</td><td>${p.quantity}</td><td>${money(p.employee_unit_price)}</td><td><b>${money(p.total)}</b></td><td><span class="badge ${badgeStatus(p.status)}">${purchaseStatusName(p.status)}</span>${p.cancel_reason?`<div class="small">${esc(p.cancel_reason)}</div>`:''}</td><td>${esc(p.notes||'')}${p.admin_notes?`<div class="small">Admin: ${esc(p.admin_notes)}</div>`:''}</td><td>${purchaseActions(p)}</td></tr>`).join('')||'<tr><td colspan="12" class="small">Sin compras.</td></tr>'}</tbody></table></div></div>${purchaseLocalLogHtml()}`}
function purchaseActions(p){if(!isAdmin())return'';let out=`<button class="secondary" onclick="editPurchase('${p.id}')">Revisar</button> `;if(p.status==='pending')out+=`<button class="primary" onclick="setPurchaseStatus('${p.id}','approved')">Aprobar</button> `;if(p.status==='approved')out+=`<button class="ghost" onclick="setPurchaseStatus('${p.id}','paid')">Pagada</button> `;if(p.status==='paid')out+=`<button class="ghost" onclick="setPurchaseStatus('${p.id}','delivered')">Entregada</button> `;if(p.status!=='cancelled')out+=`<button class="danger" onclick="cancelPurchase('${p.id}')">Cancelar</button>`;return out}
function editPurchase(id){if(!isAdmin())return;const p=db.purchases.find(x=>x.id===id);if(!p)return;const store=p.purchase_kind==='store_stock';modal(`<div class="section-head"><div><div class="eyebrow">Revisión administrativa</div><h3>Corregir compra</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid" style="margin-top:12px"><div class="span2"><label>Producto</label><input id="epName" value="${esc(p.item_name)}"></div><div><label>Empleado</label><select id="epUser">${db.people.map(u=>`<option value="${u.id}" ${u.id===p.user_id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div><div><label>Tienda</label><select id="epLocation">${db.locations.map(l=>`<option value="${l.id}" ${l.id===p.location_id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div><div><label>Fecha</label><input id="epDate" type="date" value="${esc(p.purchase_date||'')}"></div><div><label>Tipo</label><select id="epKind" onchange="editPurchaseKindChanged()"><option value="store_stock" ${store?'selected':''}>Tienda</option><option value="supplier_order" ${!store?'selected':''}>Proveedor</option></select></div><div><label>Cantidad</label><input id="epQty" type="number" min="0.001" step="0.001" value="${p.quantity}"></div><div id="epPvpWrap" class="${store?'':'hidden'}"><label>PVP / ud</label><input id="epPvp" value="${p.pvp_unit??''}"></div><div id="epCostWrap" class="${store?'hidden':''}"><label>Coste proveedor / ud</label><input id="epCost" value="${p.supplier_net_cost??''}"></div><div id="epExtraWrap" class="${store?'hidden':''}"><label>Costes directos / ud</label><input id="epExtra" value="${p.extra_unit_cost??0}"></div><div id="epSupplierWrap" class="${store?'hidden':''}"><label>Proveedor</label><input id="epSupplier" value="${esc(p.source_name||'')}"></div><div><label>Referencia</label><input id="epRef" value="${esc(p.external_reference||'')}"></div><div><label>Método de pago</label><select id="epPayment">${[['cash','Efectivo'],['card','Tarjeta'],['transfer','Transferencia'],['other','Otro']].map(([v,t])=>`<option value="${v}" ${p.payment_method===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="span4"><label>Notas compra</label><input id="epNotes" value="${esc(p.notes||'')}"></div><div class="span4"><label>Motivo de la corrección · obligatorio</label><input id="epAdminNotes" placeholder="Qué se corrige y por qué"></div></div><div class="actions" style="margin-top:12px"><button class="primary" onclick="savePurchaseEdit('${p.id}')">Guardar corrección</button></div>`)}
function editPurchaseKindChanged(){const sup=document.getElementById('epKind').value==='supplier_order';['epCostWrap','epExtraWrap','epSupplierWrap'].forEach(id=>document.getElementById(id)?.classList.toggle('hidden',!sup));document.getElementById('epPvpWrap')?.classList.toggle('hidden',sup)}
async function savePurchaseEdit(id){const kind=document.getElementById('epKind').value,reason=document.getElementById('epAdminNotes').value.trim(),row={user_id:document.getElementById('epUser').value,location_id:document.getElementById('epLocation').value,purchase_date:document.getElementById('epDate').value,item_name:document.getElementById('epName').value.trim(),purchase_kind:kind,quantity:Number(document.getElementById('epQty').value||0),pvp_unit:kind==='store_stock'?n(document.getElementById('epPvp').value):null,supplier_net_cost:kind==='supplier_order'?n(document.getElementById('epCost').value):null,extra_unit_cost:kind==='supplier_order'?Math.max(0,n(document.getElementById('epExtra').value)):0,source_name:kind==='supplier_order'?document.getElementById('epSupplier').value.trim():null,external_reference:document.getElementById('epRef').value.trim()||null,payment_method:document.getElementById('epPayment').value,notes:document.getElementById('epNotes').value.trim(),admin_notes:reason};if(reason.length<5)return notifyMsg('Toda corrección requiere un motivo de al menos 5 caracteres.','warn');if((row.external_reference||'').length<2)return notifyMsg('Ticket, pedido o referencia es obligatorio.','warn');if(!row.payment_method||row.payment_method==='unknown')return notifyMsg('Indica el método de pago.','warn');if(!row.item_name||!row.location_id||!row.purchase_date||row.quantity<=0)return notifyMsg('Revisa producto, tienda, fecha y cantidad.','warn');if(kind==='supplier_order'&&!row.source_name)return notifyMsg('Indica el proveedor.','warn');const {error}=await sb.from('employee_purchases').update(row).eq('id',id);if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderPurchasesModule();notifyMsg('Compra corregida con trazabilidad.')}
async function setPurchaseStatus(id,status){if(!isAdmin())return;const row={status};if(status==='approved'){row.approved_by=me().id;row.approved_at=new Date().toISOString()}const {error}=await sb.from('employee_purchases').update(row).eq('id',id);if(error)return notifyMsg(error.message,'bad');await reloadTeamData();renderPurchasesModule();notifyMsg('Estado actualizado y auditado.')}
function cancelPurchase(id){if(!isAdmin())return notifyMsg('Solo administración puede cancelar compras.','warn');requiredReasonModal({eyebrow:'Cancelar compra',title:'¿Por qué se cancela esta compra?',description:'La compra permanecerá en el histórico y en la auditoría. No se borra.',placeholder:'Ej.: ticket anulado, pedido cancelado por proveedor…',confirmLabel:'Cancelar compra',onConfirm:reason=>commitCancelPurchase(id,reason)})}
async function commitCancelPurchase(id,reason){const {error}=await sb.from('employee_purchases').update({status:'cancelled',cancel_reason:reason}).eq('id',id);if(error)return notifyMsg(error.message,'bad');await reloadTeamData();renderPurchasesModule();notifyMsg('Compra cancelada; el registro se conserva.')}
function exportPurchases(uid=''){const rows=purchaseRows(uid);downloadCsv('compras_control.csv',['ID','Empleado','Tienda','Fecha compra','Alta','Producto','Tipo','Proveedor','Referencia','Pago','Cantidad','PVP ud','Coste proveedor ud','Coste directo ud','IVA %','RE %','Dto tienda %','Precio empleado ud','Total','Estado','Aprobado por','Aprobado','Cancelado por','Cancelado','Motivo cancelación','Notas','Notas admin'],rows.map(x=>[x.id,person(x.user_id)?.name||'',locationName(x.location_id),x.purchase_date||'',x.created_at,x.item_name,x.purchase_kind,x.source_name||'',x.external_reference||'',x.payment_method||'unknown',x.quantity,x.pvp_unit??'',x.supplier_net_cost??'',x.extra_unit_cost??0,x.vat_pct,x.re_pct,x.stock_discount_pct,x.employee_unit_price,x.total,x.status,person(x.approved_by)?.name||'',x.approved_at||'',person(x.cancelled_by)?.name||'',x.cancelled_at||'',x.cancel_reason||'',x.notes||'',x.admin_notes||'']))}
function printPurchases(uid=''){printSimpleLog('Control de compras',['Fecha','Empleado','Tienda','Producto','Tipo','Referencia','Pago','Cantidad','Total','Estado','Notas'],purchaseRows(uid).map(x=>[x.purchase_date||'',person(x.user_id)?.name||'',locationName(x.location_id),x.item_name,x.purchase_kind,x.external_reference||'',x.payment_method||'unknown',x.quantity,money(x.total),purchaseStatusName(x.status),[x.notes,x.admin_notes,x.cancel_reason].filter(Boolean).join(' · ')]))}
function purchaseAuditHtml(){const uid=purchaseUserScope(),rows=db.purchaseAudit.filter(x=>!uid||x.user_id===uid);return `<div class="head"><div><div class="eyebrow">Compras</div><h1>Auditoría inmutable</h1><p>Quién hizo qué, cuándo, sobre qué compra y cómo cambió.</p></div>${purchaseUserSelect(uid)}</div><div class="card"><div class="section-head"><h3>${rows.length} eventos</h3><div class="actions"><button class="secondary" onclick="exportPurchaseAudit('${uid}')">Exportar CSV</button><button class="secondary" onclick="printPurchaseAudit('${uid}')">Imprimir</button></div></div><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Fecha</th><th>Empleado</th><th>Compra</th><th>Acción</th><th>Actor</th><th>Motivo</th><th>Antes</th><th>Después</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${dt(a.created_at)}</td><td>${esc(person(a.user_id)?.name||'')}</td><td>${esc(db.purchases.find(p=>p.id===a.purchase_id)?.item_name||a.purchase_id||'')}</td><td>${esc(a.action)}</td><td>${esc(person(a.actor_user_id)?.name||'Sistema')}</td><td>${esc(a.reason||'')}</td><td class="small">${esc(jsonSummary(a.old_data))}</td><td class="small">${esc(jsonSummary(a.new_data))}</td></tr>`).join('')||'<tr><td colspan="8" class="small">Sin eventos.</td></tr>'}</tbody></table></div></div>${purchaseLocalLogHtml()}`}
function exportPurchaseAudit(uid=''){const rows=db.purchaseAudit.filter(x=>!uid||x.user_id===uid);downloadCsv('auditoria_compras.csv',['Fecha','Empleado','Compra ID','Producto actual','Acción','Actor','Motivo','Antes','Después'],rows.map(a=>[a.created_at,person(a.user_id)?.name||'',a.purchase_id,db.purchases.find(p=>p.id===a.purchase_id)?.item_name||'',a.action,person(a.actor_user_id)?.name||'Sistema',a.reason||'',jsonSummary(a.old_data),jsonSummary(a.new_data)]))}
function printPurchaseAudit(uid=''){const rows=db.purchaseAudit.filter(x=>!uid||x.user_id===uid);printSimpleLog('Auditoría de compras',['Fecha','Empleado','Compra','Acción','Actor','Motivo','Antes','Después'],rows.map(a=>[a.created_at,person(a.user_id)?.name||'',db.purchases.find(p=>p.id===a.purchase_id)?.item_name||a.purchase_id,a.action,person(a.actor_user_id)?.name||'Sistema',a.reason||'',jsonSummary(a.old_data),jsonSummary(a.new_data)]))}
function purchaseReportsHtml(){const d=defaultReportDates();return `<div class="head"><div><div class="eyebrow">Compras</div><h1>Informes de compras</h1><p>Filtra y extrae compras y auditoría sin mezclar ningún dato de Tareas ni de Pricing.</p></div></div><div class="card report-filter-card"><div class="form-grid report-core-filters"><div><label>Empleado</label><select id="buyRepUser">${reportUserOptions(isAdmin()?'':me().id)}</select></div><div><label>Desde</label><input id="buyRepFrom" type="date" value="${d.from}"></div><div><label>Hasta</label><input id="buyRepTo" type="date" value="${d.to}"></div><div><label>Tienda</label><select id="buyRepLoc">${reportLocationOptions()}</select></div></div><details class="audit-details report-more"><summary>Filtros avanzados</summary><div class="audit-card"><div class="form-grid"><div><label>Estado</label><select id="buyRepStatus"><option value="">Todos</option>${['pending','approved','paid','delivered','cancelled'].map(s=>`<option value="${s}">${purchaseStatusName(s)}</option>`).join('')}</select></div><div><label>Tipo</label><select id="buyRepKind"><option value="">Todos</option><option value="store_stock">En tienda</option><option value="supplier_order">Pedido proveedor</option></select></div><div><label>Proveedor</label><input id="buyRepSupplier" placeholder="Contiene…"></div><div><label>Método de pago</label><select id="buyRepPayment"><option value="">Todos</option><option value="cash">Efectivo</option><option value="card">Tarjeta</option><option value="transfer">Transferencia</option><option value="other">Otro</option></select></div><div><label>Referencia / factura</label><input id="buyRepRef" placeholder="Contiene…"></div><div><label>Texto en notas</label><input id="buyRepNotes" placeholder="Contiene…"></div><div><label>Importe mín.</label><input id="buyRepMin" inputmode="decimal" placeholder="0,00"></div><div><label>Importe máx.</label><input id="buyRepMax" inputmode="decimal" placeholder="Sin límite"></div></div></div></details><div class="actions report-primary-actions"><button class="primary" onclick="exportPurchaseReportFiltered()">Informe exhaustivo CSV</button><button class="secondary" onclick="printPurchaseReportFiltered()">Imprimir</button><button class="ghost" onclick="exportPurchaseAuditFiltered()">Auditoría filtrada</button></div></div>${purchaseLocalLogHtml()}`}
function purchaseReportFilter(){return{uid:isAdmin()?(document.getElementById('buyRepUser')?.value||''):me().id,from:document.getElementById('buyRepFrom')?.value||'',to:document.getElementById('buyRepTo')?.value||'',loc:document.getElementById('buyRepLoc')?.value||'',status:document.getElementById('buyRepStatus')?.value||'',kind:document.getElementById('buyRepKind')?.value||'',supplier:(document.getElementById('buyRepSupplier')?.value||'').trim().toLowerCase(),payment:document.getElementById('buyRepPayment')?.value||'',ref:(document.getElementById('buyRepRef')?.value||'').trim().toLowerCase(),notes:(document.getElementById('buyRepNotes')?.value||'').trim().toLowerCase(),min:n(document.getElementById('buyRepMin')?.value||''),max:n(document.getElementById('buyRepMax')?.value||'')}}
function filteredPurchaseRows(){const f=purchaseReportFilter();return db.purchases.filter(x=>{const total=Number(x.total||0),supplier=String(x.source_name||'').toLowerCase(),ref=String(x.external_reference||'').toLowerCase(),notes=(String(x.notes||'')+' '+String(x.admin_notes||'')+' '+String(x.cancel_reason||'')).toLowerCase();return(!f.uid||x.user_id===f.uid)&&(!f.loc||x.location_id===f.loc)&&(!f.status||x.status===f.status)&&(!f.kind||x.purchase_kind===f.kind)&&(!f.supplier||supplier.includes(f.supplier))&&(!f.payment||x.payment_method===f.payment)&&(!f.ref||ref.includes(f.ref))&&(!f.notes||notes.includes(f.notes))&&(!f.min||total>=f.min)&&(!f.max||total<=f.max)&&dateInRange(x.purchase_date||x.created_at,f.from,f.to)})}
function exportPurchaseReportFiltered(){const rows=filteredPurchaseRows();const ids=new Set(rows.map(x=>x.id)),audit=db.purchaseAudit.filter(a=>ids.has(a.purchase_id));const out=[];rows.forEach(x=>out.push(['COMPRA',x.id,person(x.user_id)?.name||'',locationName(x.location_id),x.purchase_date||'',x.item_name,x.purchase_kind,x.source_name||'',x.external_reference||'',x.payment_method||'unknown',x.quantity,x.employee_unit_price,x.total,x.status,x.notes||'',x.admin_notes||'',x.cancel_reason||'']));audit.forEach(a=>out.push(['AUDITORÍA',a.purchase_id,person(a.user_id)?.name||'','',a.created_at,db.purchases.find(x=>x.id===a.purchase_id)?.item_name||'',a.action,person(a.actor_user_id)?.name||'',a.reason||'','','','','',jsonSummary(a.old_data),jsonSummary(a.new_data),'']));downloadCsv('informe_exhaustivo_compras.csv',['Tipo registro','Compra ID','Empleado','Tienda','Fecha','Producto','Tipo/Acción','Proveedor/Actor','Factura-ticket-referencia/Motivo','Pago','Cantidad','Precio ud','Total','Estado','Notas/Antes','Notas admin/Después','Cancelación'],out)}
function exportPurchaseAuditFiltered(){const ids=new Set(filteredPurchaseRows().map(x=>x.id));downloadCsv('auditoria_compras_filtrada.csv',['Fecha','Compra ID','Empleado','Acción','Actor','Motivo','Antes','Después'],db.purchaseAudit.filter(a=>ids.has(a.purchase_id)).map(a=>[a.created_at,a.purchase_id,person(a.user_id)?.name||'',a.action,person(a.actor_user_id)?.name||'Sistema',a.reason||'',jsonSummary(a.old_data),jsonSummary(a.new_data)]))}
function printPurchaseReportFiltered(){const rows=filteredPurchaseRows();printSimpleLog('Informe de compras',['Fecha','Empleado','Tienda','Producto','Tipo','Proveedor','Referencia','Pago','Cantidad','Precio ud','Total','Estado','Notas'],rows.map(x=>[x.purchase_date||'',person(x.user_id)?.name||'',locationName(x.location_id),x.item_name,x.purchase_kind,x.source_name||'',x.external_reference||'',x.payment_method||'unknown',x.quantity,money(x.employee_unit_price),money(x.total),purchaseStatusName(x.status),[x.notes,x.admin_notes,x.cancel_reason].filter(Boolean).join(' · ')]))}


/* Funcionalidad consolidada */
function taskCategory(id){return db.taskCategories.find(x=>x.id===id)||null}
function taskCategoryName(id){return taskCategory(id)?.name||'Sin categoría'}
async function confirmAttendanceIn(){const loc=document.getElementById('clockLocation')?.value;if(!loc)return notifyMsg('Selecciona una tienda.','warn');const {error}=await sb.rpc('attendance_clock_in',{p_location_id:loc});if(error)return notifyMsg(error.message,'bad');closeModal();notifyMsg(`Entrada registrada · ${locationName(loc)}.`);await reloadTeamData();tick();if(state.root==='tasks')renderTasks()}

function alarmSettingsModal(){modal(`<div class="section-head"><div><div class="eyebrow">Alarmas</div><h3>Sonido y avisos</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="card" style="margin-top:12px"><label>Volumen · <b id="alarmVolText">${Math.round(state.alarmVolume*100)}%</b></label><input id="alarmVolume" type="range" min="0" max="100" step="5" value="${Math.round(state.alarmVolume*100)}" oninput="setAlarmVolume(this.value)"><label class="checkline" style="margin-top:10px"><input id="alarmMute" type="checkbox" ${state.alarmMuted?'checked':''} onchange="toggleAlarmMute(this.checked)"> Silenciar alarmas sonoras</label><div class="actions" style="margin-top:12px"><button class="secondary" onclick="testAlarm()">Probar sonido</button><button class="secondary" onclick="ensureNotifications()">Activar avisos del navegador</button></div></div><div class="note" style="margin-top:10px">El volumen/mute se guarda en este dispositivo. Las alarmas avisan de inicio/vencimiento, tareas olvidadas, tiempo límite, suspensión prolongada y paradas personales abiertas.</div>`)}
function setAlarmVolume(v){state.alarmVolume=Math.max(0,Math.min(1,Number(v)/100));localStorage.setItem('totus_alarm_volume',String(state.alarmVolume));const e=document.getElementById('alarmVolText');if(e)e.textContent=Math.round(state.alarmVolume*100)+'%'}
function toggleAlarmMute(v){state.alarmMuted=!!v;localStorage.setItem('totus_alarm_muted',v?'1':'0')}
function testAlarm(){beep('danger')}
async function ensureNotifications(){if(!('Notification' in window))return notifyMsg('Este navegador no admite notificaciones.','warn');const p=await Notification.requestPermission();notifyMsg(p==='granted'?'Avisos del navegador activados.':'Los avisos del navegador no están permitidos.',p==='granted'?'info':'warn')}

function localDayBounds(dateStr){const a=new Date(dateStr+'T00:00:00'),b=new Date(a);b.setDate(b.getDate()+1);return[a,b]}
function attendanceNetMinutesBetween(e,from,to,now=new Date()){const a0=new Date(effectiveStart(e)),b0=new Date(effectiveEnd(e,now)),a=a0<from?from:a0,b=b0>to?to:b0;if(!Number.isFinite(a.getTime())||!Number.isFinite(b.getTime())||b<=a)return 0;return Math.max(0,(b-a)/60000-clampedBreakMinutesForEntry(e,a,b,now))}
function workdayReconciliationLocal(uid,dateStr,loc=''){const[a,b]=localDayBounds(dateStr),now=new Date();const att=db.attendance.filter(e=>e.user_id===uid&&(!loc||e.location_id===loc)&&new Date(e.clock_in)<b&&new Date(e.clock_out||now)>=a);const attendance=att.reduce((sum,e)=>sum+attendanceNetMinutesBetween(e,a,b,now),0);const attIds=new Set(att.map(e=>e.id));const personal=db.breaks.filter(x=>x.user_id===uid&&attIds.has(x.attendance_entry_id)&&!x.counts_as_work&&new Date(x.started_at)<b&&new Date(x.ended_at||now)>=a).reduce((sum,x)=>sum+Math.max(0,(Math.min(new Date(x.ended_at||now),b)-Math.max(new Date(x.started_at),a))/60000),0);const times=db.taskTimes.filter(x=>x.user_id===uid&&new Date(x.started_at)<b&&new Date(x.stopped_at||now)>=a&&(!loc||db.tasks.find(t=>t.id===x.task_id)?.location_id===loc));const taskMin=times.reduce((sum,x)=>sum+Math.max(0,(Math.min(new Date(x.stopped_at||now),b)-Math.max(new Date(x.started_at),a))/60000),0);const ints=db.interruptions.filter(x=>x.user_id===uid&&x.counts_as_work!==false&&new Date(x.started_at)<b&&new Date(x.ended_at||now)>=a&&(!loc||db.tasks.find(t=>t.id===x.task_id)?.location_id===loc));const workInt=ints.reduce((sum,x)=>sum+Math.max(0,(Math.min(new Date(x.ended_at||now),b)-Math.max(new Date(x.started_at),a))/60000),0);const byCat=new Map();for(const x of times){const t=db.tasks.find(t=>t.id===x.task_id),name=taskCategoryName(t?.category_id),mins=Math.max(0,(Math.min(new Date(x.stopped_at||now),b)-Math.max(new Date(x.started_at),a))/60000);byCat.set(name,(byCat.get(name)||0)+mins)}const accounted=taskMin+workInt;return{date:dateStr,attendance,taskMin,workInt,personal,accounted,unaccounted:Math.max(0,attendance-accounted),over:Math.max(0,accounted-attendance),categories:[...byCat.entries()].sort((a,b)=>b[1]-a[1])}}
function dateRangeDays(from,to){const out=[],a=new Date(from+'T12:00:00'),b=new Date(to+'T12:00:00');for(let x=new Date(a);x<=b;x.setDate(x.getDate()+1))out.push(dayIsoLocal(x));return out}
function reconciliationPreviewHtml(uid){const day=dayIsoLocal(new Date()),r=workdayReconciliationLocal(uid||me().id,day,'');return `<div class="card reconciliation-card" style="margin-top:12px"><div class="section-head"><div><div class="eyebrow">Conciliación de hoy</div><h3>Jornada vs. trabajo registrado</h3></div><span class="badge ${r.unaccounted>15?'badb':r.unaccounted>0?'warnb':'ok'}">${r.unaccounted>0?fmtHours(r.unaccounted)+' sin asignar':'CUADRA'}</span></div><div class="stats" style="margin-top:12px"><div class="stat"><small>Jornada computable</small><strong>${fmtHours(r.attendance)}</strong></div><div class="stat"><small>Relojes de tareas</small><strong>${fmtHours(r.taskMin)}</strong></div><div class="stat"><small>Interrupciones laborales</small><strong>${fmtHours(r.workInt)}</strong></div><div class="stat"><small>Paradas personales</small><strong>${fmtHours(r.personal)}</strong></div></div><div class="small">${r.categories.length?'Reparto: '+r.categories.slice(0,5).map(([k,v])=>`${esc(k)} ${fmtHours(v)}`).join(' · '):'Aún no hay tiempo de tareas registrado hoy.'}</div></div>`}
function exportReconciliationRange(){const f=reportFilter(),users=filteredUsers(f.uid),rows=[];for(const uid of users)for(const day of dateRangeDays(f.from,f.to)){const r=workdayReconciliationLocal(uid,day,f.loc);if(r.attendance<=0&&r.accounted<=0&&r.personal<=0)continue;rows.push([person(uid)?.name||'',day,f.loc?locationName(f.loc):'Todas',Math.round(r.attendance),Math.round(r.taskMin),Math.round(r.workInt),Math.round(r.personal),Math.round(r.accounted),Math.round(r.unaccounted),Math.round(r.over),r.categories.map(([k,v])=>`${k}: ${Math.round(v)} min`).join(' | ')])}downloadCsv('conciliacion_jornada_tareas.csv',['Empleado','Fecha','Tienda','Jornada computable min','Tareas min','Interrupciones laborales min','Paradas personales min','Trabajo justificado min','Tiempo sin asignar min','Exceso asignado min','Categorías'],rows)}

function taskLocalLogHtml(){const uid=isAdmin()?'':me().id,rows=[];for(const a of db.taskTimeAudit){if(uid&&a.user_id!==uid)continue;rows.push({at:a.created_at,user:a.user_id,actor:a.actor_user_id,action:'Tiempo · '+a.action,detail:a.reason||jsonSummary(a.new_data)})}for(const i of db.interruptions){if(uid&&i.user_id!==uid)continue;rows.push({at:i.created_at||i.started_at,user:i.user_id,actor:i.user_id,action:'Interrupción laboral · '+interruptionName(i.reason_code),detail:i.reason_note||''})}for(const o of db.overruns){if(uid&&o.user_id!==uid)continue;rows.push({at:o.created_at,user:o.user_id,actor:o.user_id,action:'Ampliación de tarea',detail:o.justification||''})}if(isAdmin())for(const a of db.taskAudit)rows.push({at:a.created_at,user:(a.new_data||a.old_data)?.assigned_to||null,actor:a.actor_user_id,action:'Tarea · '+a.action,detail:jsonSummary(a.new_data||a.old_data)});rows.sort((a,b)=>new Date(b.at)-new Date(a.at));return localLogDetails('Log de Tareas',rows.slice(0,300))}
function purchaseLocalLogHtml(){const rows=db.purchaseAudit.filter(a=>isAdmin()||a.user_id===me().id).map(a=>({at:a.created_at,user:a.user_id,actor:a.actor_user_id,action:'Compra · '+a.action,detail:[a.reason,jsonSummary(a.new_data)].filter(Boolean).join(' · ')}));return localLogDetails('Log de Compras',rows.slice(0,300))}
function scheduleLocalLogHtml(){if(!isAdmin())return'';const rows=db.adminAudit.filter(a=>['employee_schedule','employee_schedule_exception','location_opening_hours','location_opening_exception','break_type'].includes(a.entity_type)).map(a=>({at:a.created_at,user:a.target_user_id,actor:a.actor_user_id,action:`${a.entity_type} · ${a.action}`,detail:jsonSummary(a.new_data||a.old_data)}));return localLogDetails('Log de Programación',rows.slice(0,300))}
function localLogDetails(title,rows){return `<details class="audit-details" style="margin-top:12px"><summary>Historial de esta zona · ${esc(title)} · ${rows.length} movimientos</summary><div class="card audit-card"><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Actor</th><th>Detalle</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dt(x.at)}</td><td>${esc(person(x.user)?.name||'')}</td><td>${esc(x.action)}</td><td>${esc(person(x.actor)?.name||'Sistema')}</td><td class="small">${esc(x.detail||'')}</td></tr>`).join('')||'<tr><td colspan="5" class="small">Sin movimientos.</td></tr>'}</tbody></table></div></div></details>`}

function generalLogRows(){
 const rows=[],push=(module,at,user,actor,action,detail)=>rows.push({module,at,user,actor,action,detail});
 db.attendanceAudit.forEach(a=>push('Fichajes',a.created_at,a.user_id,a.actor_user_id,a.action,a.reason||jsonSummary(a.new_data)));db.breaks.filter(b=>!b.counts_as_work).forEach(b=>push('Fichajes',b.created_at||b.started_at,b.user_id,b.started_by||b.user_id,'Parada personal · '+breakName(b.break_type),[b.started_at,b.ended_at?('fin '+b.ended_at):'ABIERTA',b.notes].filter(Boolean).join(' · ')));db.taskTimeAudit.forEach(a=>push('Tareas',a.created_at,a.user_id,a.actor_user_id,'Tiempo · '+a.action,a.reason||jsonSummary(a.new_data)));db.interruptions.forEach(a=>push('Tareas',a.created_at||a.started_at,a.user_id,a.user_id,'Interrupción · '+interruptionName(a.reason_code),a.reason_note||''));db.overruns.forEach(a=>push('Tareas',a.created_at,a.user_id,a.user_id,'Ampliación',a.justification||''));if(isAdmin())db.taskAudit.forEach(a=>push('Tareas',a.created_at,(a.new_data||a.old_data)?.assigned_to||null,a.actor_user_id,a.action,jsonSummary(a.new_data||a.old_data)));db.evidence.forEach(e=>push('Tareas',e.created_at,e.uploaded_by,e.uploaded_by,'Evidencia fotográfica',e.file_name));db.purchaseAudit.forEach(a=>push('Compras',a.created_at,a.user_id,a.actor_user_id,a.action,a.reason||jsonSummary(a.new_data)));if(isAdmin())db.adminAudit.forEach(a=>push('Administración',a.created_at,a.target_user_id,a.actor_user_id,`${a.entity_type} · ${a.action}`,jsonSummary(a.new_data||a.old_data)));db.signatures.forEach(a=>push('Informes',a.signed_at,a.user_id,a.user_id,'Firma de registro',`${a.period_start} → ${a.period_end} · ${a.total_minutes} min`));db.consultationHistory.forEach(a=>{if(isAdmin()||a.user_id===me().id)push('Precios',a.created_at,a.user_id,a.user_id,'Consulta · '+a.action,a.consultation_query||'')});db.priceHistory.forEach(a=>{if(isAdmin()||a.user_id===me().id)push('Precios',a.created_at,a.user_id,a.user_id,'Histórico de precio',jsonSummary(a.snapshot))});if(isAdmin())db.userAudit.forEach(a=>{const actor=db.people.find(p=>(p.email||'').toLowerCase()===(a.actor_email||'').toLowerCase())?.id,target=db.people.find(p=>(p.email||'').toLowerCase()===(a.target_email||'').toLowerCase())?.id;push('Usuarios',a.created_at,target,actor,a.action,[a.status,a.detail].filter(Boolean).join(' · '))});if(isAdmin())db.emailLog.forEach(a=>{const target=db.people.find(p=>(p.email||'').toLowerCase()===(a.recipient_email||'').toLowerCase())?.id;push('Usuarios',a.created_at,target,null,'Correo · '+(a.email_type||''),[a.status,a.detail].filter(Boolean).join(' · '))});db.libraryAudit.forEach(a=>push('Tutoriales',a.created_at,null,a.actor_user_id,a.action,[a.title,a.detail].filter(Boolean).join(' · ')));db.questions.forEach(q=>push('Tutoriales',q.created_at,q.asked_by,q.answered_by||q.asked_by,'Consulta interna · '+q.status,q.question));db.leavePeriods.forEach(x=>push('Vacaciones',x.created_at,x.user_id,x.created_by,absenceTypeName(x.leave_type_code),`${x.start_date} → ${x.end_date} · ${Number(x.natural_days||0)} días · ${x.status}`));db.leaveRequests.forEach(x=>push('Vacaciones',x.created_at,x.user_id,x.decided_by||x.user_id,'Solicitud · '+x.status,`${x.start_date} → ${x.end_date} · ${Number(x.natural_days||0)} días`));db.notifications.forEach(x=>push('Avisos',x.created_at,x.target_user_id,x.created_by,'Aviso · '+x.notification_type,x.title));if(isAdmin())db.maintenanceLog.forEach(x=>push('Administración',x.created_at,null,x.actor_user_id,x.action,`${x.scope||''} · ${x.detail||''}`));return rows.sort((a,b)=>new Date(b.at)-new Date(a.at));
}
function generalLogFilter(){const d=defaultReportDates();return{uid:document.getElementById('logUser')?.value||state.logUserId||'',from:document.getElementById('logFrom')?.value||state.logFrom||d.from,to:document.getElementById('logTo')?.value||state.logTo||d.to,module:document.getElementById('logModule')?.value||state.logModule||''}}
function filteredGeneralLog(){const f=generalLogFilter(),qv=(state.logSearch||'').trim().toLowerCase();return generalLogRows().filter(x=>(!f.uid||x.user===f.uid||x.actor===f.uid)&&(!f.module||x.module===f.module)&&dateInRange(x.at,f.from,f.to)&&(!qv||[x.module,x.action,x.detail,person(x.user)?.name,person(x.actor)?.name].join(' ').toLowerCase().includes(qv)))}
function renderGeneralLog(){const m=document.getElementById('main');if(state.sub==='maintenance'){m.innerHTML=maintenanceHtml();return}const d=defaultReportDates(),rows=generalLogRows();m.innerHTML=`<div class="head"><div><div class="eyebrow">Log general</div><h1>Histórico de movimientos</h1><p>Visión transversal de lo ocurrido en Totus Central. Los logs operativos son inmutables.</p></div></div><div class="card"><div class="form-grid"><div class="span2"><label>Buscar</label><input value="${esc(state.logSearch||'')}" placeholder="Acción, detalle, módulo…" oninput="state.logSearch=this.value;applyGeneralLogFilter()"></div><div><label>Usuario</label><select id="logUser"><option value="">${isAdmin()?'Todos':'Mi usuario'}</option>${isAdmin()?db.people.map(p=>`<option value="${p.id}" ${state.logUserId===p.id?'selected':''}>${esc(p.name)}</option>`).join(''):''}</select></div><div><label>Módulo</label><select id="logModule"><option value="">Todos</option>${['Fichajes','Tareas','Compras','Precios','Usuarios','Tutoriales','Vacaciones','Avisos','Informes','Administración'].map(x=>`<option value="${x}" ${state.logModule===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label>Desde</label><input id="logFrom" type="date" value="${state.logFrom||d.from}"></div><div><label>Hasta</label><input id="logTo" type="date" value="${state.logTo||d.to}"></div></div><div class="actions" style="margin-top:12px"><button class="primary" onclick="applyGeneralLogFilter()">Aplicar</button><button class="secondary" onclick="exportGeneralLog()">Exportar CSV</button><button class="secondary" onclick="printGeneralLog()">Imprimir</button></div></div><div class="card" style="margin-top:12px"><div class="section-head"><h3>Movimientos</h3><span class="badge info" id="generalLogCount">${rows.length}</span></div><div id="generalLogTable" style="margin-top:10px">${generalLogTableHtml(rows)}</div></div>`}
function applyGeneralLogFilter(){const f=generalLogFilter();Object.assign(state,{logUserId:f.uid,logFrom:f.from,logTo:f.to,logModule:f.module});const rows=filteredGeneralLog(),e=document.getElementById('generalLogTable'),c=document.getElementById('generalLogCount');if(e)e.innerHTML=generalLogTableHtml(rows);if(c)c.textContent=String(rows.length)}
function generalLogTableHtml(rows){return `<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Módulo</th><th>Usuario</th><th>Actor</th><th>Acción</th><th>Detalle</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dt(x.at)}</td><td>${esc(x.module)}</td><td>${esc(person(x.user)?.name||'')}</td><td>${esc(person(x.actor)?.name||'Sistema')}</td><td>${esc(x.action)}</td><td class="small">${esc(x.detail||'')}</td></tr>`).join('')||'<tr><td colspan="6" class="small">Sin movimientos para este filtro.</td></tr>'}</tbody></table></div>`}
function exportGeneralLog(){const rows=filteredGeneralLog();downloadCsv('log_general_totus.csv',['Fecha','Módulo','Usuario','Actor','Acción','Detalle'],rows.map(x=>[x.at,x.module,person(x.user)?.name||'',person(x.actor)?.name||'Sistema',x.action,x.detail||'']))}
function printGeneralLog(){const rows=filteredGeneralLog();printSimpleLog('Log general Totus Central',['Fecha','Módulo','Usuario','Actor','Acción','Detalle'],rows.map(x=>[x.at,x.module,person(x.user)?.name||'',person(x.actor)?.name||'Sistema',x.action,x.detail||'']))}

function applyHoursTemplate(kind,target){const t=db.settings.seasonal_hours_templates?.[kind];if(!t)return notifyMsg('Plantilla no disponible.','warn');modal(`<div class="section-head"><div><div class="eyebrow">Plantilla ${esc(t.label)}</div><h3>Elige los días a los que aplicar estas horas</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="note" style="margin-top:10px">Tramo 1: ${esc(t.shift1)} · Tramo 2: ${esc(t.shift2)}. No se activa ningún día automáticamente.</div><div class="weekday-picks" style="margin-top:14px">${WEEK_LONG.map((x,i)=>`<label><input type="checkbox" class="tplDay" value="${i+1}">${esc(x)}</label>`).join('')}</div><div class="actions" style="margin-top:14px"><button class="primary" onclick="commitHoursTemplate('${kind}','${target}')">Aplicar a días seleccionados</button></div>`) }




function updateWorkReportPreview(){const f=reportFilter(),e=document.getElementById('reportPreview');if(e)e.innerHTML=workReportPreview(f.uid,f.from,f.to,f.loc)}
function printReconciliationRange(){const f=reportFilter(),users=filteredUsers(f.uid),rows=[];for(const uid of users)for(const day of dateRangeDays(f.from,f.to)){const r=workdayReconciliationLocal(uid,day,f.loc);if(r.attendance||r.accounted||r.personal)rows.push([person(uid)?.name||'',day,f.loc?locationName(f.loc):'Todas',Math.round(r.attendance),Math.round(r.taskMin),Math.round(r.workInt),Math.round(r.personal),Math.round(r.unaccounted),r.categories.map(([k,v])=>`${k}: ${Math.round(v)} min`).join(' | ')])}printSimpleLog('Conciliación jornada / tareas',['Empleado','Fecha','Tienda','Jornada min','Tareas min','Laboral min','Personal min','Sin asignar min','Categorías'],rows)}
function commitHoursTemplate(kind,target){const t=db.settings.seasonal_hours_templates?.[kind],days=[...document.querySelectorAll('.tplDay:checked')].map(x=>Number(x.value));if(!t||!days.length)return notifyMsg('Selecciona al menos un día.','warn');const cls=target==='opening'?'.open-sch':'.sch';for(const el of document.querySelectorAll(cls)){const wd=Number(el.dataset.wd);if(!days.includes(wd))continue;const sh=Number(el.dataset.shift),k=el.dataset.kind;if(sh===1)el.value=(k==='start'?t.shift1.split('-')[0]:t.shift1.split('-')[1]);if(sh===2)el.value=(k==='start'?t.shift2.split('-')[0]:t.shift2.split('-')[1])}closeModal();notifyMsg(`${t.label} aplicado a ${days.length} días. Revisa fechas y guarda la temporada.`)}

/* Funcionalidad consolidada */
function uniqBy(arr,keyFn){const seen=new Set();return arr.filter(x=>{const k=keyFn(x);if(seen.has(k))return false;seen.add(k);return true})}
function schedulePeriods(uid){return uniqBy(db.schedules.filter(x=>x.user_id===uid).slice().sort((a,b)=>String(b.valid_from||'').localeCompare(String(a.valid_from||''))),x=>[x.valid_from||'',x.valid_to||'',x.location_id||'',x.season_name||'Base'].join('|'))}
function schedulePeriodKey(x){return [x.valid_from||'',x.valid_to||'',x.location_id||'',x.season_name||'Base'].join('|')}
function ensureScheduleSelection(uid){const periods=schedulePeriods(uid);const exists=periods.find(x=>(x.valid_from||'')===state.scheduleFrom&&(x.location_id||'')===(state.scheduleLocationId||''));if(exists){state.scheduleSeason=exists.season_name||'Base';state.scheduleTo=exists.valid_to||'';return exists}const today=dayIsoLocal(new Date());const active=periods.find(x=>(!x.valid_from||x.valid_from<=today)&&(!x.valid_to||x.valid_to>=today))||periods[0];if(active){state.scheduleFrom=active.valid_from||today;state.scheduleTo=active.valid_to||'';state.scheduleSeason=active.season_name||'Base';state.scheduleLocationId=active.location_id||'';return active}state.scheduleFrom=state.scheduleFrom||today;state.scheduleTo=state.scheduleTo||'';state.scheduleSeason=state.scheduleSeason||'Base';state.scheduleLocationId=state.scheduleLocationId||db.locations[0]?.id||'';return null}
function setSchedulePeriod(v){const [from,to,loc,...seasonParts]=String(v||'').split('|');state.scheduleFrom=from||dayIsoLocal(new Date());state.scheduleTo=to||'';state.scheduleLocationId=loc||'';state.scheduleSeason=seasonParts.join('|')||'Base';renderTasks()}
function schedulePeriodPicker(uid){const periods=schedulePeriods(uid);if(!periods.length)return '<div class="small">Aún no hay temporadas guardadas para este empleado.</div>';return `<label>Temporadas guardadas</label><select onchange="setSchedulePeriod(this.value)">${periods.map(x=>`<option value="${esc(schedulePeriodKey(x))}" ${(x.valid_from||'')===state.scheduleFrom&&(x.location_id||'')===(state.scheduleLocationId||'')?'selected':''}>${esc(x.season_name||'Base')} · ${esc(locationName(x.location_id))} · ${esc(x.valid_from||'')} → ${esc(x.valid_to||'sin fin')}</option>`).join('')}</select>`}
function scheduleSeasonControls(uid,can){ensureScheduleSelection(uid);return `<div class="season-toolbar"><div>${schedulePeriodPicker(uid)}</div><div><label>Nombre temporada</label><input id="seasonName" value="${esc(state.scheduleSeason||'Base')}" ${can?'':'disabled'}></div><div><label>Desde</label><input id="seasonFrom" type="date" value="${esc(state.scheduleFrom||dayIsoLocal(new Date()))}" ${can?'':'disabled'}></div><div><label>Hasta</label><input id="seasonTo" type="date" value="${esc(state.scheduleTo||'')}" ${can?'':'disabled'}></div><div><label>Tienda obligatoria</label><select id="seasonLocation" ${can?'':'disabled'}>${db.locations.map(l=>`<option value="${l.id}" ${state.scheduleLocationId===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div></div>`}
function scheduleExceptionList(uid){const rows=db.scheduleExceptions.filter(x=>x.user_id===uid).slice().sort((a,b)=>String(b.work_date).localeCompare(String(a.work_date))).slice(0,20);return rows.map(x=>`<div class="row"><div class="grow"><b>${esc(x.work_date)}</b> · tramo ${Number(x.shift_index||1)}<div class="small">${x.is_day_off?'Día libre / sin turno':`${esc(String(x.start_time||'').slice(0,5))}–${esc(String(x.end_time||'').slice(0,5))} · ${esc(locationName(x.location_id))}`} ${x.reason?`· ${esc(x.reason)}`:''}</div></div><span class="badge ${x.is_day_off?'warnb':'info'}">EXCEPCIÓN</span></div>`).join('')||'<div class="small">Sin excepciones registradas.</div>'}
function newScheduleException(uid){if(!isAdmin())return;modal(`<div class="section-head"><div><div class="eyebrow">Excepción de turno</div><h3>Cambio puntual de jornada</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid" style="margin-top:12px"><div><label>Fecha</label><input id="excDate" type="date" value="${dayIsoLocal(new Date())}"></div><div><label>Tramo</label><select id="excShift"><option value="1">1</option><option value="2">2</option><option value="3">3</option><option value="4">4</option></select></div><div><label>Entrada</label><input id="excStart" type="time"></div><div><label>Salida</label><input id="excEnd" type="time"></div><div class="span2"><label>Tienda</label><select id="excLoc">${db.locations.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></div><div class="span2"><label>Motivo</label><input id="excReason" placeholder="Cambio puntual, cita, refuerzo, vacaciones..."></div><div class="span4"><label class="check-line"><input id="excOff" type="checkbox"> Día libre / no debe trabajar</label></div></div><div class="actions" style="margin-top:12px"><button class="primary" onclick="saveScheduleException('${uid}')">Guardar excepción</button></div>`)}
async function saveScheduleException(uid){const date=document.getElementById('excDate').value,shift=Number(document.getElementById('excShift').value),off=document.getElementById('excOff').checked,st=document.getElementById('excStart').value,en=document.getElementById('excEnd').value,loc=document.getElementById('excLoc').value||null,reason=document.getElementById('excReason').value.trim();if(!date)return notifyMsg('Indica la fecha.','warn');if(!off&&!loc)return notifyMsg('Indica la tienda donde se prestará servicio.','warn');if(!off&&(!st||!en||en<=st))return notifyMsg('Indica entrada y salida válidas.','warn');const row={user_id:uid,work_date:date,shift_index:shift,is_day_off:off,start_time:off?null:st,end_time:off?null:en,location_id:off?null:loc,reason:reason||null,created_by:me().id,updated_at:new Date().toISOString()};const {error}=await sb.from('employee_schedule_exceptions').upsert(row,{onConflict:'user_id,work_date,shift_index'});if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderTasks();notifyMsg('Excepción de horario guardada.')}

function openingPeriods(loc){return uniqBy(db.openingHours.filter(x=>x.location_id===loc).slice().sort((a,b)=>String(b.valid_from||'').localeCompare(String(a.valid_from||''))),x=>[x.valid_from||'',x.valid_to||'',x.season_name||'Base'].join('|'))}
function ensureOpeningSelection(loc){state.openingLocationId=loc||state.openingLocationId||db.locations[0]?.id||'';const ps=openingPeriods(state.openingLocationId);const today=dayIsoLocal(new Date());let p=ps.find(x=>(x.valid_from||'')===state.openingFrom)||ps.find(x=>x.valid_from<=today&&(!x.valid_to||x.valid_to>=today))||ps[0];if(p){state.openingFrom=p.valid_from;state.openingTo=p.valid_to||'';state.openingSeason=p.season_name||'Base'}else{state.openingFrom=state.openingFrom||today;state.openingTo=state.openingTo||'';state.openingSeason=state.openingSeason||'Base'}return p}
function setOpeningLocation(v){state.openingLocationId=v;state.openingFrom='';ensureOpeningSelection(v);renderTasks()}
function setOpeningPeriod(v){const [from,to,...season]=String(v||'').split('|');state.openingFrom=from||dayIsoLocal(new Date());state.openingTo=to||'';state.openingSeason=season.join('|')||'Base';renderTasks()}
function activeOpeningRows(){return db.openingHours.filter(x=>x.location_id===state.openingLocationId&&x.valid_from===state.openingFrom)}
function openingEditor(can){
 const rows=activeOpeningRows(),time=(label,wd,shift,kind,value)=>`<label class="schedule-time-field"><span>${label}</span><input class="open-sch" aria-label="${WEEK_LONG[wd-1]} ${label.toLowerCase()}" data-wd="${wd}" data-shift="${shift}" data-kind="${kind}" type="time" value="${value||''}" ${can?'':'disabled'}></label>`;
 let out='<div class="schedule-grid opening-grid" style="margin-top:12px"><div class="sh">Día</div><div class="sh">Apertura 1</div><div class="sh">Cierre 1</div><div class="sh">Apertura 2</div><div class="sh">Cierre 2</div>';
 for(let wd=1;wd<=7;wd++){
  const a=rows.find(x=>Number(x.weekday)===wd&&Number(x.shift_index)===1&&x.active),b=rows.find(x=>Number(x.weekday)===wd&&Number(x.shift_index)===2&&x.active);
  out+=`<div class="schedule-row"><div class="schedule-day">${WEEK_LONG[wd-1]}</div>${time('Apertura 1',wd,1,'start',a?.open_time?.slice(0,5))}${time('Cierre 1',wd,1,'end',a?.close_time?.slice(0,5))}${time('Apertura 2',wd,2,'start',b?.open_time?.slice(0,5))}${time('Cierre 2',wd,2,'end',b?.close_time?.slice(0,5))}</div>`;
 }
 return out+'</div>';
}
function openingHoursAdminHtml(){if(!isAdmin()||!db.locations.length)return'';ensureOpeningSelection(state.openingLocationId||db.locations[0].id);const ps=openingPeriods(state.openingLocationId);return `<details class="audit-details" style="margin-top:12px"><summary>Horarios de apertura por temporada</summary><div class="card audit-card"><div class="season-toolbar"><div><label>Tienda</label><select onchange="setOpeningLocation(this.value)">${db.locations.map(l=>`<option value="${l.id}" ${state.openingLocationId===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div><div><label>Temporadas guardadas</label><select onchange="setOpeningPeriod(this.value)"><option value="">Nueva temporada</option>${ps.map(x=>`<option value="${esc([x.valid_from,x.valid_to||'',x.season_name||'Base'].join('|'))}" ${x.valid_from===state.openingFrom?'selected':''}>${esc(x.season_name||'Base')} · ${esc(x.valid_from)} → ${esc(x.valid_to||'sin fin')}</option>`).join('')}</select></div><div><label>Nombre temporada</label><input id="openSeasonName" value="${esc(state.openingSeason||'Base')}"></div><div><label>Desde</label><input id="openSeasonFrom" type="date" value="${esc(state.openingFrom||dayIsoLocal(new Date()))}"></div><div><label>Hasta</label><input id="openSeasonTo" type="date" value="${esc(state.openingTo||'')}"></div></div><div class="actions" style="margin:8px 0"><button class="ghost" onclick="applyHoursTemplate('winter','opening')">Cargar horas invierno</button><button class="ghost" onclick="applyHoursTemplate('summer','opening')">Cargar horas verano</button></div>${openingEditor(true)}<div class="actions" style="margin-top:12px"><button class="primary" onclick="saveOpeningHoursPeriod()">Guardar temporada de apertura</button><button class="secondary" onclick="newOpeningException()">+ Excepción de apertura</button></div><div class="list" style="margin-top:12px">${openingExceptionList()}</div></div></details>`}
async function saveOpeningHoursPeriod(){const loc=state.openingLocationId,name=document.getElementById('openSeasonName').value.trim()||'Temporada',from=document.getElementById('openSeasonFrom').value,to=document.getElementById('openSeasonTo').value||null,els=[...document.querySelectorAll('.open-sch')],rows=[];if(!loc||!from)return notifyMsg('Indica tienda y fecha de inicio.','warn');if(to&&to<from)return notifyMsg('La fecha final no puede ser anterior.','warn');for(let wd=1;wd<=7;wd++)for(let sh=1;sh<=2;sh++){const st=els.find(e=>+e.dataset.wd===wd&&+e.dataset.shift===sh&&e.dataset.kind==='start')?.value,en=els.find(e=>+e.dataset.wd===wd&&+e.dataset.shift===sh&&e.dataset.kind==='end')?.value;if(!st&&!en)continue;if(!st||!en||en<=st)return notifyMsg(`Horario de apertura incompleto en ${WEEK_LONG[wd-1]} tramo ${sh}.`,'warn');rows.push({weekday:wd,shift_index:sh,open_time:st,close_time:en,active:true,notes:null})}const {error}=await sb.rpc('replace_location_opening_period',{p_location_id:loc,p_valid_from:from,p_valid_to:to,p_season_name:name,p_rows:rows});if(error)return notifyMsg(error.message,'bad');state.openingFrom=from;state.openingTo=to||'';state.openingSeason=name;await reloadTeamData();renderTasks();notifyMsg('Temporada de apertura guardada.')}
function openingExceptionList(){const rows=db.openingExceptions.filter(x=>x.location_id===state.openingLocationId).slice().sort((a,b)=>String(b.open_date).localeCompare(String(a.open_date))).slice(0,16);return rows.map(x=>`<div class="row"><div class="grow"><b>${esc(x.open_date)}</b> · tramo ${Number(x.shift_index||1)}<div class="small">${x.is_closed?'CERRADO':`${esc(String(x.open_time||'').slice(0,5))}–${esc(String(x.close_time||'').slice(0,5))}`} ${x.reason?`· ${esc(x.reason)}`:''}</div></div><span class="badge ${x.is_closed?'badb':'info'}">EXCEPCIÓN</span></div>`).join('')||'<div class="small">Sin excepciones de apertura.</div>'}
function newOpeningException(){if(!isAdmin())return;modal(`<div class="section-head"><div><div class="eyebrow">Excepción de apertura</div><h3>${esc(locationName(state.openingLocationId))}</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid" style="margin-top:12px"><div><label>Fecha</label><input id="openExcDate" type="date" value="${dayIsoLocal(new Date())}"></div><div><label>Tramo</label><select id="openExcShift"><option value="1">1</option><option value="2">2</option><option value="3">3</option><option value="4">4</option></select></div><div><label>Apertura</label><input id="openExcStart" type="time"></div><div><label>Cierre</label><input id="openExcEnd" type="time"></div><div class="span4"><label class="check-line"><input id="openExcClosed" type="checkbox"> Tienda cerrada ese tramo/día</label></div><div class="span4"><label>Motivo</label><input id="openExcReason" placeholder="Festivo, inventario, horario especial..."></div></div><div class="actions" style="margin-top:12px"><button class="primary" onclick="saveOpeningException()">Guardar excepción</button></div>`)}
async function saveOpeningException(){const loc=state.openingLocationId,date=document.getElementById('openExcDate').value,shift=Number(document.getElementById('openExcShift').value),closed=document.getElementById('openExcClosed').checked,st=document.getElementById('openExcStart').value,en=document.getElementById('openExcEnd').value,reason=document.getElementById('openExcReason').value.trim();if(!loc||!date)return notifyMsg('Indica tienda y fecha.','warn');if(!closed&&(!st||!en||en<=st))return notifyMsg('Indica apertura y cierre válidos.','warn');const {error}=await sb.from('location_opening_exceptions').upsert({location_id:loc,open_date:date,shift_index:shift,is_closed:closed,open_time:closed?null:st,close_time:closed?null:en,reason:reason||null,created_by:me().id,updated_at:new Date().toISOString()},{onConflict:'location_id,open_date,shift_index'});if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderTasks();notifyMsg('Excepción de apertura guardada.')}

function breakCatalogAdminHtml(){if(!isAdmin())return'';const personal=personalBreakTypes(),work=workInterruptionTypes();const row=x=>`<div class="row"><div class="grow"><b>${esc(x.label)}</b><div class="small">${esc(x.code)}${x.requires_note?' · exige nota':''}${Number(x.expected_minutes||0)>0?' · previsto '+Number(x.expected_minutes)+' min':''}</div></div><span class="badge ${x.counts_as_work?'ok':'badb'}">${x.counts_as_work?'COMPUTA':'NO COMPUTA'}</span><span class="badge ${x.category==='work'?'info':'warnb'}">${x.category==='work'?'LABORAL':'PERSONAL'}</span>${x.category==='personal'?`<button class="ghost" onclick="setBreakExpected('${esc(x.code)}')">Tiempo</button>`:''}<button class="ghost" onclick="toggleBreakTypeActive('${esc(x.code)}',${x.active===false?'true':'false'})">${x.active===false?'Activar':'Desactivar'}</button></div>`;return `<details class="audit-details" style="margin-top:12px"><summary>Catálogo de paradas e interrupciones · ${db.breakTypes.filter(x=>x.active!==false).length}</summary><div class="card audit-card"><div class="section-head"><div><h3>Motivos disponibles</h3><div class="small">Personal = NO COMPUTA. Laboral = COMPUTA. El admin puede ampliar el catálogo sin una nueva versión.</div></div><button class="primary" onclick="newBreakType()">+ Motivo</button></div><div class="grid g2" style="margin-top:12px"><div><div class="eyebrow">Paradas personales</div><div class="list">${personal.map(row).join('')}</div></div><div><div class="eyebrow">Interrupciones laborales</div><div class="list">${work.map(row).join('')}</div></div></div></div></details>`}
function newBreakType(){if(!isAdmin())return;modal(`<div class="section-head"><h3>Nuevo motivo de parada</h3><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid" style="margin-top:12px"><div class="span2"><label>Nombre visible</label><input id="btLabel" placeholder="Ej. Espera de técnico"></div><div><label>Tipo</label><select id="btCategory"><option value="personal">Personal · NO COMPUTA</option><option value="work">Laboral · COMPUTA</option></select></div><div><label>Tiempo previsto · min</label><input id="btExpected" type="number" min="0" max="1440" value="5"></div><div class="span2"><label class="check-line"><input id="btNote" type="checkbox"> Exigir nota</label></div></div><div class="note" style="margin-top:10px">La regla no se puede invertir: toda parada personal descuenta y toda interrupción laboral computa.</div><div class="actions" style="margin-top:12px"><button class="primary" onclick="saveBreakType()">Guardar motivo</button></div>`)}
async function saveBreakType(){const label=document.getElementById('btLabel').value.trim(),cat=document.getElementById('btCategory').value,note=document.getElementById('btNote').checked,expected=Math.max(0,Math.min(1440,Number(document.getElementById('btExpected')?.value||0)));if(label.length<3)return notifyMsg('Escribe un nombre descriptivo.','warn');let code=label.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,50);if(!code)code='motivo_'+Date.now();if(db.breakTypes.some(x=>x.code===code))code+='_'+Date.now().toString().slice(-4);const max=Math.max(0,...db.breakTypes.map(x=>Number(x.sort_order||0)));const {error}=await sb.from('attendance_break_types').insert({code,label,category:cat,counts_as_work:cat==='work',requires_note:note,expected_minutes:expected,active:true,sort_order:max+10});if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderTasks();notifyMsg('Motivo añadido al catálogo.')}
async function toggleBreakTypeActive(code,active){if(!isAdmin())return;const {error}=await sb.from('attendance_break_types').update({active,updated_at:new Date().toISOString()}).eq('code',code);if(error)return notifyMsg(error.message,'bad');await reloadTeamData();renderTasks();notifyMsg(active?'Motivo activado.':'Motivo desactivado.')}

function taskCategoryAdminHtml(){const rows=db.taskCategories.slice().sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)||String(a.name).localeCompare(String(b.name)));return `<details class="audit-details" style="margin-top:12px"><summary>Categorías de tareas · ${rows.filter(x=>x.active!==false).length} activas</summary><div class="card audit-card"><div class="section-head"><div><h3>Catálogo configurable</h3><div class="small">Las categorías desactivadas se conservan en el histórico pero dejan de ofrecerse en nuevas tareas.</div></div><button class="primary" onclick="newTaskCategory()">+ Categoría</button></div><div class="list" style="margin-top:10px">${rows.map(x=>`<div class="row"><div class="grow"><b>${esc(x.name)}</b><div class="small">${esc(x.code)} · orden ${Number(x.sort_order||0)}</div></div><span class="badge ${x.active!==false?'ok':'warnb'}">${x.active!==false?'ACTIVA':'INACTIVA'}</span><button class="ghost" onclick="toggleTaskCategory('${x.id}',${x.active===false?'true':'false'})">${x.active===false?'Activar':'Desactivar'}</button></div>`).join('')||'<div class="small">Sin categorías.</div>'}</div></div></details>`}
function newTaskCategory(){if(!isAdmin())return;modal(`<div class="section-head"><h3>Nueva categoría de tarea</h3><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid" style="margin-top:12px"><div class="span2"><label>Nombre</label><input id="tcName" placeholder="Ej. Preparación de pedidos web"></div><div><label>Orden</label><input id="tcOrder" type="number" min="0" value="${Math.max(10,...db.taskCategories.map(x=>Number(x.sort_order||0)+10))}"></div></div><div class="actions" style="margin-top:12px"><button class="primary" onclick="saveTaskCategory()">Guardar categoría</button></div>`)}
async function saveTaskCategory(){const name=document.getElementById('tcName').value.trim(),sort_order=Math.max(0,Number(document.getElementById('tcOrder').value||0));if(name.length<3)return notifyMsg('Escribe un nombre descriptivo.','warn');let code=name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,50);if(!code)code='categoria_'+Date.now();if(db.taskCategories.some(x=>x.code===code))code+='_'+Date.now().toString().slice(-4);const {error}=await sb.from('task_categories').insert({code,name,active:true,sort_order});if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderTasks();notifyMsg('Categoría añadida.')}
async function toggleTaskCategory(id,active){if(!isAdmin())return;const {error}=await sb.from('task_categories').update({active,updated_at:new Date().toISOString()}).eq('id',id);if(error)return notifyMsg(error.message,'bad');await reloadTeamData();renderTasks();notifyMsg(active?'Categoría activada.':'Categoría desactivada para nuevas tareas.')}

function workRulesAdminHtml(){if(!isAdmin())return'';const wr=db.settings.work_hours_rules||{},ar=db.settings.attendance_rounding_rules||{},tr=db.settings.task_rules||{};return `<details class="audit-details" style="margin-top:12px"><summary>Reglas operativas configurables</summary><div class="card audit-card"><div class="section-head"><div><h3>Parámetros de trabajo</h3><div class="small">Cambios globales sin necesidad de nueva versión.</div></div></div><div class="form-grid" style="margin-top:10px"><div><label>Objetivo jornada completa · horas/mes</label><input id="cfgFullTimeHours" type="number" min="0" step="0.25" value="${Number(wr.full_time_monthly_minutes||9600)/60}"></div><div><label>Aviso parada personal · min</label><input id="cfgBreakWarn" type="number" min="1" max="240" value="${Number(ar.break_warning_minutes||10)}"></div><div><label>Repetir alarmas · min</label><input id="cfgAlarmRepeat" type="number" min="2" max="240" value="${Number(wr.overdue_alarm_repeat_minutes||10)}"></div><div><label>Recordatorio tarea por defecto · min</label><input id="cfgTaskReminder" type="number" min="0" max="10080" value="${Number(tr.default_reminder_minutes||15)}"></div></div><div class="actions" style="margin-top:12px"><button class="primary" onclick="saveWorkRules()">Guardar reglas</button></div><div class="note" style="margin-top:10px">Las reglas de integridad no son configurables: las pausas personales siempre NO COMPUTAN, las interrupciones laborales siempre COMPUTAN, los logs permanecen inmutables y la firma conserva el total real.</div></div></details>`}
async function saveWorkRules(){if(!isAdmin())return;const full=Math.max(0,Math.round(Number(document.getElementById('cfgFullTimeHours').value||160)*60)),breakWarn=Math.max(1,Math.min(240,Number(document.getElementById('cfgBreakWarn').value||10))),repeat=Math.max(2,Math.min(240,Number(document.getElementById('cfgAlarmRepeat').value||10))),rem=Math.max(0,Math.min(10080,Number(document.getElementById('cfgTaskReminder').value||15))),wr={...(db.settings.work_hours_rules||{}),full_time_monthly_minutes:full,overdue_alarm_repeat_minutes:repeat,signed_report_requires_all_hours:true},ar={...(db.settings.attendance_rounding_rules||{}),break_warning_minutes:breakWarn,subtract_personal_breaks:true,clip_late_exit_to_schedule:true,clip_early_entry_to_schedule:true},tr={...(db.settings.task_rules||{}),default_reminder_minutes:rem,notification_sound:true};const rows=[{key:'work_hours_rules',value:wr,updated_by:me().id,updated_at:new Date().toISOString()},{key:'attendance_rounding_rules',value:ar,updated_by:me().id,updated_at:new Date().toISOString()},{key:'task_rules',value:tr,updated_by:me().id,updated_at:new Date().toISOString()}];const {error}=await sb.from('team_app_settings').upsert(rows,{onConflict:'key'});if(error)return notifyMsg(error.message,'bad');await reloadTeamData();renderTasks();notifyMsg('Reglas operativas actualizadas.')}

function scheduleHtml(){const uid=state.scheduleUserId||me().id,u=person(uid)||me(),can=isAdmin(),hs=monthlyHourState(uid);ensureScheduleSelection(uid);const period=schedulePeriods(uid).find(x=>(x.valid_from||'')===state.scheduleFrom&&(x.location_id||'')===(state.scheduleLocationId||''));const periodSummary=period?`${esc(period.season_name||'Base')} · ${esc(locationName(period.location_id))} · ${esc(period.valid_from||'')} → ${esc(period.valid_to||'sin fin')}`:'Sin temporada laboral guardada';return `<div class="head"><div><div class="eyebrow">Programación</div><h1>Turnos, temporadas y apertura</h1><p>Los turnos del empleado y los horarios de apertura de cada tienda son independientes. Ambos admiten temporadas y excepciones puntuales.</p></div>${can?`<div style="min-width:260px"><label>Empleado</label><select onchange="state.scheduleUserId=this.value;state.scheduleFrom='';renderTasks()">${db.people.filter(p=>p.role!=='invitado').map(p=>`<option value="${p.id}" ${uid===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>`:''}</div><details class="audit-details schedule-main-details"><summary>Turno de ${esc(u.name)} · <span class="summary-muted">${periodSummary}</span></summary><div class="card audit-card"><div class="section-head"><div><h3>Turno por temporada</h3><div class="small">Jornada partida, verano/invierno y cambios de vigencia sin borrar temporadas anteriores.</div></div>${can?`<button class="secondary" onclick="newScheduleException('${uid}')">+ Excepción puntual</button>`:''}</div>${scheduleSeasonControls(uid,can)}<details class="audit-details schedule-editor-details" style="margin-top:10px"><summary>${can?'Editar horario semanal':'Ver horario semanal'}</summary><div class="card audit-card">${can?`<div class="actions compact-actions" style="margin-bottom:9px"><button class="ghost" onclick="applyHoursTemplate('winter','work')">Cargar invierno</button><button class="ghost" onclick="applyHoursTemplate('summer','work')">Cargar verano</button></div>`:''}${scheduleEditor(uid,can)}${can?'<div class="actions" style="margin-top:10px"><button class="primary" onclick="saveSchedule()">Guardar temporada laboral</button></div>':''}</div></details><div class="list" style="margin-top:10px">${scheduleExceptionList(uid)}</div></div></details><details class="audit-details schedule-target-details" style="margin-top:12px"><summary>Objetivo mensual · ${fmtHours(hs.target)} <span class="summary-muted">${fmtHours(hs.worked)} realizados</span></summary><div class="card audit-card"><h3>Objetivo mensual ${helpIcon('monthly_target','Cómo funciona el objetivo mensual')}</h3><div class="small" style="margin:5px 0 13px">Por defecto: 160 h para jornada completa. A partir de ahí las horas adicionales se muestran separadas, pero el registro firmado conserva el total real.</div><div class="form-grid"><div class="span2"><label>Mes</label><input id="targetMonth" type="month" value="${monthKey(new Date()).slice(0,7)}"></div><div><label>Objetivo mensual · horas</label><input id="targetHours" type="number" min="0" step="0.25" value="${targetValueHours(uid)}" ${can?'':'disabled'}></div><div><label>Referencia por turnos vigentes</label><input disabled value="${fmtHours(monthlyTargetFromSchedule(uid,new Date()))}"></div></div>${can?'<div class="actions"><button class="secondary" onclick="saveMonthlyTarget()">Guardar objetivo</button><button class="ghost" onclick="setTargetFullTime()">Restablecer 160 h</button></div>':''}${hoursCountdownHtml(uid)}<div class="note" style="margin-top:12px">Entrar antes o salir después queda visible pero no suma fuera del turno. Llegar tarde, salir antes y las paradas personales NO computables descuentan.</div></div></details>${can?openingHoursAdminHtml()+breakCatalogAdminHtml()+taskCategoryAdminHtml()+workRulesAdminHtml()+scheduleLocalLogHtml():''}${holidayAdminPanelHtml()}`}


function checkReminders(){
 attendanceWarnings(true);
 const uid=me()?.id;if(!uid)return;
 const now=Date.now(),repeat=Math.max(2,Number(db.settings.work_hours_rules?.overdue_alarm_repeat_minutes||10))*60000;
 for(const t of db.tasks.filter(x=>x.assigned_to===uid&&!['done','cancelled'].includes(x.status))){
  const at=new Date(t.due_at||t.starts_at||0).getTime();if(!at)continue;
  const remind=Math.max(0,Number(t.reminder_minutes??15))*60000,delta=at-now;
  if(delta<=remind){const bucket=delta<0?Math.floor(Math.abs(delta)/repeat):0,key=`task-${t.id}-${delta<0?'late':'soon'}-${bucket}`;if(!state.remindersSeen.has(key)){state.remindersSeen.add(key);const late=delta<0,msg=late?`Tarea vencida: ${t.title} · ${Math.max(1,Math.round(Math.abs(delta)/60000))} min de retraso.`:`Próxima tarea: ${t.title} · en ${Math.max(0,Math.round(delta/60000))} min.`;notifyMsg(msg,late?'bad':'warn',9000);browserNotify(late?'Totus · Tarea vencida':'Totus · Próxima tarea',msg);beep(late?'danger':'alert')}}
 }
 const br=openPersonalBreak();if(br){const warnMin=breakWarningMinutes(br),warn=warnMin*60000,elapsed=now-new Date(br.started_at).getTime();if(elapsed>=warn){const bucket=Math.floor((elapsed-warn)/repeat),key=`personal-break-long-${br.id}-${warnMin}-${bucket}`;if(!state.remindersSeen.has(key)){state.remindersSeen.add(key);const msg=`Parada personal abierta: ${breakName(br.break_type)} · ${fmtDur(elapsed/1000)} · previsto ${warnMin} min. Finalízala al volver al trabajo.`;notifyMsg(msg,'bad',10000);browserNotify('Totus · Parada personal abierta',msg);beep('danger')}}}
 for(const x of myNotifications().filter(x=>!x.read_at&&x.sound)){const key=`notice-${x.id}`;if(!state.remindersSeen.has(key)){state.remindersSeen.add(key);notifyMsg(`${x.title}: ${x.message}`,x.notification_type==='atencion'?'bad':'warn',10000);browserNotify(`Totus · ${x.title}`,x.message);beep(x.notification_type==='atencion'?'danger':'alert')}}
}


function setBreakExpected(code){if(!isAdmin())return;const x=breakType(code);if(!x)return;modal(`<div class="section-head"><div><div class="eyebrow">Tiempo previsto</div><h3>${esc(x.label)}</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid" style="margin-top:12px"><div class="span2"><label>Minutos previstos</label><input id="breakExpectedEdit" type="number" min="0" max="1440" value="${Number(x.expected_minutes||0)}"></div></div><div class="note" style="margin-top:10px">La herramienta mostrará además la media real histórica de cada empleado para comparar el tiempo previsto con el utilizado.</div><div class="actions" style="margin-top:12px"><button class="primary" onclick="saveBreakExpected('${esc(code)}')">Guardar</button></div>`) }
async function saveBreakExpected(code){if(!isAdmin())return;const expected=Math.max(0,Math.min(1440,Number(document.getElementById('breakExpectedEdit')?.value||0)));const {error}=await sb.from('attendance_break_types').update({expected_minutes:expected,updated_at:new Date().toISOString()}).eq('code',code);if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderTasks();notifyMsg('Tiempo previsto actualizado.')}

// Funcionalidad consolidada
function breakAverageMinutes(uid,code){const rows=db.breaks.filter(x=>x.user_id===uid&&x.break_type===code&&x.ended_at);if(!rows.length)return 0;return Math.round(rows.reduce((a,x)=>a+elapsedSec(x.started_at,x.ended_at)/60,0)/rows.length)}
function breakSuggestedMinutes(uid,code){const avg=breakAverageMinutes(uid,code),configured=Number(breakType(code)?.expected_minutes||0);return avg>0?avg:configured}
function breakWarningMinutes(br){return Math.max(1,Number(br?.expected_minutes||breakType(br?.break_type)?.expected_minutes||db.settings.attendance_rounding_rules?.break_warning_minutes||10))}
function phonePersonalMinutes(uid,date=new Date()){const[start,end]=monthBoundsLocal(date),now=new Date();return db.breaks.filter(x=>x.user_id===uid&&!x.counts_as_work&&isPhoneActivityCode(x.break_type)).reduce((a,x)=>a+intervalMinutesWithin(x.started_at,x.ended_at,start,end,now),0)}
function adminTimeControlHtml(uid){if(!isAdmin())return'';const u=person(uid),att=db.attendance.find(x=>x.user_id===uid&&!x.clock_out),br=db.breaks.find(x=>x.user_id===uid&&!x.ended_at),types=personalBreakTypes();return `<div class="card" style="margin-top:12px"><div class="section-head"><div><div class="eyebrow">Control administrativo</div><h3>Registrar una parada observada · ${esc(u?.name||'Empleado')}</h3><div class="small">El administrador puede iniciar o finalizar una parada personal del empleado. Queda registrada como iniciada por admin, con tiempo previsto y duración real.</div></div>${br?`<span class="badge badb">ACTIVA · ${esc(breakName(br.break_type))}</span>`:`<span class="badge ${att?'ok':'warnb'}">${att?'JORNADA ABIERTA':'SIN FICHAJE'}</span>`}</div>${br?`<div class="note bad-note"><b>${esc(breakName(br.break_type))}</b> desde ${dt(br.started_at)} · ${fmtDur(elapsedSec(br.started_at))}${Number(br.expected_minutes||0)>0?` · previsto ${br.expected_minutes} min`:''}</div><div class="actions" style="margin-top:10px"><button class="danger" onclick="adminStopPersonalBreak('${uid}')">Finalizar parada</button></div>`:`<div class="form-grid" style="margin-top:10px"><div><label>Tipo</label><select id="adminBreakType" onchange="adminBreakTypeChanged('${uid}')">${types.map(x=>`<option value="${esc(x.code)}" data-expected="${Number(x.expected_minutes||0)}">${esc(x.label)}</option>`).join('')}</select></div><div><label>Tiempo previsto · min</label><input id="adminBreakExpected" type="number" min="0" max="1440" value="${breakSuggestedMinutes(uid,types[0]?.code)||0}"><div class="small" id="adminBreakEstimateHint">Sugerencia automática: media histórica si existe; si no, valor configurado.</div></div><div class="span2"><label>Detalle / motivo</label><input id="adminBreakNote" placeholder="Ej. uso de móvil personal observado / cigarro"></div></div><div class="actions" style="margin-top:10px"><button class="danger" ${att?'':'disabled'} onclick="adminStartPersonalBreak('${uid}')">Iniciar control</button></div>`}<div class="stats" style="margin-top:12px"><div class="stat"><small>Teléfono personal · mes</small><strong>${fmtHours(phonePersonalMinutes(uid))}</strong></div>${types.slice(0,4).map(x=>`<div class="stat"><small>Media ${esc(x.label)}</small><strong>${breakAverageMinutes(uid,x.code)||0} min</strong></div>`).join('')}</div></div>`}
function adminBreakTypeChanged(uid){const s=document.getElementById('adminBreakType'),o=s?.selectedOptions?.[0],inp=document.getElementById('adminBreakExpected'),hint=document.getElementById('adminBreakEstimateHint');if(inp&&o){const configured=Number(o.dataset.expected||0),avg=breakAverageMinutes(uid,o.value);inp.value=avg>0?avg:configured;if(hint)hint.textContent=avg>0?`Media real de este empleado: ${avg} min · configurado: ${configured||0} min`:`Sin media todavía · configurado: ${configured||0} min`}}
async function adminStartPersonalBreak(uid){if(!isAdmin())return;const type=document.getElementById('adminBreakType')?.value,note=document.getElementById('adminBreakNote')?.value.trim()||'',expected=Math.max(0,Math.min(1440,Number(document.getElementById('adminBreakExpected')?.value||0))),bt=breakType(type);if(bt?.requires_note&&note.length<5)return notifyMsg('Describe el motivo de la parada.','warn');const {error}=await sb.rpc('admin_personal_break_start',{p_user_id:uid,p_break_type:type,p_notes:note||null,p_expected_minutes:expected});if(error)return notifyMsg(error.message,'bad');await reloadTeamData();renderTasks();notifyMsg(`Control iniciado para ${person(uid)?.name||'empleado'} · ${breakName(type)}.`,'warn')}
async function adminStopPersonalBreak(uid){if(!isAdmin())return;const {error}=await sb.rpc('admin_personal_break_stop',{p_user_id:uid});if(error)return notifyMsg(error.message,'bad');await reloadTeamData();renderTasks();notifyMsg(`Parada finalizada para ${person(uid)?.name||'empleado'}.`)}

function libraryCategoryName(c){return ({protocolo:'Protocolo',tutorial:'Tutorial',consulta:'Consulta',documento:'Documento',otro:'Otro'}[c]||c)}
function renderLibrary(){const m=document.getElementById('main');if(state.sub==='questions'){m.innerHTML=questionsHtml();return}m.innerHTML=libraryHtml();filterLibrary()}
function libraryHtml(){const rows=db.library||[],status=isAdmin()?state.libraryStatus:'active';return `<div class="head"><div><div class="eyebrow">Biblioteca interna</div><h1>Tutoriales y consultas ${helpIcon('library','Cómo funciona la biblioteca interna')}</h1><p>Protocolos de trabajo, tutoriales de PrestaShop y documentación interna del equipo.</p></div>${isAdmin()?'<button class="primary" onclick="newLibraryItem()">+ Añadir contenido</button>':''}</div><div class="card"><div class="form-grid"><div><label>Buscar</label><input id="librarySearch" placeholder="Título, contenido o descripción" oninput="filterLibrary()"></div><div><label>Categoría</label><select id="libraryCategory" onchange="filterLibrary()"><option value="">Todas</option>${['protocolo','tutorial','consulta','documento','otro'].map(c=>`<option value="${c}">${libraryCategoryName(c)}</option>`).join('')}</select></div>${isAdmin()?`<div><label>Estado</label><select id="libraryStatus" onchange="state.libraryStatus=this.value;filterLibrary()"><option value="active" ${status==='active'?'selected':''}>Activos</option><option value="archived" ${status==='archived'?'selected':''}>Archivados</option><option value="all" ${status==='all'?'selected':''}>Todos</option></select></div>`:''}</div></div><div id="libraryList" class="grid g2" style="margin-top:12px">${libraryRowsHtml(rows)}</div>${libraryLocalLogHtml()}`}
function libraryRowsHtml(rows){return rows.map(x=>`<div class="card library-item" data-search="${esc(((x.title||'')+' '+(x.description||'')+' '+(x.content_text||'')).toLowerCase())}" data-category="${esc(x.category||'')}" data-active="${x.active!==false?'active':'archived'}"><div class="section-head"><div><span class="badge info">${esc(libraryCategoryName(x.category))}</span> ${x.active!==false?'<span class="badge ok">ACTIVO</span>':'<span class="badge warnb">ARCHIVADO</span>'}<h3 style="margin-top:8px">${esc(x.title)}</h3></div>${isAdmin()?`<button class="ghost" onclick="editLibraryItem('${x.id}')">Editar</button>`:''}</div>${x.description?`<p>${esc(x.description)}</p>`:''}${x.content_text?`<div class="note" style="white-space:pre-wrap;max-height:220px;overflow:auto">${esc(x.content_text)}</div>`:''}<div class="actions" style="margin-top:10px">${x.file_path?`<button class="secondary" onclick="openLibraryFile('${x.id}')">Abrir${x.file_name?' · '+esc(x.file_name):''}</button><button class="secondary" onclick="downloadLibraryFile('${x.id}')">Descargar</button>`:''}${x.external_url?`<button class="secondary" onclick="openLibraryLink('${x.id}')">Abrir enlace</button>`:''}</div></div>`).join('')||'<div class="card"><div class="small">Todavía no hay contenidos en la biblioteca.</div></div>'}
function filterLibrary(){const q=(document.getElementById('librarySearch')?.value||'').toLowerCase().trim(),c=document.getElementById('libraryCategory')?.value||'',status=isAdmin()?(document.getElementById('libraryStatus')?.value||state.libraryStatus||'active'):'active';document.querySelectorAll('.library-item').forEach(el=>{const okStatus=status==='all'||el.dataset.active===status;el.style.display=(!q||el.dataset.search.includes(q))&&(!c||el.dataset.category===c)&&okStatus?'':'none'})}
function newLibraryItem(){if(!isAdmin())return;libraryEditor(null)}
function editLibraryItem(id){if(!isAdmin())return;libraryEditor(db.library.find(x=>x.id===id)||null)}
function libraryEditor(x){x=x||{};modal(`<div class="section-head"><div><div class="eyebrow">Biblioteca interna</div><h3>${x.id?'Editar contenido':'Añadir contenido'}</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid" style="margin-top:12px"><div class="span2"><label>Título</label><input id="libTitle" value="${esc(x.title||'')}"></div><div><label>Categoría</label><select id="libCategory">${['protocolo','tutorial','consulta','documento','otro'].map(c=>`<option value="${c}" ${x.category===c?'selected':''}>${libraryCategoryName(c)}</option>`).join('')}</select></div><div><label>Orden</label><input id="libOrder" type="number" value="${Number(x.sort_order||0)}"></div><div class="span2"><label>Descripción</label><input id="libDescription" value="${esc(x.description||'')}"></div><div class="span2"><label>Texto / procedimiento</label><textarea id="libContent" rows="9">${esc(x.content_text||'')}</textarea></div><div class="span2"><label>Enlace externo opcional</label><input id="libUrl" value="${esc(x.external_url||'')}" placeholder="https://..."></div><label class="file-action span2"><b>📎 Archivo opcional</b><span>PDF, documento, imagen o vídeo · máximo 50 MB</span><small class="file-choice-name" id="libFileName">Ningún archivo seleccionado</small><input id="libFile" type="file" onchange="selectedFileName(this,'libFileName')"></label>${x.id?libraryVersionHistoryHtml(x.id):''}<div class="actions" style="margin-top:12px"><button class="primary" onclick="saveLibraryItem('${x.id||''}')">Guardar</button>${x.id?(x.active===false?`<button class="primary" onclick="restoreLibraryItem('${x.id}')">Restaurar</button>`:`<button class="danger" onclick="archiveLibraryItem('${x.id}')">Archivar</button>`):''}</div>`)}
async function saveLibraryItem(id){if(!isAdmin())return;const title=document.getElementById('libTitle').value.trim();if(title.length<3)return notifyMsg('Escribe un título.','warn');const rawUrl=document.getElementById('libUrl').value.trim();if(rawUrl&&!/^https?:\/\//i.test(rawUrl))return notifyMsg('El enlace debe comenzar por http:// o https://.','warn');const existing=id?db.library.find(x=>x.id===id):null,oldPath=existing?.file_path||'',oldName=existing?.file_name||'',file=document.getElementById('libFile')?.files?.[0];let file_path=oldPath||null,file_name=oldName||null,file_type=existing?.file_type||null;if(file&&file.size>50*1024*1024)return notifyMsg('El archivo supera el máximo de 50 MB.','warn');if(file){const safe=(file.name||'archivo').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9._-]+/g,'_');file_path=`${new Date().toISOString().slice(0,10)}/${Date.now()}_${safe}`;const up=await sb.storage.from('internal-library').upload(file_path,file,{upsert:false});if(up.error)return notifyMsg(up.error.message,'bad');file_name=file.name;file_type=file.type||null}const row={title,category:document.getElementById('libCategory').value,description:document.getElementById('libDescription').value.trim()||null,content_text:document.getElementById('libContent').value.trim()||null,external_url:rawUrl||null,file_path,file_name,file_type,sort_order:Number(document.getElementById('libOrder').value||0),updated_by:me().id,updated_at:new Date().toISOString()};let error;if(id){({error}=await sb.from('internal_library').update(row).eq('id',id))}else{row.created_by=me().id;({error}=await sb.from('internal_library').insert(row))}if(error){if(file&&file_path&&file_path!==oldPath)await sb.storage.from('internal-library').remove([file_path]);return notifyMsg(error.message,'bad')}closeModal();await reloadTeamData();renderLibrary();filterLibrary();notifyMsg('Biblioteca actualizada.')}
async function openLibraryFile(id){const x=db.library.find(v=>v.id===id);if(!x?.file_path)return;const {data,error}=await sb.storage.from('internal-library').createSignedUrl(x.file_path,300);if(error)return notifyMsg(error.message,'bad');window.open(data.signedUrl,'_blank','noopener')}
async function downloadStorageFile(bucket,path,name){const {data,error}=await sb.storage.from(bucket).download(path);if(error)throw new Error(error.message);downloadBlob(name||path.split('/').pop()||'archivo',data)}
async function downloadLibraryFile(id){const x=db.library.find(v=>v.id===id);if(!x?.file_path)return;try{await downloadStorageFile('internal-library',x.file_path,x.file_name||'documento')}catch(e){notifyMsg(e.message,'bad')}}
function openLibraryLink(id){const x=db.library.find(v=>v.id===id),url=x?.external_url||'';if(!/^https?:\/\//i.test(url))return notifyMsg('Enlace no válido.','warn');window.open(url,'_blank','noopener')}
function libraryVersionHistoryHtml(id){if(!isAdmin())return'';const item=db.library.find(x=>x.id===id),seen=new Set(),versions=[];if(item?.file_path){seen.add(item.file_path);versions.push({path:item.file_path,name:item.file_name||'Archivo actual',at:item.updated_at||item.created_at,current:true})}for(const a of (db.libraryAudit||[]).filter(a=>a.library_id===id)){const old=a.old_data||{},path=old.file_path;if(path&&!seen.has(path)){seen.add(path);versions.push({path,name:old.file_name||'Versión anterior',at:a.created_at,current:false})}}if(!versions.length)return'';return `<details class="audit-details" style="margin-top:12px"><summary>Versiones de archivo · ${versions.length}</summary><div class="card audit-card"><div class="list">${versions.map(v=>`<div class="list-row"><div><b>${esc(v.name)}</b><div class="small">${v.current?'Actual':'Anterior'} · ${dt(v.at)}</div></div><div class="actions"><button class="secondary" onclick="openLibraryVersion('${v.path}')">Abrir</button><button class="secondary" onclick="downloadLibraryVersion('${v.path}','${esc(v.name)}')">Descargar</button></div></div>`).join('')}</div></div></details>`}
async function openLibraryVersion(path){if(!isAdmin()||!path)return;const {data,error}=await sb.storage.from('internal-library').createSignedUrl(path,300);if(error)return notifyMsg(error.message,'bad');window.open(data.signedUrl,'_blank','noopener')}
async function downloadLibraryVersion(path,name='documento'){try{await downloadStorageFile('internal-library',path,name)}catch(e){notifyMsg(e.message,'bad')}}
function libraryLocalLogHtml(){if(!isAdmin())return'';const rows=(db.libraryAudit||[]).map(a=>({at:a.created_at,user:null,actor:a.actor_user_id,action:'Biblioteca · '+a.action,detail:[a.title,a.detail].filter(Boolean).join(' · ')}));return localLogDetails('Tutoriales y consultas',rows.slice(0,300))}
async function archiveLibraryItem(id){if(!isAdmin())return;if(!await askConfirm({title:'Archivar contenido',message:'Dejará de mostrarse al equipo, pero permanecerá en histórico.',confirmText:'Archivar',danger:true}))return;const {error}=await sb.from('internal_library').update({active:false,updated_by:me().id,updated_at:new Date().toISOString()}).eq('id',id);if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderLibrary();notifyMsg('Contenido archivado.')}
async function restoreLibraryItem(id){if(!isAdmin())return;if(!await askConfirm({title:'Restaurar contenido',message:'Volverá a mostrarse al equipo.',confirmText:'Restaurar'}))return;const {error}=await sb.from('internal_library').update({active:true,updated_by:me().id,updated_at:new Date().toISOString()}).eq('id',id);if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();state.libraryStatus='active';renderLibrary();filterLibrary();notifyMsg('Contenido restaurado.')}


/* === Vacaciones, alarmas y calendario laboral === */
function parseLocalDate(v){return v?new Date(String(v).slice(0,10)+'T12:00:00'):null}
function dateIso(v){return v instanceof Date?dayIsoLocal(v):String(v||'').slice(0,10)}
function naturalDaysOverlap(a,b,from,to){const s=parseLocalDate(a),e=parseLocalDate(b),rs=parseLocalDate(from),re=parseLocalDate(to);if(!s||!e||!rs||!re)return 0;const x=s>rs?s:rs,y=e<re?e:re;return y<x?0:Math.floor((y-x)/86400000)+1}
function dateInPeriod(iso,start,end){return !!iso&&!!start&&!!end&&iso>=start&&iso<=end}
function leaveSettingsFor(uid){return (db.leaveSettings||[]).find(x=>x.user_id===uid)||{user_id:uid,accrual_start_date:null,monthly_rate:2.5,annual_cap:30}}
function leaveYearSummary(uid,year=new Date().getFullYear(),today=new Date()){
 const cfg=leaveSettingsFor(uid),ys=`${year}-01-01`,ye=`${year}-12-31`,todayIso=dateIso(today),effectiveEnd=year<today.getFullYear()?ye:year>today.getFullYear()?null:(todayIso<ye?todayIso:ye);
 let months=0;
 const rawStart=cfg.accrual_start_date||ys,start=rawStart>ys?rawStart:ys;
 if(effectiveEnd&&start<=effectiveEnd){const a=parseLocalDate(start),b=parseLocalDate(effectiveEnd);months=Math.max(0,(b.getFullYear()-a.getFullYear())*12+b.getMonth()-a.getMonth()+1)}
 const rate=Number(cfg.monthly_rate??2.5),cap=Number(cfg.annual_cap??30),generated=Math.min(cap,months*rate);
 const active=(db.leavePeriods||[]).filter(x=>x.user_id===uid&&x.status==='active');
 const vacation=active.filter(x=>x.leave_type_code==='vacation').reduce((n,x)=>n+naturalDaysOverlap(x.start_date,x.end_date,ys,ye),0);
 const gift=active.filter(x=>x.leave_type_code==='gift').reduce((n,x)=>n+naturalDaysOverlap(x.start_date,x.end_date,ys,ye),0);
 const abs=active.filter(x=>!['vacation','gift'].includes(x.leave_type_code)).reduce((n,x)=>n+naturalDaysOverlap(x.start_date,x.end_date,ys,ye),0);
 const locIds=userLocationIds(uid),holidayDates=new Set((db.holidays||[]).filter(h=>h.active!==false&&h.holiday_date>=ys&&h.holiday_date<=ye&&(h.location_id==null||locIds.includes(h.location_id))).map(h=>h.holiday_date));return{year,months,rate,cap,generated,vacation,gift,absences:abs,holidays:holidayDates.size,remaining:Math.max(0,generated-vacation),overused:Math.max(0,vacation-generated),start};
}
function absenceType(code){return (db.leaveTypes||[]).find(x=>x.code===code)}
function absenceTypeName(code){return absenceType(code)?.label||code||'Ausencia'}
function leaveLabel(x){const code=x?.leave_type_code||x?.leave_type||x;return absenceTypeName(code)}
function userLocationIds(uid){
 const ids=new Set(),today=dateIso(new Date());
 db.schedules.filter(x=>x.user_id===uid&&x.active!==false&&(!x.valid_from||x.valid_from<=today)&&(!x.valid_to||x.valid_to>=today)&&x.location_id).forEach(x=>ids.add(x.location_id));
 db.attendance.filter(x=>x.user_id===uid&&x.location_id).slice(0,50).forEach(x=>ids.add(x.location_id));
 const store=(person(uid)?.store||'').toLowerCase();db.locations.filter(l=>store&&(((l.name||'').toLowerCase().includes(store))||((l.code||'').toLowerCase()===store))).forEach(l=>ids.add(l.id));
 return [...ids]
}
function holidayRowsForUserDate(uid,iso){const ids=userLocationIds(uid);return (db.holidays||[]).filter(h=>h.active!==false&&h.holiday_date===iso&&(h.location_id==null||ids.includes(h.location_id)))}
function holidayRowsForDate(iso,locId=null){return (db.holidays||[]).filter(x=>x.active!==false&&x.holiday_date===iso&&(locId==='all'||x.location_id==null||(locId&&x.location_id===locId)))}
function userLeaveOnDate(uid,iso){return (db.leavePeriods||[]).filter(x=>x.user_id===uid&&x.status==='active'&&['vacation','gift'].includes(x.leave_type_code)&&dateInPeriod(iso,x.start_date,x.end_date))}
function userAbsenceOnDate(uid,iso){return (db.leavePeriods||[]).filter(x=>x.user_id===uid&&x.status==='active'&&!['vacation','gift'].includes(x.leave_type_code)&&dateInPeriod(iso,x.start_date,x.end_date))}

function dayCountText(v){const n=Number(v||0),txt=n.toLocaleString('es-ES',{maximumFractionDigits:1});return `${txt} ${Math.abs(n-1)<0.0001?'día':'días'}`}
function leaveSummaryStatsHtml(uid){const y=leaveYearSummary(uid);return `<div class="leave-stats"><div><small>Generados ${helpIcon('vacation_accrual','Cómo se generan las vacaciones')}</small><b>${dayCountText(y.generated)}</b><span>${y.months} mes${y.months===1?'':'es'} × ${y.rate.toLocaleString('es-ES')} · máx. ${y.cap.toLocaleString('es-ES')}</span></div><div><small>Disfrutados</small><b>${dayCountText(y.vacation)}</b><span>Días naturales usados</span></div><div><small>Restantes</small><b class="${y.overused?'bad-text':''}">${dayCountText(y.remaining)}</b><span>${y.overused?`Exceso ${y.overused} días`:'Disponibles este año'}</span></div><div><small>Días regalo</small><b>${dayCountText(y.gift)}</b><span>No consumen vacaciones</span></div><div><small>Otras ausencias</small><b>${dayCountText(y.absences)}</b><span>Médico, gestiones y otros</span></div><div><small>Festivos del año</small><b>${dayCountText(y.holidays)}</b><span>Según tienda asignada</span></div></div>`}
function leaveTimelineRows(uid,limit=8){const rows=[];(db.leavePeriods||[]).filter(x=>x.user_id===uid&&x.status==='active').forEach(x=>{const code=x.leave_type_code,kind=code==='vacation'?'vacation':code==='gift'?'gift':'absence';rows.push({kind,code,label:x.label||leaveLabel(x),start:x.start_date,end:x.end_date,days:Number(x.natural_days||naturalDaysOverlap(x.start_date,x.end_date,x.start_date,x.end_date)),id:x.id,source:'leave'})});return rows.sort((a,b)=>String(b.start).localeCompare(String(a.start))).slice(0,limit)}
function leaveDaysLabel(row){const n=Number(row?.days||0),base=`${n} día${n===1?'':'s'}`;return row?.kind==='vacation'||row?.kind==='gift'?`${base} natural${n===1?'':'es'}`:`${base} registrado${n===1?'':'s'}`}
function leavePanelHtml(uid,compact=true){const rows=leaveTimelineRows(uid,compact?6:40);return `<div class="card panel-widget leave-widget ${compact?'':'wide'}"><div class="section-head"><div><div class="eyebrow">Vacaciones y ausencias</div><h3>${esc(person(uid)?.name||'Empleado')} ${helpIcon('vacation_natural','Qué significa días naturales')}</h3></div><div class="actions"><button class="secondary" onclick="openLeaveManager('${uid}')">${isAdmin()?'Gestionar':'Ver detalle'}</button></div></div>${leaveSummaryStatsHtml(uid)}<div class="leave-timeline">${rows.map(r=>`<div class="leave-row ${r.kind}"><span class="leave-kind">${r.kind==='vacation'?'VACACIONES':r.kind==='gift'?'REGALO':'AUSENCIA'}</span><div class="grow"><b>${esc(r.label)}</b><div class="small">${d(r.start)} → ${d(r.end)} · ${leaveDaysLabel(r)}</div></div>${isAdmin()?`<button class="ghost" onclick="${r.kind==='absence'?`editAbsence('${r.id}')`:`editLeavePeriod('${r.id}')`}">Editar</button>`:''}</div>`).join('')||'<div class="empty-state compact"><b>Sin fechas registradas</b><span>No hay vacaciones, regalos ni ausencias activas.</span></div>'}</div>${leaveRequestsHtml(uid,compact)}</div>`}

function leaveCancelledHistoryHtml(uid){const rows=(db.leavePeriods||[]).filter(x=>x.user_id===uid&&x.status==='cancelled').map(x=>({at:x.cancelled_at||x.updated_at,label:x.label||leaveLabel(x),start:x.start_date,end:x.end_date,days:Number(x.natural_days||naturalDaysOverlap(x.start_date,x.end_date,x.start_date,x.end_date)),reason:x.cancel_reason})).sort((a,b)=>String(b.at).localeCompare(String(a.at)));if(!rows.length)return'';return `<details class="audit-details" style="margin-top:12px"><summary>Períodos cancelados / corregidos · ${rows.length}</summary><div class="card audit-card"><div class="list">${rows.map(x=>`<div class="list-row"><div><b>${esc(x.label)}</b><div class="small">${d(x.start)} → ${d(x.end)} · ${x.days} días · ${esc(x.reason||'Sin motivo')}</div></div><span class="badge warnb">CANCELADO</span></div>`).join('')}</div></div></details>`}
function openLeaveManager(uid){const u=person(uid),rows=leaveTimelineRows(uid,100),admin=isAdmin();modal(`<div class="section-head"><div><div class="eyebrow">Panel del empleado</div><h3>Vacaciones y ausencias · ${esc(u?.name||'Empleado')}</h3><div class="small">Vacaciones = días naturales, incluidos sábados, domingos y festivos. Los días regalo se muestran aparte y no consumen saldo.</div></div><button class="ghost" onclick="closeModal()">Cerrar</button></div>${leaveSummaryStatsHtml(uid)}${admin?`<div class="actions leave-admin-actions"><button class="primary" onclick="newLeavePeriod('${uid}','vacation')">+ Vacaciones</button><button class="secondary" onclick="newLeavePeriod('${uid}','gift')">+ Día regalo</button><button class="secondary" onclick="newAbsence('${uid}')">+ Otra ausencia</button><button class="secondary" onclick="editLeaveSettings('${uid}')">⚙ Saldo / devengo</button><button class="secondary" onclick="manageAbsenceTypes()">⚙ Tipos de ausencia</button></div>`:''}<div class="card leave-manager-list"><div class="section-head"><div><h3>Fechas registradas</h3><div class="small">Cada período se conserva en histórico aunque se cancele.</div></div></div><div class="list">${rows.map(r=>`<div class="list-row"><div><span class="badge ${r.kind==='gift'?'ok':r.kind==='vacation'?'info':'warnb'}">${r.kind==='gift'?'REGALO':r.kind==='vacation'?'VACACIONES':'AUSENCIA'}</span> <b>${esc(r.label)}</b><div class="small">${d(r.start)} → ${d(r.end)} · ${leaveDaysLabel(r)}</div></div>${admin?`<button class="secondary" onclick="${r.kind==='absence'?`editAbsence('${r.id}')`:`editLeavePeriod('${r.id}')`}">Editar</button>`:''}</div>`).join('')||'<div class="small">Sin períodos registrados.</div>'}</div></div>${leaveRequestsHtml(uid,false)}${leaveCancelledHistoryHtml(uid)}`)}
function leavePeriodEditor(uid,type,x=null){x=x||{};modal(`<div class="section-head"><div><div class="eyebrow">${type==='gift'?'Día regalo':'Vacaciones'}</div><h3>${x.id?'Editar período':'Añadir período'} · ${esc(person(uid)?.name||'Empleado')}</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="note">Los días se cuentan de fecha a fecha, <b>incluyendo sábados, domingos y festivos</b>. ${type==='gift'?'Este período se contabiliza como regalo y no descuenta vacaciones.':'Este período descuenta del saldo de vacaciones.'}</div><div class="form-grid" style="margin-top:12px"><div><label>Desde</label><input id="leaveStart" type="date" value="${esc(x.start_date||dateIso(new Date()))}"></div><div><label>Hasta</label><input id="leaveEnd" type="date" value="${esc(x.end_date||x.start_date||dateIso(new Date()))}"></div><div class="span2"><label>Indicador / nombre</label><input id="leaveLabel" value="${esc(x.label||(type==='gift'?'Día regalo':'Vacaciones'))}" placeholder="Ej.: Vacaciones verano"></div><div class="span2"><label>Notas opcionales</label><textarea id="leaveNotes" rows="4">${esc(x.notes||'')}</textarea></div></div><div class="actions"><button class="primary" onclick="saveLeavePeriod('${uid}','${type}','${x.id||''}')">Guardar</button>${x.id?`<button class="danger" onclick="cancelLeavePeriod('${x.id}')">Cancelar período</button>`:''}</div>`)}
function newLeavePeriod(uid,type){if(isAdmin())leavePeriodEditor(uid,type)}
function editLeavePeriod(id){if(!isAdmin())return;const x=(db.leavePeriods||[]).find(v=>v.id===id);if(x)leavePeriodEditor(x.user_id,x.leave_type_code,x)}
async function saveLeavePeriod(uid,type,id=''){if(!isAdmin())return;const start=document.getElementById('leaveStart').value,end=document.getElementById('leaveEnd').value,label=document.getElementById('leaveLabel').value.trim(),notes=document.getElementById('leaveNotes').value.trim();if(!start||!end||end<start)return notifyMsg('Revisa las fechas: la fecha final no puede ser anterior.','warn');const days=naturalDaysOverlap(start,end,start,end);if(type==='vacation'){const y=leaveYearSummary(uid,Number(start.slice(0,4))),other=(db.leavePeriods||[]).filter(x=>x.user_id===uid&&x.leave_type_code==='vacation'&&x.status==='active'&&x.id!==id).reduce((n,x)=>n+naturalDaysOverlap(x.start_date,x.end_date,`${start.slice(0,4)}-01-01`,`${start.slice(0,4)}-12-31`),0);if(other+days>y.generated&& !await askConfirm({title:'Vacaciones por encima del saldo generado',message:`Este período dejaría ${other+days} días usados frente a ${y.generated} generados.`,confirmText:'Guardar igualmente',danger:true}))return}const row={user_id:uid,leave_type_code:type,start_date:start,end_date:end,label:label||leaveLabel(type),notes:notes||null,status:'active'};let error;if(id){({error}=await sb.from('employee_leave_periods').update(row).eq('id',id))}else{row.created_by=me().id;({error}=await sb.from('employee_leave_periods').insert(row))}if(error)return notifyMsg(error.message,'bad');await reloadTeamData();openLeaveManager(uid);notifyMsg(`${type==='gift'?'Día regalo':'Vacaciones'} guardado: ${days} día${days===1?'':'s'} natural${days===1?'':'es'}.`)}
function cancelLeavePeriod(id){if(!isAdmin())return;const x=(db.leavePeriods||[]).find(v=>v.id===id);if(!x)return;modal(`<div class="section-head"><div><div class="eyebrow">Cancelar período</div><h3>${esc(leaveLabel(x))} · ${esc(person(x.user_id)?.name||'Empleado')}</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="note">No se borrará: quedará cancelado y auditado.</div><label>Motivo de cancelación</label><textarea id="leaveCancelReason" rows="4" placeholder="Indica por qué se corrige o cancela"></textarea><div class="actions"><button class="danger" onclick="confirmCancelLeavePeriod('${id}')">Confirmar cancelación</button></div>`)}
async function confirmCancelLeavePeriod(id){const x=(db.leavePeriods||[]).find(v=>v.id===id),reason=document.getElementById('leaveCancelReason').value.trim();if(reason.length<5)return notifyMsg('Escribe un motivo de al menos 5 caracteres.','warn');const {error}=await sb.from('employee_leave_periods').update({status:'cancelled',cancel_reason:reason,cancelled_by:me().id,cancelled_at:new Date().toISOString()}).eq('id',id);if(error)return notifyMsg(error.message,'bad');await reloadTeamData();openLeaveManager(x.user_id);notifyMsg('Período cancelado y conservado en histórico.')}
function editLeaveSettings(uid){if(!isAdmin())return;const x=leaveSettingsFor(uid);modal(`<div class="section-head"><div><div class="eyebrow">Vacaciones</div><h3>Regla de devengo · ${esc(person(uid)?.name||'Empleado')}</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="note">Por defecto: <b>2,5 días por mes</b> hasta <b>30 días por año</b>. La fecha de inicio permite ajustar incorporaciones durante el año.</div><div class="form-grid"><div><label>Inicio del devengo</label><input id="leaveAccrualStart" type="date" value="${esc(x.accrual_start_date||`${new Date().getFullYear()}-01-01`)}"></div><div><label>Días por mes</label><input id="leaveRate" type="number" min="0" max="31" step="0.5" value="${Number(x.monthly_rate??2.5)}"></div><div><label>Máximo anual</label><input id="leaveCap" type="number" min="0" max="366" step="0.5" value="${Number(x.annual_cap??30)}"></div></div><div class="actions"><button class="primary" onclick="saveLeaveSettings('${uid}')">Guardar regla</button></div>`)}
async function saveLeaveSettings(uid){const row={user_id:uid,accrual_start_date:document.getElementById('leaveAccrualStart').value||null,monthly_rate:Number(document.getElementById('leaveRate').value||2.5),annual_cap:Number(document.getElementById('leaveCap').value||30),updated_by:me().id,updated_at:new Date().toISOString()};if(row.monthly_rate<0||row.annual_cap<0)return notifyMsg('Los valores no pueden ser negativos.','warn');const {error}=await sb.from('employee_leave_settings').upsert(row,{onConflict:'user_id'});if(error)return notifyMsg(error.message,'bad');await reloadTeamData();openLeaveManager(uid);notifyMsg('Regla de vacaciones actualizada.')}

function absenceEditor(uid,x=null){x=x||{};const types=(db.leaveTypes||[]).filter(t=>!['vacation','gift'].includes(t.code)&&(t.active!==false||t.code===x.leave_type_code));modal(`<div class="section-head"><div><div class="eyebrow">Ausencia</div><h3>${x.id?'Editar ausencia':'Registrar ausencia'} · ${esc(person(uid)?.name||'Empleado')}</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid"><div><label>Tipo</label><select id="absenceType">${types.map(t=>`<option value="${esc(t.code)}" ${x.leave_type_code===t.code?'selected':''}>${esc(t.label)}</option>`).join('')}</select></div><div><label>Desde</label><input id="absenceStart" type="date" value="${esc(x.start_date||dateIso(new Date()))}"></div><div><label>Hasta</label><input id="absenceEnd" type="date" value="${esc(x.end_date||x.start_date||dateIso(new Date()))}"></div><div><label>Indicador / nombre</label><input id="absenceLabel" value="${esc(x.label||'')}"></div><div class="span2"><label>Motivo / notas</label><textarea id="absenceNotes" rows="4">${esc(x.notes||'')}</textarea></div></div><div class="actions"><button class="primary" onclick="saveAbsence('${uid}','${x.id||''}')">Guardar ausencia</button>${x.id?`<button class="danger" onclick="cancelAbsence('${x.id}')">Cancelar ausencia</button>`:''}</div>`)}
function newAbsence(uid){if(isAdmin())absenceEditor(uid)}
function editAbsence(id){if(!isAdmin())return;const x=(db.leavePeriods||[]).find(v=>v.id===id&&!['vacation','gift'].includes(v.leave_type_code));if(x)absenceEditor(x.user_id,x)}
async function saveAbsence(uid,id=''){if(!isAdmin())return;const type=document.getElementById('absenceType').value,start=document.getElementById('absenceStart').value,end=document.getElementById('absenceEnd').value,label=document.getElementById('absenceLabel').value.trim(),notes=document.getElementById('absenceNotes').value.trim(),def=absenceType(type);if(!start||!end||end<start)return notifyMsg('Revisa las fechas de la ausencia.','warn');if(def?.requires_note&&notes.length<5)return notifyMsg('Este tipo de ausencia requiere indicar el motivo.','warn');const row={user_id:uid,leave_type_code:type,start_date:start,end_date:end,label:label||def?.label||'Ausencia',notes:notes||null,status:'active'};let error;if(id){({error}=await sb.from('employee_leave_periods').update(row).eq('id',id))}else{row.created_by=me().id;({error}=await sb.from('employee_leave_periods').insert(row))}if(error)return notifyMsg(error.message,'bad');await reloadTeamData();openLeaveManager(uid);notifyMsg('Ausencia guardada.')}
function cancelAbsence(id){if(!isAdmin())return;const x=(db.leavePeriods||[]).find(v=>v.id===id&&!['vacation','gift'].includes(v.leave_type_code));if(!x)return;modal(`<div class="section-head"><div><div class="eyebrow">Cancelar ausencia</div><h3>${esc(absenceTypeName(x.leave_type_code))}</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="note">La ausencia no se borrará; quedará en el histórico.</div><label>Motivo</label><textarea id="absenceCancelReason" rows="4"></textarea><div class="actions"><button class="danger" onclick="confirmCancelAbsence('${id}')">Confirmar cancelación</button></div>`)}
async function confirmCancelAbsence(id){const x=(db.leavePeriods||[]).find(v=>v.id===id),reason=document.getElementById('absenceCancelReason').value.trim();if(reason.length<5)return notifyMsg('Escribe un motivo de al menos 5 caracteres.','warn');const {error}=await sb.from('employee_leave_periods').update({status:'cancelled',cancel_reason:reason}).eq('id',id);if(error)return notifyMsg(error.message,'bad');await reloadTeamData();openLeaveManager(x.user_id);notifyMsg('Ausencia cancelada y auditada.')}
function manageAbsenceTypes(){if(!isAdmin())return;modal(`<div class="section-head"><div><div class="eyebrow">Ausencias configurables</div><h3>Tipos de ausencia</h3><div class="small">Puedes adaptar estas categorías a vuestra forma de trabajar sin tocar código.</div></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="list" style="margin-top:12px">${(db.leaveTypes||[]).filter(t=>!['vacation','gift'].includes(t.code)).map(t=>`<div class="list-row"><div class="grow"><b>${esc(t.label)}</b><div class="small">${esc(t.description||'')} ${t.requires_note?'· exige motivo':''}</div></div><span class="badge ${t.active!==false?'ok':'warnb'}">${t.active!==false?'ACTIVO':'INACTIVO'}</span><button class="secondary" onclick="editAbsenceType('${esc(t.code)}')">Editar</button></div>`).join('')}</div><div class="actions"><button class="primary" onclick="editAbsenceType('')">+ Nuevo tipo</button></div>`)}
function editAbsenceType(code=''){if(!isAdmin())return;const x=(db.leaveTypes||[]).find(t=>t.code===code)||{};modal(`<div class="section-head"><div><div class="eyebrow">Tipo de ausencia</div><h3>${code?'Editar':'Crear'} categoría</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid"><div class="span2"><label>Nombre</label><input id="absenceTypeLabel" value="${esc(x.label||'')}"></div><div class="span2"><label>Descripción</label><input id="absenceTypeDesc" value="${esc(x.description||'')}"></div><div><label>Orden</label><input id="absenceTypeOrder" type="number" value="${Number(x.sort_order||0)}"></div><div><label class="check-line"><input id="absenceTypeNote" type="checkbox" ${x.requires_note?'checked':''}> Exigir motivo</label><label class="check-line"><input id="absenceTypeActive" type="checkbox" ${x.active!==false?'checked':''}> Activo</label></div></div><div class="actions"><button class="primary" onclick="saveAbsenceType('${esc(code)}')">Guardar tipo</button></div>`)}
async function saveAbsenceType(existing=''){const label=document.getElementById('absenceTypeLabel').value.trim(),description=document.getElementById('absenceTypeDesc').value.trim();if(label.length<3)return notifyMsg('Escribe un nombre claro para el tipo de ausencia.','warn');const code=existing||label.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,40);if(!code)return notifyMsg('No se pudo generar el código del tipo.','bad');const row={code,label,description:description||null,requires_note:document.getElementById('absenceTypeNote').checked,active:document.getElementById('absenceTypeActive').checked,sort_order:Number(document.getElementById('absenceTypeOrder').value||0),updated_at:new Date().toISOString()};row.deducts_vacation=false;const {error}=await sb.from('employee_leave_types').upsert(row,{onConflict:'code'});if(error)return notifyMsg(error.message,'bad');await reloadTeamData();manageAbsenceTypes();notifyMsg('Tipo de ausencia guardado.')}

function manageHolidays(){if(!isAdmin())return;const rows=(db.holidays||[]).slice().sort((a,b)=>String(a.holiday_date).localeCompare(String(b.holiday_date)));modal(`<div class="section-head"><div><div class="eyebrow">Calendario laboral</div><h3>Festivos</h3><div class="small">Puedes asignar un festivo a una tienda concreta o a todas.</div></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="card"><div class="form-grid"><div><label>Fecha</label><input id="holidayDate" type="date" value="${dateIso(new Date())}"></div><div><label>Tienda</label><select id="holidayLoc"><option value="">Todas las tiendas</option>${db.locations.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></div><div class="span2"><label>Festivo / descripción</label><input id="holidayLabel" placeholder="Ej.: Fiesta local"></div><div class="span2"><label>Notas opcionales</label><input id="holidayNotes"></div></div><div class="actions"><button class="primary" onclick="saveHoliday()">+ Añadir festivo</button></div></div><div class="list holiday-list">${rows.map(x=>`<div class="list-row"><div class="grow"><b>${d(x.holiday_date)} · ${esc(x.label)}</b><div class="small">${x.location_id?esc(locationName(x.location_id)):'Todas las tiendas'}${x.notes?' · '+esc(x.notes):''}</div></div><button class="danger" onclick="deactivateHoliday('${x.id}')">Desactivar</button></div>`).join('')||'<div class="small">No hay festivos configurados.</div>'}</div>`)}
async function saveHoliday(){const holiday_date=document.getElementById('holidayDate').value,location_id=document.getElementById('holidayLoc').value||null,label=document.getElementById('holidayLabel').value.trim(),notes=document.getElementById('holidayNotes').value.trim();if(!holiday_date||label.length<3)return notifyMsg('Indica fecha y nombre del festivo.','warn');const {error}=await sb.from('team_holidays').insert({holiday_date,location_id,label,notes:notes||null,active:true,created_by:me().id});if(error)return notifyMsg(error.message.includes('duplicate')?'Ya existe un festivo para esa tienda y fecha.':error.message,'bad');await reloadTeamData();manageHolidays();notifyMsg('Festivo añadido al calendario.')}
async function deactivateHoliday(id){if(!isAdmin())return;if(!await askConfirm({title:'Desactivar festivo',message:'El cambio quedará auditado y dejará de aplicarse.',confirmText:'Desactivar',danger:true}))return;const {error}=await sb.from('team_holidays').update({active:false}).eq('id',id);if(error)return notifyMsg(error.message,'bad');await reloadTeamData();manageHolidays();notifyMsg('Festivo desactivado.')}

function calendarDecorationsForDay(day){const iso=dateIso(day),uid=isAdmin()?(state.calendarUserId&&state.calendarUserId!=='all'?state.calendarUserId:null):me().id,loc=isAdmin()?(state.calendarLocationId||'all'):null,out=[];(isAdmin()?holidayRowsForDate(iso,loc):holidayRowsForUserDate(uid,iso)).forEach(h=>out.push({kind:'holiday',title:h.label,meta:h.location_id?locationName(h.location_id):'Todas las tiendas'}));if(uid){userLeaveOnDate(uid,iso).forEach(x=>out.push({kind:x.leave_type_code,title:x.label||leaveLabel(x),meta:person(uid)?.name||''}));userAbsenceOnDate(uid,iso).forEach(x=>out.push({kind:'absence',title:x.label||absenceTypeName(x.leave_type_code),meta:person(uid)?.name||''}))}else if(isAdmin()){for(const p of db.people.filter(p=>p.role!=='invitado')){userLeaveOnDate(p.id,iso).forEach(x=>out.push({kind:x.leave_type_code,title:`${x.label||leaveLabel(x)} · ${p.name}`,meta:p.name}));userAbsenceOnDate(p.id,iso).forEach(x=>out.push({kind:'absence',title:`${x.label||absenceTypeName(x.leave_type_code)} · ${p.name}`,meta:p.name}))}}return out}
function calendarDecorationChip(x){return `<div class="calendar-special ${x.kind}" title="${esc(x.title)}"><b>${x.kind==='holiday'?'Festivo':x.kind==='vacation'?'Vacaciones':x.kind==='gift'?'Regalo':'Ausencia'}</b><span>${esc(x.title)}</span></div>`}
function calendarDayBox(day,compact=false){const items=calendarItemsForDay(day),special=calendarDecorationsForDay(day),iso=dayIsoLocal(day),today=day.toDateString()===new Date().toDateString(),kinds=new Set(special.map(x=>x.kind));const compactSummary=`<div class="calendar-compact-summary" aria-label="${items.length} tareas y ${special.length} indicaciones">${items.length?`<span class="calendar-compact-count">${items.length}</span>`:'<span class="calendar-compact-count empty"></span>'}${['holiday','vacation','gift','absence'].filter(k=>kinds.has(k)).map(k=>`<i class="calendar-dot ${k}"></i>`).join('')}</div>`;return `<div class="calendar-day-box ${today?'today':''} ${compact?'compact':''}" onclick="openDayAgenda('${iso}')"><div class="calendar-day-head"><div><span>${esc(day.toLocaleDateString('es-ES',{weekday:'short'}))}</span><b>${day.getDate()}</b></div><div class="day-badges">${special.length?`<span class="badge special-count">${special.length} aviso${special.length===1?'':'s'}</span>`:''}<span class="badge ${items.length?'info':''}">${items.length} tarea${items.length===1?'':'s'}</span></div></div>${compactSummary}${special.length?`<div class="calendar-specials">${special.slice(0,compact?2:4).map(calendarDecorationChip).join('')}${special.length>(compact?2:4)?`<div class="small">+${special.length-(compact?2:4)} indicaciones</div>`:''}</div>`:''}<div class="calendar-day-items">${items.slice(0,compact?4:8).map(calendarTaskChip).join('')||'<div class="calendar-empty">Sin tareas</div>'}${items.length>(compact?4:8)?`<button class="ghost calendar-more" onclick="event.stopPropagation();openDayAgenda('${iso}')">+${items.length-(compact?4:8)} más</button>`:''}</div></div>`}
function openDayAgenda(date){state.calendarSelectedDate=date;const day=new Date(date+'T12:00:00'),items=calendarItemsForDay(day),special=calendarDecorationsForDay(day);modal(`<div class="section-head"><div><div class="eyebrow">Agenda del día</div><h3>${esc(day.toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long',year:'numeric'}))}</h3><div class="small">${items.length} tarea${items.length===1?'':'s'} · ${special.length} indicación${special.length===1?'':'es'} de calendario</div></div><button class="ghost" onclick="closeModal()">Cerrar</button></div>${special.length?`<div class="calendar-agenda-specials">${special.map(calendarDecorationChip).join('')}</div>`:''}<div class="agenda-day-list" style="margin-top:12px">${items.filter(x=>x.id).map(x=>{const t=db.tasks.find(t=>t.id===x.id);return `<div class="agenda-task"><div class="grow"><b>${esc(x.title)}</b><div class="task-meta"><span class="badge info">${esc(x.location)}</span><span class="badge">${esc(x.category)}</span>${isAdmin()&&x.person?`<span class="badge">${esc(x.person)}</span>`:''}</div><div class="small">${t?.due_at?'Vence '+dt(t.due_at):t?.starts_at?'Inicio '+dt(t.starts_at):''}</div></div><button class="secondary" onclick="closeModal();${isAdmin()?`calendarEditTask('${x.id}')`:`openTaskCard('${x.id}')`}">${isAdmin()?'Gestionar':'Abrir'}</button></div>`}).join('')||'<div class="note">No hay tareas asignadas este día.</div>'}</div>${isAdmin()?`<div class="actions" style="margin-top:12px"><button class="primary" onclick="closeModal();calendarNewTaskOn('${date}')">+ Añadir tarea este día</button><button class="secondary" onclick="closeModal();manageHolidays()">Gestionar festivos</button></div>`:''}`)}
function calendarHtml(){const layout=state.calendarLayout||'calendar',title=calendarTitle(),content=layout==='list'?calendarListView():layout==='cards'?calendarCardsView():(state.calendarScale==='day'?calendarDayView():state.calendarScale==='week'?calendarWeekView():calendarMonthView());return `<div class="head calendar-page-head"><div><div class="eyebrow">Calendario de trabajo</div><h1 style="text-transform:capitalize">${esc(title)}</h1><p>${isAdmin()?'Tareas, vacaciones, regalos, ausencias y festivos del equipo.':'Tus tareas, vacaciones, ausencias y festivos en una sola vista.'}</p></div><div class="actions">${isAdmin()?`<button class="secondary" onclick="manageHolidays()">Festivos</button><button class="primary" onclick="calendarNewTaskOn('${dayIsoLocal(state.calendarDate||new Date())}')">+ Nueva tarea</button>`:''}</div></div><div class="card calendar-toolbar"><div class="calendar-view-switch"><button class="${layout==='list'?'active':''}" onclick="setCalendarLayout('list')">Lista</button><button class="${layout==='cards'?'active':''}" onclick="setCalendarLayout('cards')">Casillas</button><button class="${layout==='calendar'?'active':''}" onclick="setCalendarLayout('calendar')">Calendario</button></div><div class="calendar-scale-switch"><button class="${state.calendarScale==='day'?'active':''}" onclick="setCalendarScale('day')">Día</button><button class="${state.calendarScale==='week'?'active':''}" onclick="setCalendarScale('week')">Semana</button><button class="${state.calendarScale==='month'?'active':''}" onclick="setCalendarScale('month')">Mes</button></div><div class="calendar-mobile-controls"><label>Vista<select onchange="setCalendarLayout(this.value)"><option value="calendar" ${layout==='calendar'?'selected':''}>Calendario</option><option value="list" ${layout==='list'?'selected':''}>Lista</option><option value="cards" ${layout==='cards'?'selected':''}>Casillas</option></select></label><label>Periodo<select onchange="setCalendarScale(this.value)"><option value="month" ${state.calendarScale==='month'?'selected':''}>Mes</option><option value="week" ${state.calendarScale==='week'?'selected':''}>Semana</option><option value="day" ${state.calendarScale==='day'?'selected':''}>Día</option></select></label></div><div class="calendar-filters"><select class="calendar-filter" aria-label="Filtrar calendario por tienda" onchange="state.calendarLocationId=this.value;renderTasks()">${locationOptions(state.calendarLocationId||'all')}</select>${calendarUserOptions()}</div><div class="calendar-nav"><button class="secondary" onclick="moveCalendar(-1)">←</button><button class="secondary" onclick="calendarToday()">Hoy</button><button class="secondary" onclick="moveCalendar(1)">→</button></div></div><div class="card calendar-surface" style="margin-top:12px">${content}<div class="small calendar-hint">Pulsa un día para abrir su agenda. Las etiquetas distinguen tareas, vacaciones, días regalo, ausencias y festivos.${isAdmin()?' Desde ahí puedes añadir o modificar tareas.':''}</div></div>${taskLocalLogHtml()}`}
function calendarListView(){const r=calendarRange(),entries=[];calendarTasksInRange(r.start,r.end).forEach(t=>entries.push({at:new Date(calendarTaskMoment(t)),kind:'task',task:t}));for(let day=startOfDay(r.start);day<r.end;day=addDays(day,1)){for(const x of calendarDecorationsForDay(day))entries.push({at:new Date(dateIso(day)+'T12:00:00'),kind:x.kind,special:x})}entries.sort((a,b)=>a.at-b.at);return `<div class="calendar-list-view">${entries.map(e=>{if(e.kind==='task'){const t=e.task,p=person(t.assigned_to);return `<div class="calendar-list-row" onclick="${isAdmin()?`calendarEditTask('${t.id}')`:`openTaskCard('${t.id}')`}"><div class="calendar-list-date"><b>${e.at.toLocaleDateString('es-ES',{day:'2-digit',month:'short'})}</b><span>${e.at.toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}</span></div><div class="grow"><b>${esc(t.title)}</b><div class="task-meta"><span class="badge ${badgeStatus(t.status)}">${taskStatusName(t.status)}</span><span class="badge info">${esc(locationName(t.location_id))}</span><span class="badge">${esc(taskCategoryName(t.category_id))}</span>${isAdmin()&&p?`<span class="badge">${esc(p.name)}</span>`:''}</div><div class="small">${esc(t.description||'')}</div></div><div class="num"><b>${Number(t.estimated_minutes||0)} min</b><div class="small">previstos</div></div></div>`}const x=e.special;return `<div class="calendar-list-row special-row"><div class="calendar-list-date"><b>${e.at.toLocaleDateString('es-ES',{day:'2-digit',month:'short'})}</b><span>Todo el día</span></div><div class="grow">${calendarDecorationChip(x)}</div></div>`}).join('')||'<div class="note">No hay tareas ni indicaciones en el período seleccionado.</div>'}</div>`}


function panelAlarmRows(uid){const now=Date.now(),rows=[];for(const t of db.tasks.filter(t=>t.assigned_to===uid&&!['done','cancelled'].includes(t.status))){const at=new Date(t.due_at||t.starts_at||0).getTime();if(!at)continue;const delta=(at-now)/60000;if(delta<0)rows.push({level:'bad',title:'Tarea vencida',text:t.title,time:`${Math.abs(Math.round(delta))} min de retraso`});else if(delta<=24*60)rows.push({level:delta<=60?'warn':'info',title:'Próxima tarea',text:t.title,time:delta<60?`en ${Math.max(0,Math.round(delta))} min`:new Date(at).toLocaleString('es-ES',{weekday:'short',hour:'2-digit',minute:'2-digit'})})}const br=(db.breaks||[]).find(x=>x.user_id===uid&&!x.ended_at&&!x.counts_as_work);if(br){const min=Math.round((now-new Date(br.started_at).getTime())/60000),warn=breakWarningMinutes(br);rows.unshift({level:min>=warn?'bad':'warn',title:'Parada personal abierta',text:breakName(br.break_type),time:`${min} min · previsto ${warn}`})}const intr=(db.interruptions||[]).find(x=>x.user_id===uid&&!x.ended_at);if(intr)rows.unshift({level:'warn',title:'Tarea suspendida',text:db.tasks.find(t=>t.id===intr.task_id)?.title||'Tarea',time:fmtDur(elapsedSec(intr.started_at))});return rows.slice(0,7)}
function panelToggleMute(){toggleAlarmMute(!state.alarmMuted);renderTasks();notifyMsg(state.alarmMuted?'Alarmas sonoras silenciadas.':'Alarmas sonoras activadas.')}
function panelSetAlarmVolume(v){setAlarmVolume(v);const e=document.getElementById('panelAlarmVolText');if(e)e.textContent=Math.round(state.alarmVolume*100)+'%'}
function panelAlarmsHtml(uid){const rows=panelAlarmRows(uid);return `<div class="card panel-widget alarm-widget"><div class="section-head"><div><div class="eyebrow">Tareas y alarmas</div><h3>Avisos visuales y sonoros</h3></div><span class="badge ${state.alarmMuted?'warnb':'ok'}">${state.alarmMuted?'SONIDO OFF':'SONIDO ON'}</span></div><div class="alarm-controls"><button class="${state.alarmMuted?'primary':'secondary'}" onclick="panelToggleMute()">${state.alarmMuted?'Activar sonido':'Silenciar'}</button><button class="secondary" onclick="testAlarm()">Probar</button><button class="ghost" onclick="alarmSettingsModal()">Ajustes</button></div><div class="alarm-list">${rows.map(r=>`<div class="alarm-row ${r.level}"><span class="alarm-dot"></span><div class="grow"><b>${esc(r.title)}</b><span>${esc(r.text)}</span></div><small>${esc(r.time)}</small></div>`).join('')||'<div class="empty-state compact"><b>Sin avisos pendientes</b><span>No hay alarmas activas en este momento.</span></div>'}</div></div>`}
function panelMiniCalendarHtml(uid){const now=new Date(),first=new Date(now.getFullYear(),now.getMonth(),1),st=startOfWeek(first),days=[];for(let i=0;i<42;i++){const day=addDays(st,i),iso=dateIso(day),taskN=db.tasks.filter(t=>t.assigned_to===uid&&!['cancelled'].includes(t.status)&&dateIso(calendarTaskMoment(t))===iso).length,leave=userLeaveOnDate(uid,iso),abs=userAbsenceOnDate(uid,iso),hol=holidayRowsForUserDate(uid,iso),other=day.getMonth()!==now.getMonth();days.push(`<button class="mini-day ${other?'other':''} ${iso===dateIso(now)?'today':''} ${leave.some(x=>x.leave_type_code==='vacation')?'vacation':''} ${leave.some(x=>x.leave_type_code==='gift')?'gift':''} ${abs.length?'absence':''} ${hol.length?'holiday':''}" onclick="state.calendarDate=new Date('${iso}T12:00:00');goSub('calendar')"><span>${day.getDate()}</span><i>${taskN||''}</i></button>`)}return `<div class="card panel-widget mini-calendar-widget"><div class="section-head"><div><div class="eyebrow">Mini calendario</div><h3>${esc(now.toLocaleDateString('es-ES',{month:'long',year:'numeric'}))}</h3></div><button class="secondary" onclick="goSub('calendar')">Abrir calendario</button></div><div class="mini-week">${WEEK.map(x=>`<span>${x.slice(0,1)}</span>`).join('')}</div><div class="mini-calendar">${days.join('')}</div><div class="mini-legend"><span><i class="vacation"></i>Vacaciones</span><span><i class="gift"></i>Regalo</span><span><i class="absence"></i>Ausencia</span><span><i class="holiday"></i>Festivo</span><span><b>n</b> tareas</span></div></div>`}

