function panelKey(){return `totus_panel_widgets_${me()?.id||'user'}`}
function personalPanelHtml(uid){return `<div class="head"><div><div class="eyebrow">Consola personal</div><h1>Mi panel</h1><p>Tu jornada, tareas, avisos, calendario y vacaciones en una sola pantalla configurable.</p></div><div class="actions">${isAdmin()?`<div class="panel-employee-switch"><label>Controlar empleado</label><select aria-label="Cambiar a control de empleado" onchange="if(this.value){state.timeUserId=this.value;renderTasks()}"><option value="">Selecciona…</option>${db.people.filter(p=>p.role!=='invitado'&&p.id!==me().id).map(p=>`<option value="${p.id}">Control · ${esc(p.name)}</option>`).join('')}</select></div>`:''}<button class="secondary" onclick="customizePanel()">⚙ Configurar panel</button></div></div><div class="panel-dashboard">${panelPrimaryStacksHtml(uid)}${panelHas('notifications')?`<div class="panel-wide-block">${notificationsPanelHtml(uid)}</div>`:''}${panelWideWidgetsHtml(uid)}</div>${!PANEL_WIDGETS.some(w=>panelHas(w.id))?`<div class="empty-state big"><b>Tu panel está vacío</b><span>Activa los bloques que quieras usar.</span><button class="primary" onclick="customizePanel()">Configurar mi panel</button></div>`:''}`}
function mineHtml(){const uid=isAdmin()?(state.timeUserId||me().id):me().id;if(uid===me().id){state.timeUserId=null;return personalPanelHtml(uid)}return employeeControlHtml(uid)+leavePanelHtml(uid,false)+notificationsPanelHtml(uid)}
function panelPrimaryStacksHtml(uid){const left=[panelHas('now')?panelNowHtml():'',panelHas('quick')?panelQuickHtml():'',panelHas('month')?`<div class="panel-stack-month">${hoursCountdownHtml(uid)}</div>`:''].filter(Boolean).join(''),right=[panelHas('alarms')?panelAlarmsHtml(uid):'',panelHas('miniCalendar')?panelMiniCalendarHtml(uid):''].filter(Boolean).join('');if(!left&&!right)return'';return `<div class="panel-primary-grid">${left?`<div class="panel-stack">${left}</div>`:''}${right?`<div class="panel-stack">${right}</div>`:''}</div>`}
function panelWideWidgetsHtml(uid){return `${panelHas('leave')?`<div class="panel-wide-block">${leavePanelHtml(uid,true)}</div>`:''}${panelHas('tasks')?`<div class="panel-wide-block">${panelTasksHtml(uid)}</div>`:''}${panelHas('stats')?`<div class="panel-wide-block">${panelStatsHtml(uid)}</div>`:''}${panelHas('recent')?`<div class="panel-wide-block">${panelRecentHtml(uid)}</div>`:''}`}


function holidayAdminPanelHtml(){if(!isAdmin())return'';const year=new Date().getFullYear(),rows=(db.holidays||[]).filter(x=>String(x.holiday_date).startsWith(String(year)));return `<div class="card" style="margin-top:12px"><div class="section-head"><div><div class="eyebrow">Calendario laboral</div><h3>Festivos · ${year}</h3><div class="small">${rows.length} registros activos. Pueden aplicarse a una tienda concreta o a todas.</div></div><button class="secondary" onclick="manageHolidays()">Gestionar festivos</button></div><div class="holiday-summary">${rows.slice(0,8).map(x=>`<span class="badge ${x.location_id?'info':''}">${d(x.holiday_date)} · ${esc(x.label)}${x.location_id?' · '+esc(locationName(x.location_id)):''}</span>`).join('')||'<span class="small">Sin festivos configurados para este año.</span>'}</div></div>`}
const LEAVE_HELP={vacation_accrual:{title:'Devengo de vacaciones',body:'Por defecto se generan 2,5 días por mes hasta un máximo de 30 días al año. El administrador puede ajustar la fecha de inicio, la tasa mensual o el máximo para un trabajador concreto.'},vacation_natural:{title:'Días naturales',body:'Las vacaciones se cuentan desde la fecha inicial hasta la final, ambos días incluidos. Sábados, domingos y festivos que queden dentro del período también cuentan como días de vacaciones.'}};
if(typeof HELP_CONTENT==='object')Object.assign(HELP_CONTENT,LEAVE_HELP);




/* Núcleo funcional consolidado */
function addDays(v,n){const x=new Date(v);x.setDate(x.getDate()+n);return x}

function adminAddAttendance(uid){if(!isAdmin())return;modal(`<div class="section-head"><div><div class="eyebrow">Administrador</div><h3>Añadir fichaje olvidado</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid" style="margin-top:12px"><div class="span2"><label>Tienda / centro</label><select id="aaLocation">${db.locations.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></div><div class="span2"></div><div class="span2"><label>Entrada real</label><input id="aaIn" type="datetime-local"></div><div class="span2"><label>Salida real</label><input id="aaOut" type="datetime-local"></div><div class="span4"><label>Motivo obligatorio</label><input id="aaReason" placeholder="Ej. El empleado olvidó fichar la entrada"></div><div class="span4"><label>Notas</label><input id="aaNotes" placeholder="Observaciones"></div></div><div class="actions" style="margin-top:12px"><button class="primary" onclick="saveAdminAttendance('${uid}')">Guardar fichaje</button></div>`) }

function adminAuditHtml(uid){const taskRows=db.taskAudit.filter(x=>!uid||db.tasks.find(t=>t.id===x.task_id)?.assigned_to===uid).slice(0,200),adm=db.adminAudit.filter(x=>!uid||x.target_user_id===uid).slice(0,200);return `<details class="audit-details" style="margin-top:12px"><summary>Administración · tareas y cambios sensibles</summary><div class="grid g2" style="margin-top:10px"><div class="card"><div class="section-head"><h3>Log de tareas</h3><div class="actions"><button class="secondary" onclick="exportTaskAudit('${uid||''}')">Exportar</button><button class="secondary" onclick="printTaskAudit('${uid||''}')">Imprimir</button></div></div><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Fecha</th><th>Tarea</th><th>Acción</th><th>Actor</th><th>Detalle</th></tr></thead><tbody>${taskRows.map(a=>`<tr><td>${dt(a.created_at)}</td><td>${esc(db.tasks.find(t=>t.id===a.task_id)?.title||a.task_id||'')}</td><td>${esc(a.action)}</td><td>${esc(person(a.actor_user_id)?.name||'Sistema')}</td><td class="small">${esc(jsonSummary(a.new_data))}</td></tr>`).join('')||'<tr><td colspan="5" class="small">Sin eventos.</td></tr>'}</tbody></table></div></div><div class="card"><div class="section-head"><h3>Log administrativo</h3><div class="actions"><button class="secondary" onclick="exportAdminAudit('${uid||''}')">Exportar</button><button class="secondary" onclick="printAdminAudit('${uid||''}')">Imprimir</button></div></div><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Fecha</th><th>Entidad</th><th>Acción</th><th>Actor</th><th>Detalle</th></tr></thead><tbody>${adm.map(a=>`<tr><td>${dt(a.created_at)}</td><td>${esc(a.entity_type)}</td><td>${esc(a.action)}</td><td>${esc(person(a.actor_user_id)?.name||'Sistema')}</td><td class="small">${esc(jsonSummary(a.new_data))}</td></tr>`).join('')||'<tr><td colspan="5" class="small">Sin eventos.</td></tr>'}</tbody></table></div></div></div></details>`}

function attendanceHtml(){const uid=isAdmin()?(state.historyUserId||me().id):me().id,rows=db.attendance.filter(x=>x.user_id===uid).slice(0,500),worked=monthlyWorkedMinutes(uid),real=monthlyRealMinutes(uid),breaks=monthlyBreakMinutes(uid),target=monthlyTargetMinutes(uid),remaining=target-worked,u=person(uid)||me(),audit=db.attendanceAudit.filter(x=>x.user_id===uid).slice(0,300);return `<div class="head"><div><div class="eyebrow">Fichajes</div><h1>Control horario ${helpIcon('computable','Qué significa hora computable')}</h1><p>La hora real siempre queda registrada; para el cómputo se recorta el tiempo anterior al horario y posterior a la salida. Llegar tarde, salir antes y pausas personales sí descuentan.</p></div>${isAdmin()?`<div style="min-width:260px"><label>Empleado</label><select onchange="state.historyUserId=this.value;renderTasks()">${db.people.filter(p=>p.role!=='invitado').map(p=>`<option value="${p.id}" ${uid===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>`:''}</div><div class="stats"><div class="stat"><small>Computado mes</small><strong>${fmtHours(worked)}</strong></div><div class="stat"><small>Presencia real</small><strong>${fmtHours(real)}</strong></div><div class="stat"><small>Pausas personales</small><strong>${fmtHours(breaks)}</strong></div><div class="stat"><small>${remaining>=0?'Restan':'Exceso'}</small><strong>${fmtHours(Math.abs(remaining))}</strong></div></div><div class="card"><div class="section-head"><div><h3>Historial · ${esc(u.name)}</h3><div class="small">Objetivo del mes: ${fmtHours(target)}</div></div><div class="actions"><button class="secondary" onclick="exportAttendance('${uid}')">Exportar informe CSV</button><button class="secondary" onclick="printAttendance('${uid}')">Imprimir</button>${isAdmin()?`<button class="primary" onclick="adminAddAttendance('${uid}')">+ Fichaje olvidado</button>`:''}</div></div><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Día</th><th>Tienda</th><th>Entrada real</th><th>Salida real</th><th>Entrada computable</th><th>Salida computable</th><th>Presencia</th><th>Pausas</th><th>Computado</th><th>Origen</th>${isAdmin()?'<th></th>':''}</tr></thead><tbody>${rows.map(e=>`<tr><td>${attendanceDayLabel(e.clock_in)}</td><td>${esc(locationName(e.location_id))}</td><td>${dt(e.clock_in)}</td><td>${e.clock_out?dt(e.clock_out):'<span class="badge ok">ABIERTO</span>'}</td><td>${dt(effectiveStart(e))}${Number(e.rounding_in_minutes)>0?`<div class="small">+${Number(e.rounding_in_minutes).toFixed(0)} min redondeados</div>`:''}</td><td>${e.clock_out?dt(effectiveEnd(e)): '—'}${Number(e.rounding_out_minutes)>0?`<div class="small">-${Number(e.rounding_out_minutes).toFixed(0)} min redondeados</div>`:''}</td><td>${fmtHours(attendanceRealMinutes(e))}</td><td>${fmtHours(Number(e.break_minutes||0))}</td><td><b>${fmtHours(attendanceNetMinutes(e))}</b></td><td>${esc(e.source)}${e.admin_action_reason?`<div class="small">${esc(e.admin_action_reason)}</div>`:''}</td>${isAdmin()?`<td><button class="ghost" onclick="editAttendance('${e.id}')">Corregir</button></td>`:''}</tr>`).join('')||'<tr><td colspan="11" class="small">Sin fichajes.</td></tr>'}</tbody></table></div></div><details class="audit-details" style="margin-top:12px"><summary>Log de fichajes y pausas · ${audit.length} eventos</summary><div class="card audit-card"><div class="section-head"><div><h3>Trazabilidad</h3><div class="small">Registro de cambios, correcciones y pausas.</div></div><div class="actions"><button class="secondary" onclick="exportAttendanceAudit('${uid}')">Exportar log</button><button class="secondary" onclick="printAttendanceAudit('${uid}')">Imprimir log</button></div></div><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Fecha</th><th>Acción</th><th>Actor</th><th>Motivo</th><th>Cambio</th></tr></thead><tbody>${audit.map(a=>`<tr><td>${dt(a.created_at)}</td><td>${esc(a.action)}</td><td>${esc(person(a.actor_user_id)?.name||'Sistema/usuario')}</td><td>${esc(a.reason||'')}</td><td class="small">${esc(jsonSummary(a.new_data))}</td></tr>`).join('')||'<tr><td colspan="5" class="small">Sin eventos.</td></tr>'}</tbody></table></div></div></details>${isAdmin()?adminAuditHtml(uid):''}`}

function attendanceNetMinutes(e,now=new Date()){
  const a=effectiveStart(e),b=effectiveEnd(e,now);if(!a||!b)return 0;
  return Math.max(0,(new Date(b)-new Date(a))/60000-clampedBreakMinutesForEntry(e,a,b,now));
}

function calendarCardsView(){const r=calendarRange(),boxes=[];for(let day=startOfDay(r.start);day<r.end;day=addDays(day,1)){const items=calendarItemsForDay(day);if(items.length||state.calendarScale!=='month')boxes.push(calendarDayBox(day,false))}return `<div class="calendar-cards-grid">${boxes.join('')||'<div class="note">No hay tareas en el periodo seleccionado.</div>'}</div>`}

function calendarDayView(){return `<div class="calendar-day-view">${calendarDayBox(startOfDay(state.calendarDate||new Date()),false)}</div>`}

function calendarEditTask(id){if(!isAdmin())return openTaskCard(id);const t=db.tasks.find(x=>x.id===id);if(!t)return;state.editTaskId=id;state.taskEditorContext='calendar';state.taskDraft={...t,starts_at:inputDT(t.starts_at),due_at:inputDT(t.due_at),recurrence:{enabled:false,frequency:'weekly',interval:1,weekdays:[],until:null,count:0,occurrence:1,...(t.recurrence||{})}};modal(taskEditorHtml())}

function calendarItemsForDay(day){const start=startOfDay(day),end=addDays(start,1),items=calendarTasksInRange(start,end).map(t=>({id:t.id,title:t.title,location:locationName(t.location_id),category:taskCategoryName(t.category_id),person:person(t.assigned_to)?.name||'',done:t.status==='done',cancelled:t.status==='cancelled',urgent:t.priority==='urgent',virtual:false,time:calendarTaskMoment(t)}));for(const t of db.tasks){if(!calendarTaskAllowed(t)||['done','cancelled'].includes(t.status)||!t.recurrence?.enabled)continue;for(const v of virtualRecurrenceDates(t,start,end))items.push({id:null,title:t.title,location:locationName(t.location_id),category:taskCategoryName(t.category_id),person:person(t.assigned_to)?.name||'',done:false,cancelled:false,urgent:t.priority==='urgent',virtual:true,time:v})}return items.sort((a,b)=>new Date(a.time||0)-new Date(b.time||0))}

function calendarMonthView(){const d=new Date(state.calendarDate||new Date()),first=new Date(d.getFullYear(),d.getMonth(),1),st=startOfWeek(first),cells=[];for(let i=0;i<42;i++){const day=addDays(st,i),other=day.getMonth()!==d.getMonth();cells.push(`<div class="calendar-month-cell ${other?'other':''}">${calendarDayBox(day,true)}</div>`)}return `<div class="calendar-head">${WEEK.map(x=>`<div>${x}</div>`).join('')}</div><div class="calendar calendar-month-grid">${cells.join('')}</div>`}

function calendarRange(){const base=startOfDay(state.calendarDate||new Date()),scale=state.calendarScale||'month';if(scale==='day')return{start:base,end:addDays(base,1)};if(scale==='week'){const st=startOfWeek(base);return{start:st,end:addDays(st,7)}}const st=new Date(base.getFullYear(),base.getMonth(),1),en=new Date(base.getFullYear(),base.getMonth()+1,1);return{start:st,end:en}}

function calendarTaskAllowed(t){const loc=state.calendarLocationId||'all',uid=isAdmin()?(state.calendarUserId||'all'):me()?.id;if(loc!=='all'&&t.location_id!==loc)return false;if(uid&&uid!=='all'&&t.assigned_to!==uid)return false;return true}

function calendarTaskChip(x){const cls=`calendar-task-chip ${x.done?'done':''} ${x.cancelled?'cancelled':''} ${x.urgent?'urgent':''} ${x.virtual?'virtual':''}`;const action=x.id?`onclick="event.stopPropagation();${isAdmin()?`calendarEditTask('${x.id}')`:`openTaskCard('${x.id}')`}"`:'';return `<div class="${cls}" ${action} title="${esc(x.title)}"><div class="calendar-chip-title">${x.virtual?'↻ ':''}${esc(x.title)}</div><div class="calendar-chip-meta">${esc(x.location)}${isAdmin()&&x.person?' · '+esc(x.person):''}</div></div>`}

function calendarTaskMoment(t){return t.starts_at||t.due_at||t.created_at}

function calendarTasksInRange(start,end){return db.tasks.filter(t=>calendarTaskAllowed(t)&&calendarTaskMoment(t)&&new Date(calendarTaskMoment(t))>=start&&new Date(calendarTaskMoment(t))<end).sort((a,b)=>new Date(calendarTaskMoment(a))-new Date(calendarTaskMoment(b)))}

function calendarTitle(){const d=new Date(state.calendarDate||new Date()),scale=state.calendarScale||'month';if(scale==='day')return d.toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long',year:'numeric'});if(scale==='week'){const st=startOfWeek(d),en=addDays(st,6);return `${st.toLocaleDateString('es-ES',{day:'numeric',month:'short'})} – ${en.toLocaleDateString('es-ES',{day:'numeric',month:'short',year:'numeric'})}`}return d.toLocaleDateString('es-ES',{month:'long',year:'numeric'})}

