function checkTaskOverrunLive(task,timer){if(!task||!timer||Number(task.estimated_minutes||0)<=0)return;const st=taskOverrunState(task);const key='overrun-live-'+task.id+'-'+st.allowed;if(st.left<=5&&st.left>0&&!state.remindersSeen.has(key)){state.remindersSeen.add(key);notifyMsg(`Quedan ${Math.ceil(st.left)} min autorizados para ${task.title}.`,'warn');browserNotify('Totus · Tiempo de tarea',`Quedan ${Math.ceil(st.left)} min para ${task.title}`);beep()}if(st.left<=0){const k='overrun-stop-'+task.id+'-'+st.allowed;if(!state.remindersSeen.has(k)){state.remindersSeen.add(k);notifyMsg('Tiempo autorizado agotado. Para continuar debes justificar la ampliación.','bad',8000);browserNotify('Totus · Tarea detenida','Debes justificar la ampliación de tiempo.');beep();setTimeout(()=>stopTaskTimer(),50)}}}

function clampedBreakMinutesForEntry(e,from=null,to=null,now=new Date()){
  const start=from?new Date(from):new Date(effectiveStart(e));
  const end=to?new Date(to):new Date(effectiveEnd(e,now));
  if(!Number.isFinite(start.getTime())||!Number.isFinite(end.getTime())||end<=start)return 0;
  let total=0;
  for(const br of db.breaks.filter(x=>x.attendance_entry_id===e.id&&!x.counts_as_work)){
    const a=new Date(br.started_at),b=new Date(br.ended_at||now);
    if(!Number.isFinite(a.getTime())||!Number.isFinite(b.getTime())||b<=start||a>=end)continue;
    const x=a<start?start:a,y=b>end?end:b;
    total+=Math.max(0,(y-x)/60000);
  }
  return total;
}

async function completeTask(id){if(!canOperate())return notifyMsg('Tu perfil es de solo lectura.','warn');const t=db.tasks.find(x=>x.id===id);if(!t||t.assigned_to!==me().id)return notifyMsg('Solo el responsable asignado puede completar esta tarea.','warn');const {error}=await sb.rpc('complete_team_task',{p_task_id:id});if(error){if(/justifica|ampliaci|autorizado/i.test(error.message))return justifyTaskOverrun(id,error.message);return notifyMsg(error.message,'bad')}await reloadTeamData();tick();renderTasks();notifyMsg('Tarea completada.');browserNotify('Totus · Tarea completada',t.title);beep('success')}

