function hoursCountdownHtml(uid=me().id){const h=monthlyHourState(uid);return `<div class="countdown-card"><div class="countdown-head"><div><span>Objetivo mensual</span><b>${fmtHours(h.target)}</b></div><div class="countdown-number ${h.additional>0?'extra':''}">${h.remaining>0?fmtHours(h.remaining):fmtHours(h.additional)}</div></div><div class="progress"><span style="width:${h.pct}%"></span></div><div class="countdown-foot"><span>${h.remaining>0?'Restantes':'Objetivo cubierto'}</span><span>Completado ${h.pct.toFixed(1)}%</span><span>Ordinarias ${fmtHours(h.ordinary)}</span><span>Adicionales ${fmtHours(h.additional)}</span></div></div>`}

function intervalMinutesWithin(startValue,endValue,rangeStart,rangeEnd,now=new Date()){const st=new Date(startValue),en=new Date(endValue||now),from=st<rangeStart?rangeStart:st,to=en>rangeEnd?rangeEnd:en;if(!Number.isFinite(st.getTime())||!Number.isFinite(en.getTime())||to<=from)return 0;return Math.max(0,(to-from)/60000)}

function intervalOverlapsReport(startValue,endValue,from,to,now=new Date()){const[a,b]=reportRangeBounds(from,to);return intervalMinutesWithin(startValue,endValue,a,b,now)>0}

function isFullCalendarMonth(from,to){if(!from||!to||from.slice(0,7)!==to.slice(0,7))return false;const x=new Date(from+'T12:00:00'),first=`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-01`,last=`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(new Date(x.getFullYear(),x.getMonth()+1,0).getDate()).padStart(2,'0')}`;return from===first&&to===last}

function justifyTaskOverrun(taskId,msg=''){const t=db.tasks.find(x=>x.id===taskId);if(!t||t.assigned_to!==me().id)return notifyMsg('Solo el responsable asignado puede justificar la ampliación.','warn');const st=taskOverrunState(t);modal(`<div class="section-head"><div><div class="eyebrow">Tiempo de tarea</div><h3>Justificar ampliación</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div>${msg?`<div class="bad-note note" style="margin-top:10px">${esc(msg)}</div>`:''}<div class="stats" style="margin-top:12px"><div class="stat"><small>Tiempo previsto</small><strong>${t.estimated_minutes} min</strong></div><div class="stat"><small>Consumido</small><strong>${Math.round(st.elapsed)} min</strong></div><div class="stat"><small>Autorizado</small><strong>${st.allowed} min</strong></div><div class="stat"><small>Ampliaciones</small><strong>${db.overruns.filter(x=>x.task_id===t.id).length}</strong></div></div><div class="form-grid"><div class="span4"><label>Qué ha ocurrido / por qué necesitas más tiempo</label><textarea id="overrunReason" placeholder="Motivo concreto y verificable"></textarea></div><div><label>Ampliar · minutos</label><input id="overrunExtension" type="number" min="1" max="480" value="30"></div></div><div class="actions" style="margin-top:12px"><button class="primary" onclick="submitTaskOverrun('${t.id}')">Guardar justificación y continuar</button></div>`)}

function latestSignature(uid,from,to){return db.signatures.find(x=>x.user_id===uid&&x.period_start===from&&x.period_end===to)||null}

function locationOptions(selected='all',includeAll=true){return `${includeAll?`<option value="all" ${selected==='all'?'selected':''}>Todas las tiendas</option>`:''}${db.locations.map(l=>`<option value="${l.id}" ${selected===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}`}

function monthBoundsLocal(date=new Date()){return[new Date(date.getFullYear(),date.getMonth(),1),new Date(date.getFullYear(),date.getMonth()+1,1)]}

function monthlyBreakMinutes(uid=me().id,date=new Date()){const[start,end]=monthBoundsLocal(date),now=new Date();return db.breaks.filter(x=>x.user_id===uid&&!x.counts_as_work).reduce((sum,x)=>sum+intervalMinutesWithin(x.started_at,x.ended_at,start,end,now),0)}

function monthlyRealMinutes(uid=me().id,date=new Date()){const[start,end]=monthBoundsLocal(date),now=new Date();return db.attendance.filter(x=>x.user_id===uid).reduce((sum,e)=>sum+intervalMinutesWithin(e.clock_in,e.clock_out,start,end,now),0)}

function monthlyTaskMinutes(uid=me().id,date=new Date()){const[start,end]=monthBoundsLocal(date),now=new Date();return db.taskTimes.filter(x=>x.user_id===uid).reduce((sum,x)=>sum+intervalMinutesWithin(x.started_at,x.stopped_at,start,end,now),0)}

function monthlyUnassignedMinutes(uid=me().id,date=new Date()){return Math.max(0,monthlyWorkedMinutes(uid,date)-monthlyTaskMinutes(uid,date)-monthlyWorkInterruptionMinutes(uid,date))}

function monthlyWorkInterruptionMinutes(uid=me().id,date=new Date()){const[start,end]=monthBoundsLocal(date),now=new Date();return db.interruptions.filter(x=>x.user_id===uid&&x.counts_as_work!==false).reduce((sum,x)=>sum+intervalMinutesWithin(x.started_at,x.ended_at,start,end,now),0)}

function monthlyWorkedMinutes(uid=me().id,date=new Date()){
  const start=new Date(date.getFullYear(),date.getMonth(),1),end=new Date(date.getFullYear(),date.getMonth()+1,1),now=new Date();let mins=0;
  for(const e of db.attendance.filter(x=>x.user_id===uid)){
    const a0=new Date(effectiveStart(e)),b0raw=effectiveEnd(e,now);if(!b0raw)continue;const b0=new Date(b0raw);
    if(b0<=start||a0>=end)continue;
    const from=a0<start?start:a0,to=b0>end?end:b0;
    const gross=Math.max(0,(to-from)/60000);
    const breaks=clampedBreakMinutesForEntry(e,from,to,now);
    mins+=Math.max(0,gross-breaks);
  }
  return mins;
}

function moveCalendar(n){const d=new Date(state.calendarDate||new Date());if(state.calendarScale==='day')d.setDate(d.getDate()+n);else if(state.calendarScale==='week')d.setDate(d.getDate()+7*n);else d.setMonth(d.getMonth()+n);state.calendarDate=d;state.month=new Date(d.getFullYear(),d.getMonth(),1);renderTasks()}


function openSignaturePad(){const f=reportFilter(),uid=me().id;if(f.uid&&f.uid!==uid)return notifyMsg('Cada empleado solo puede firmar su propio registro.','warn');if(!isFullCalendarMonth(f.from,f.to))return notifyMsg('La firma mensual requiere seleccionar el mes completo.','warn');state.signatureInk=false;modal(`<div class="section-head"><div><div class="eyebrow">Firma mensual</div><h3>Firma con el dedo</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="note" style="margin-top:10px">La firma se asociará al registro íntegro ${esc(f.from)} → ${esc(f.to)}. Las horas adicionales permanecen incluidas en el registro firmado.</div><div class="signature-pad-wrap"><canvas id="signatureCanvas" class="signature-canvas"></canvas></div><div class="actions"><button class="secondary" onclick="clearSignaturePad()">Borrar firma</button><button class="primary" onclick="saveWorkSignature()">Guardar firma</button></div>`);setTimeout(initSignatureCanvas,50)}

function overrunHistoryHtml(uid){const rows=db.overruns.filter(x=>x.user_id===uid).slice(0,200);return `<details class="audit-details" style="margin-top:12px"><summary>Justificaciones de ampliación · ${rows.length}</summary><div class="card audit-card"><div class="section-head"><h3>Excesos de tiempo justificados</h3><button class="secondary" onclick="exportOverruns('${uid}')">Exportar</button></div><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Fecha</th><th>Tarea</th><th>Previsto</th><th>Consumido</th><th>Ampliación</th><th>Justificación</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dt(x.created_at)}</td><td>${esc(db.tasks.find(t=>t.id===x.task_id)?.title||'')}</td><td>${x.estimated_minutes} min</td><td>${x.elapsed_minutes} min</td><td>+${x.extension_minutes} min</td><td>${esc(x.justification)}</td></tr>`).join('')||'<tr><td colspan="6" class="small">Sin ampliaciones.</td></tr>'}</tbody></table></div></div></details>`}

function overviewHtml(){
 const h=monthlyHourState(),real=monthlyRealMinutes(),breaks=monthlyBreakMinutes(),open=myOpenTasks(),dueToday=open.filter(t=>t.due_at&&new Date(t.due_at).toDateString()===new Date().toDateString()),running=openTaskTime(),activeInt=openTaskInterruption(),br=openPersonalBreak();
 const attendanceActions=canOperate()?`<button class="primary" onclick="toggleAttendance()">${openAttendance()?'Fichar salida':'Fichar entrada'}</button>${openAttendance()?`<button class="secondary" onclick="togglePersonalBreak()">${br?'Finalizar parada':'Parada personal · NO COMPUTA'}</button>`:''}`:'<span class="badge info">SOLO LECTURA</span>';
 const taskActions=!canOperate()?'<span class="badge info">SOLO LECTURA</span>':running?`<button class="primary" onclick="stopTaskTimer()">Pausar</button><button class="secondary" onclick="resetTaskTimer()">Reiniciar tramo</button><button class="secondary" onclick="suspendTask('${running.task_id}')">Interrupción laboral</button><button class="ghost" onclick="openActiveTask()">Abrir tarea</button>`:activeInt?`<button class="primary" onclick="resumeTask('${activeInt.task_id}')">Reanudar</button><button class="ghost" onclick="openTaskCard('${activeInt.task_id}')">Abrir tarea</button>`:'<button class="secondary" onclick="goSub(\'tasks\')">Elegir tarea</button>';
 return `<div class="head"><div><div class="eyebrow">Equipo</div><h1>Trabajo de hoy</h1><p>Fichaje real y computable, tareas, pausas, cuenta atrás mensual y avisos en vivo.</p></div><div class="actions"><button class="secondary" onclick="goSub('calendar')">Calendario</button>${isAdmin()?'<button class="primary" onclick="newTaskToday()">+ Tarea</button>':''}</div></div>${hoursCountdownHtml()}${reconciliationPreviewHtml(me().id)}<div class="stats"><div class="stat"><small>Computado mes</small><strong>${fmtHours(h.worked)}</strong></div><div class="stat"><small>Presencia real</small><strong>${fmtHours(real)}</strong></div><div class="stat"><small>Pausas personales</small><strong>${fmtHours(breaks)}</strong></div><div class="stat"><small>Tiempo en tareas</small><strong>${fmtHours(monthlyTaskMinutes())}</strong></div><div class="stat"><small>Trabajado sin asignar ${helpIcon('unassigned','Qué significa trabajado sin asignar')}</small><strong>${fmtHours(monthlyUnassignedMinutes())}</strong></div><div class="stat"><small>Horas adicionales</small><strong>${fmtHours(h.additional)}</strong></div></div>${taskAttentionHtml()}<div class="grid g2"><div class="card"><div class="section-head"><div><div class="eyebrow">Fichaje</div><h3>Jornada</h3></div><span class="badge ${openAttendance()?'ok':'warnb'}">${openAttendance()?'EN CURSO':'PARADA'}</span></div><div class="timer-big" style="margin:14px 0">${openAttendance()?fmtDur(elapsedSec(openAttendance().clock_in)):'00:00:00'}</div><div class="actions">${attendanceActions}<button class="ghost" onclick="goSub('attendance')">Historial</button></div>${attendanceWarnings(false).map(x=>`<div class="${x.level==='bad'?'bad-note':'warn-note'} note" style="margin-top:10px">${esc(x.text)}</div>`).join('')}</div><div class="card"><div class="section-head"><div><div class="eyebrow">Tarea activa</div><h3>${running?esc(db.tasks.find(t=>t.id===running.task_id)?.title||'Tarea'):activeInt?esc(db.tasks.find(t=>t.id===activeInt.task_id)?.title||'Tarea suspendida'):'Sin reloj en marcha'}</h3></div>${running?'<span class="badge ok">CONTANDO</span>':activeInt?'<span class="badge warnb">SUSPENDIDA</span>':''}</div><div class="timer-big" style="margin:14px 0">${running?fmtDur(elapsedSec(running.started_at)):activeInt?fmtDur(elapsedSec(activeInt.started_at)):'00:00:00'}</div><div class="actions">${taskActions}</div></div><div class="card"><div class="section-head"><div><div class="eyebrow">Hoy</div><h3>Tareas de hoy</h3></div></div><div class="list" style="margin-top:10px">${dueToday.map(taskMiniRow).join('')||'<div class="small">No hay tareas con vencimiento hoy.</div>'}</div></div><div class="card"><div class="section-head"><div><div class="eyebrow">Próximas</div><h3>Lo siguiente</h3></div><button class="ghost" onclick="goSub('tasks')">Ver todas</button></div><div class="list" style="margin-top:10px">${open.slice(0,6).map(taskMiniRow).join('')||'<div class="small">Nada pendiente.</div>'}</div></div></div>${isAdmin()?teamStatusHtml():''}`
}

function panelHas(id){return panelPrefs().has(id)}


function panelNowHtml(){const att=openAttendance(),timer=openTaskTime(),intr=openTaskInterruption(),br=openPersonalBreak(),task=timer?db.tasks.find(t=>t.id===timer.task_id):intr?db.tasks.find(t=>t.id===intr.task_id):null;return `<div class="card panel-widget"><div class="section-head"><div><div class="eyebrow">Ahora</div><h3>Estado en este momento</h3></div></div><div class="now-grid"><div class="now-item"><small>Jornada</small><b>${att?fmtDur(elapsedSec(att.clock_in)):'Fuera de jornada'}</b><span>${att?locationName(att.location_id):'Sin fichaje abierto'}</span></div><div class="now-item"><small>Tarea</small><b>${timer?fmtDur(elapsedSec(timer.started_at)):intr?'Suspendida':'Sin tarea activa'}</b><span>${task?esc(task.title):'—'}</span></div><div class="now-item"><small>Parada personal ${helpIcon('personal_break','Qué es una parada personal')}</small><b>${br?fmtDur(elapsedSec(br.started_at)):'Sin parada'}</b><span>${br?esc(breakName(br.break_type)):'—'}</span></div></div></div>`}

function panelPrefs(){try{const raw=JSON.parse(localStorage.getItem(panelKey())||'null');if(raw&&Array.isArray(raw))return new Set(raw)}catch{}return new Set(PANEL_WIDGETS.filter(x=>x.def).map(x=>x.id))}

function panelQuickHtml(){const att=openAttendance(),br=openPersonalBreak();return `<div class="card panel-widget"><div class="section-head"><div><div class="eyebrow">Accesos rápidos</div><h3>Lo que uso ahora</h3></div></div><div class="quick-grid"><button class="quick-action" onclick="goSub('calendar')"><b>Calendario</b><span>Ver agenda y tareas</span></button><button class="quick-action" onclick="goSub('tasks')"><b>Tareas</b><span>Abrir mi lista</span></button><button class="quick-action" onclick="goRoot('purchases')"><b>Compras</b><span>Registrar o consultar</span></button><button class="quick-action" onclick="goRoot('library')"><b>Tutoriales</b><span>Protocolos y ayuda interna</span></button><button class="quick-action" onclick="goSub('reports')"><b>Informes</b><span>Mis horas y actividad</span></button>${canOperate()?`<button class="quick-action emphasis" onclick="toggleAttendance()"><b>${att?'Fichar salida':'Fichar entrada'}</b><span>${att?locationName(att.location_id):'Elegir tienda y comenzar'}</span></button>${att?`<button class="quick-action ${br?'warn':''}" onclick="togglePersonalBreak()"><b>${br?'Finalizar parada':'Parada personal'}</b><span>${br?breakName(br.break_type):'Tiempo no computable'}</span></button>`:''}`:''}</div></div>`}

function panelRecentHtml(uid){const rows=db.taskTimes.filter(x=>x.user_id===uid).sort((a,b)=>new Date(b.started_at)-new Date(a.started_at)).slice(0,8);return `<div class="card panel-widget"><div class="section-head"><div><div class="eyebrow">Actividad reciente</div><h3>Últimos tramos</h3></div><button class="secondary" onclick="exportTaskTimes('${uid}')">Exportar</button></div><div class="list" style="margin-top:10px">${rows.map(x=>{const t=db.tasks.find(t=>t.id===x.task_id);return `<div class="row"><div class="grow"><b>${esc(t?.title||'Tarea')}</b><div class="small">${dt(x.started_at)} · ${esc(locationName(t?.location_id))}</div></div><span class="badge info">${fmtDur(elapsedSec(x.started_at,x.stopped_at))}</span></div>`}).join('')||'<div class="small">Todavía no hay tramos registrados.</div>'}</div></div>`}

function panelStatsHtml(uid){const h=monthlyHourState(uid),real=monthlyRealMinutes(uid),breaks=monthlyBreakMinutes(uid);return `<div class="card panel-widget"><div class="section-head"><div><div class="eyebrow">Mes actual</div><h3>Resumen de tiempos</h3></div></div><div class="stats"><div class="stat"><small>Computado</small><strong>${fmtHours(h.worked)}</strong></div><div class="stat"><small>Presencia real</small><strong>${fmtHours(real)}</strong></div><div class="stat"><small>Pausas personales</small><strong>${fmtHours(breaks)}</strong></div><div class="stat"><small>Tiempo en tareas</small><strong>${fmtHours(monthlyTaskMinutes(uid))}</strong></div><div class="stat"><small>Sin asignar ${helpIcon('unassigned','Qué significa trabajado sin asignar')}</small><strong>${fmtHours(monthlyUnassignedMinutes(uid))}</strong></div><div class="stat"><small>Adicionales</small><strong>${fmtHours(h.additional)}</strong></div></div></div>`}

function panelTasksHtml(uid){const rows=db.tasks.filter(t=>t.assigned_to===uid&&!['done','cancelled'].includes(t.status)).sort((a,b)=>new Date(a.due_at||a.starts_at||'9999')-new Date(b.due_at||b.starts_at||'9999'));return `<div class="card panel-widget"><div class="section-head"><div><div class="eyebrow">Mis tareas</div><h3>Abiertas · ${rows.length}</h3></div><button class="secondary" onclick="goSub('tasks')">Ver todas</button></div><div class="list" style="margin-top:10px">${rows.slice(0,6).map(taskMiniRow).join('')||'<div class="empty-state"><b>Sin tareas abiertas</b><span>No tienes ninguna tarea pendiente o en curso.</span></div>'}</div></div>`}

function periodAttendance(uid,from,to){return db.attendance.filter(x=>x.user_id===uid&&intervalOverlapsReport(x.clock_in,x.clock_out,from,to))}

function periodHourTotals(uid,from,to){const rows=periodAttendance(uid,from,to),[rangeStart,rangeEnd]=reportRangeBounds(from,to),worked=rows.reduce((a,e)=>a+attendanceNetMinutesBetween(e,rangeStart,rangeEnd),0),monthDate=new Date(from+'T12:00:00'),target=monthlyTargetMinutes(uid,monthDate),ordinary=Math.min(worked,target),additional=Math.max(0,worked-target);return{rows,worked,target,ordinary,additional}}

function printAdminAudit(uid=''){let rows=db.adminAudit;if(uid)rows=rows.filter(x=>x.target_user_id===uid);printSimpleLog('Log administrativo',['Fecha','Entidad','ID','Usuario afectado','Actor','Acción','Antes','Después'],rows.map(a=>[a.created_at,a.entity_type,a.entity_id||'',person(a.target_user_id)?.name||'',person(a.actor_user_id)?.name||'Sistema',a.action,jsonSummary(a.old_data),jsonSummary(a.new_data)]))}

function printAttendance(uid){const u=person(uid),target=monthlyTargetMinutes(uid),worked=monthlyWorkedMinutes(uid),real=monthlyRealMinutes(uid),breaks=monthlyBreakMinutes(uid),remaining=target-worked,rows=db.attendance.filter(x=>x.user_id===uid);const w=window.open('','_blank','width=1100,height=800');if(!w)return notifyMsg('El navegador ha bloqueado la ventana de impresión.','warn');w.document.write(`<html><head><title>Informe de horas · ${esc(u?.name||'')}</title><style>body{font-family:Arial,sans-serif;padding:24px;color:#111}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccc;padding:7px;font-size:12px;text-align:left}h1{margin-bottom:4px}.sum{display:flex;gap:24px;margin:16px 0}.sum b{display:block;font-size:18px}</style></head><body><h1>Informe de horas · ${esc(u?.name||'')}</h1><div>${new Date().toLocaleDateString('es-ES',{month:'long',year:'numeric'})}</div><div class="sum"><div>Presencia real<b>${fmtHours(real)}</b></div><div>Pausas<b>${fmtHours(breaks)}</b></div><div>Computado<b>${fmtHours(worked)}</b></div><div>Objetivo<b>${fmtHours(target)}</b></div><div>${remaining>=0?'Restan':'Extra'}<b>${fmtHours(Math.abs(remaining))}</b></div></div><table><thead><tr><th>Día</th><th>Entrada real</th><th>Salida real</th><th>Computa desde</th><th>Computa hasta</th><th>Pausas</th><th>Minutos</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${attendanceDayLabel(e.clock_in)}</td><td>${dt(e.clock_in)}</td><td>${e.clock_out?dt(e.clock_out):'Abierto'}</td><td>${dt(effectiveStart(e))}</td><td>${e.clock_out?dt(effectiveEnd(e)):'—'}</td><td>${e.break_minutes||0}</td><td>${Math.round(attendanceNetMinutes(e))}</td></tr>`).join('')}</tbody></table><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}

function printAttendanceAudit(uid){const u=person(uid),rows=db.attendanceAudit.filter(x=>x.user_id===uid).map(a=>[a.created_at,a.action,person(a.actor_user_id)?.name||'Sistema/usuario',a.reason||'',jsonSummary(a.old_data),jsonSummary(a.new_data)]);printSimpleLog(`Log de fichajes · ${u?.name||'Empleado'}`,['Fecha','Acción','Actor','Motivo','Antes','Después'],rows)}

function printSimpleLog(title,headers,rows){const w=window.open('','_blank','width=1200,height=800');if(!w)return notifyMsg('El navegador ha bloqueado la ventana de impresión.','warn');const th=headers.map(x=>`<th>${esc(x)}</th>`).join(''),body=rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('');w.document.write(`<html><head><title>${esc(title)}</title><style>body{font-family:Arial,sans-serif;padding:24px;color:#111}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccc;padding:7px;font-size:11px;text-align:left}h1{margin:0 0 14px}</style></head><body><h1>${esc(title)}</h1><table><thead><tr>${th}</tr></thead><tbody>${body}</tbody></table><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}

function printTaskAudit(uid=''){let rows=db.taskAudit;if(uid)rows=rows.filter(x=>db.tasks.find(t=>t.id===x.task_id)?.assigned_to===uid);printSimpleLog('Log de tareas',['Fecha','Tarea','Acción','Actor','Antes','Después'],rows.map(a=>[a.created_at,db.tasks.find(t=>t.id===a.task_id)?.title||a.task_id||'',a.action,person(a.actor_user_id)?.name||'Sistema',jsonSummary(a.old_data),jsonSummary(a.new_data)]))}

function purchasesForWorkReport(){const f=reportFilter(),users=filteredUsers(f.uid);return db.purchases.filter(x=>users.includes(x.user_id)&&(!f.loc||x.location_id===f.loc)&&dateInRange(x.purchase_date||x.created_at,f.from,f.to))}

async function reportDigest(uid,from,to){const h=periodHourTotals(uid,from,to),[rangeStart,rangeEnd]=reportRangeBounds(from,to),rowIds=new Set(h.rows.map(e=>e.id)),breaks=db.breaks.filter(b=>b.user_id===uid&&rowIds.has(b.attendance_entry_id)&&!b.counts_as_work&&intervalMinutesWithin(b.started_at,b.ended_at,rangeStart,rangeEnd)>0).map(b=>({id:b.id,attendance_entry_id:b.attendance_entry_id,type:b.break_type,label:b.break_label||breakName(b.break_type),started_at:b.started_at,ended_at:b.ended_at,minutes:Math.round(intervalMinutesWithin(b.started_at,b.ended_at,rangeStart,rangeEnd)),notes:b.notes||''})),snapshot=h.rows.map(e=>({id:e.id,location_id:e.location_id,clock_in:e.clock_in,clock_out:e.clock_out,effective_in:effectiveStart(e),effective_out:e.clock_out?effectiveEnd(e):null,net_minutes:Math.round(attendanceNetMinutesBetween(e,rangeStart,rangeEnd))}));return sha256Hex(JSON.stringify({uid,from,to,target:Math.round(h.target),ordinary:Math.round(h.ordinary),additional:Math.round(h.additional),total:Math.round(h.worked),rows:snapshot,personal_breaks:breaks}))}

function reportFilter(){const d=defaultReportDates();return{uid:document.getElementById('repUser')?.value||state.reportUserId||me().id,from:document.getElementById('repFrom')?.value||d.from,to:document.getElementById('repTo')?.value||d.to,loc:document.getElementById('repLoc')?.value||''}}

function reportLocationOptions(){return `<option value="">Todas</option>`+db.locations.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}

function reportRangeBounds(from,to){const a=new Date((from||'1970-01-01')+'T00:00:00'),b=new Date((to||'2999-12-31')+'T00:00:00');b.setDate(b.getDate()+1);return[a,b]}

function reportUserOptions(selected){const rows=isAdmin()?db.people.filter(p=>p.role!=='invitado'):[me()].filter(Boolean);return (isAdmin()?`<option value="">Todos los trabajadores</option>`:'')+rows.map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}

function resetPanelWidgets(){localStorage.removeItem(panelKey());closeModal();renderTasks();notifyMsg('Mi panel restablecido.')}

async function resetTaskTimer(){if(!canOperate())return notifyMsg('Tu perfil es de solo lectura.','warn');const cur=openTaskTime();if(!cur)return;const t=db.tasks.find(x=>x.id===cur.task_id);if(!(await askConfirm({title:'Reiniciar reloj',message:'El tramo actual quedará guardado y comenzará otro sin borrar el histórico.',confirmText:'Reiniciar'})))return;const {error}=await sb.rpc('task_timer_reset');if(error){if(/justificar|agotado|autorizado/i.test(error.message)&&t)return justifyTaskOverrun(t.id,error.message);return notifyMsg(error.message,'bad')}await reloadTeamData();tick();renderTasks();notifyMsg('Reloj reiniciado; tramo anterior conservado.')}

async function saveAdminAttendance(uid){const a=isoFromInput(document.getElementById('aaIn').value),b=isoFromInput(document.getElementById('aaOut').value),location=document.getElementById('aaLocation').value,reason=document.getElementById('aaReason').value.trim(),notes=document.getElementById('aaNotes').value.trim();if(!a||!location||reason.length<3)return notifyMsg('Tienda, entrada y motivo son obligatorios.','warn');const {error}=await sb.rpc('attendance_admin_add',{p_user_id:uid,p_location_id:location,p_clock_in:a,p_clock_out:b,p_reason:reason,p_notes:notes||null});if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderTasks();notifyMsg('Fichaje manual añadido y registrado en log.')}

async function saveAttendanceEdit(id){const a=isoFromInput(document.getElementById('aeIn').value),b=isoFromInput(document.getElementById('aeOut').value),location=document.getElementById('aeLocation').value,reason=document.getElementById('aeReason').value.trim(),override=document.getElementById('aeOverride').checked,ei=override?isoFromInput(document.getElementById('aeEffIn').value):null,eo=override?isoFromInput(document.getElementById('aeEffOut').value):null;if(!a||!location||reason.length<3)return notifyMsg('Tienda, entrada y motivo son obligatorios.','warn');const {error}=await sb.rpc('attendance_admin_update',{p_id:id,p_location_id:location,p_clock_in:a,p_clock_out:b,p_reason:reason,p_notes:document.getElementById('aeNotes').value.trim()||null,p_override:override,p_effective_in:ei,p_effective_out:eo});if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderTasks();notifyMsg('Corrección guardada en el log.')}


function savePanelWidgets(){const vals=[...document.querySelectorAll('.panelWidgetChoice:checked')].map(x=>x.value);localStorage.setItem(panelKey(),JSON.stringify(vals));closeModal();renderTasks();notifyMsg('Mi panel actualizado.')}

function setCalendarLayout(v){state.calendarLayout=v;localStorage.setItem('totus_calendar_layout',v);renderTasks()}

function setCalendarScale(v){state.calendarScale=v;localStorage.setItem('totus_calendar_scale',v);renderTasks()}

async function setTargetFullTime(){if(!isAdmin())return;const uid=state.scheduleUserId,month=document.getElementById('targetMonth').value+'-01';const {error}=await sb.from('employee_monthly_targets').upsert({user_id:uid,month,target_minutes:fullTimeDefaultMinutes(),created_by:me().id},{onConflict:'user_id,month'});if(error)return notifyMsg(error.message,'bad');await reloadTeamData();renderTasks();notifyMsg('Objetivo restablecido a 160 h.')}

async function sha256Hex(text){const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return [...new Uint8Array(buf)].map(x=>x.toString(16).padStart(2,'0')).join('')}

function signaturePanelHtml(uid){const fuid=uid||me().id;if(!fuid)return `<div class="note" style="margin-top:12px">Selecciona un empleado para consultar su firma mensual.</div>`;const d=defaultReportDates(),sig=latestSignature(fuid,d.from,d.to),own=fuid===me().id;return `<div class="card signature-panel" style="margin-top:12px"><div class="section-head"><div><div class="eyebrow">Firma mensual</div><h3>${esc(person(fuid)?.name||'Empleado')}</h3><div class="small">La firma se vincula al registro íntegro del mes y a una huella SHA-256.</div></div>${sig?'<span class="badge ok">FIRMADO</span>':'<span class="badge warnb">PENDIENTE</span>'}</div>${sig?`<div class="signature-status"><img src="${esc(sig.signature_data)}" alt="Firma"><div><b>Firmado ${dt(sig.signed_at)}</b><div class="small">Ordinarias ${fmtHours(sig.ordinary_minutes)} · adicionales ${fmtHours(sig.additional_minutes)} · total ${fmtHours(sig.total_minutes)}</div><div class="small digest">SHA-256 ${esc(sig.report_digest)}</div></div></div>`:`<div class="note" style="margin-top:10px">Todavía no existe una firma para el mes actual.</div>`}<div class="actions" style="margin-top:12px">${own&&canOperate()?'<button class="primary" onclick="openSignaturePad()">Firmar mes actual</button>':''}<button class="secondary" onclick="printOfficialWorkReport('${fuid}')">Imprimir registro mensual</button></div></div>`}

function startOfDay(v){const x=new Date(v);return new Date(x.getFullYear(),x.getMonth(),x.getDate())}

function startOfWeek(v){const x=startOfDay(v),d=(x.getDay()+6)%7;return addDays(x,-d)}

async function startPersonalBreak(){const type=document.getElementById('breakType')?.value||'personal',note=document.getElementById('breakNote')?.value.trim()||'';const bt=breakType(type);if(bt?.requires_note&&note.length<5)return notifyMsg('Describe el motivo de esta parada.','warn');const {error}=await sb.rpc('attendance_pause_start',{p_break_type:type,p_notes:note||null});if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();tick();if(state.root==='tasks')renderTasks();notifyMsg(`${breakName(type)} iniciada · NO COMPUTA.`,'warn')}

async function startTaskTimer(taskId){if(!canOperate())return notifyMsg('Tu perfil es de solo lectura.','warn');const current=openTaskTime();if(current&&current.task_id===taskId)return;const {error}=await sb.rpc('task_timer_start',{p_task_id:taskId});if(error){if(/justificar|agotado|autorizado/i.test(error.message))return justifyTaskOverrun(taskId,error.message);return notifyMsg(error.message,'bad')}await reloadTeamData();tick();renderTasks()}

async function submitTaskOverrun(id){const reason=document.getElementById('overrunReason').value.trim(),ext=Math.max(1,Math.min(480,Number(document.getElementById('overrunExtension').value||30)));if(reason.length<5)return notifyMsg('Debes explicar el motivo de la ampliación.','warn');const {error}=await sb.rpc('task_overrun_justify',{p_task_id:id,p_justification:reason,p_extension_minutes:ext});if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();notifyMsg('Ampliación registrada en el histórico.');await startTaskTimer(id)}

function taskAttentionHtml(){const mine=myOpenTasks(),over=mine.filter(t=>t.due_at&&new Date(t.due_at)<new Date()),susp=mine.filter(t=>openTaskInterruption(t.id,t.assigned_to));if(!over.length&&!susp.length)return'';return `<div class="card attention-card"><div class="section-head"><div><div class="eyebrow">Atención</div><h3>Tareas que necesitan acción</h3></div><span class="badge badb">${over.length+susp.length}</span></div><div class="list" style="margin-top:9px">${[...new Set([...over,...susp])].map(taskMiniRow).join('')}</div></div>`}

function taskInterruptionMinutesInReport(taskId,uid,from,to){const[a,b]=reportRangeBounds(from,to);return db.interruptions.filter(x=>x.task_id===taskId&&(!uid||x.user_id===uid)&&x.counts_as_work!==false).reduce((sum,x)=>sum+intervalMinutesWithin(x.started_at,x.ended_at,a,b),0)}

function taskInterruptionsHtml(uid){const rows=db.interruptions.filter(x=>x.user_id===uid).slice(0,300);return `<details class="audit-details" style="margin-top:12px"><summary>Suspensiones de tarea · ${rows.length}</summary><div class="card audit-card"><div class="section-head"><div><h3>Interrupciones justificadas</h3><div class="small">Motivo, nota, inicio, reanudación y duración.</div></div><button class="secondary" onclick="exportTaskInterruptions('${uid}')">Exportar</button></div><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Tarea</th><th>Motivo</th><th>Nota</th><th>Inicio</th><th>Fin</th><th>Duración</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(db.tasks.find(t=>t.id===x.task_id)?.title||'')}</td><td>${esc(interruptionName(x.reason_code))}</td><td>${esc(x.reason_note||'')}</td><td>${dt(x.started_at)}</td><td>${x.ended_at?dt(x.ended_at):'<span class="badge warnb">ACTIVA</span>'}</td><td>${fmtDur(elapsedSec(x.started_at,x.ended_at))}</td></tr>`).join('')||'<tr><td colspan="6" class="small">Sin suspensiones.</td></tr>'}</tbody></table></div></div></details>`}

function taskMiniRow(t){const p=person(t.assigned_to),late=t.due_at&&new Date(t.due_at)<new Date();return `<div class="row" onclick="${isAdmin()?`calendarEditTask('${t.id}')`:`openTaskCard('${t.id}')`}"><div class="grow"><b>${esc(t.title)}</b><div class="meta">${esc(locationName(t.location_id))}${p?' · '+esc(p.name):''}${t.due_at?' · '+dt(t.due_at):''}</div></div><span class="badge ${late?'badb':badgeStatus(t.status)}">${late?'VENCIDA':priorityName(t.priority)}</span></div>`}

function taskOverlapsReport(t,from,to){if(t.starts_at&&t.due_at)return intervalOverlapsReport(t.starts_at,t.due_at,from,to);return dateInRange(t.starts_at||t.due_at||t.created_at,from,to)}

function taskTimeMinutesInReport(taskId,uid,from,to){const[a,b]=reportRangeBounds(from,to);return db.taskTimes.filter(x=>x.task_id===taskId&&(!uid||x.user_id===uid)).reduce((sum,x)=>sum+intervalMinutesWithin(x.started_at,x.stopped_at,a,b),0)}

function teamReportsHtml(){const d=defaultReportDates(),uid=isAdmin()?(state.reportUserId||''):me().id;return `<div class="head"><div><div class="eyebrow">Informes</div><h1>Control exhaustivo de trabajo ${helpIcon('reports','Cómo funcionan los informes')}</h1><p>Selecciona el periodo y obtén el informe completo. Los desgloses quedan disponibles sin llenar la pantalla.</p></div></div><div class="card report-filter-card"><div class="form-grid report-core-filters"><div><label>Usuario</label><select id="repUser" onchange="state.reportUserId=this.value;updateWorkReportPreview()">${reportUserOptions(uid)}</select></div><div><label>Desde</label><input id="repFrom" type="date" value="${d.from}" onchange="updateWorkReportPreview()"></div><div><label>Hasta</label><input id="repTo" type="date" value="${d.to}" onchange="updateWorkReportPreview()"></div><div><label>Tienda</label><select id="repLoc" onchange="updateWorkReportPreview()">${reportLocationOptions()}</select></div></div><div class="actions report-primary-actions"><button class="primary" onclick="exportCompleteWorkReport()">Informe completo CSV</button><button class="secondary" onclick="printOfficialWorkReport()">Informe firmable</button></div><details class="audit-details report-more"><summary>Más exportaciones y desgloses</summary><div class="audit-card actions report-secondary-actions"><button class="secondary" onclick="exportReconciliationRange()">Conciliación por días</button><button class="secondary" onclick="printReconciliationRange()">Imprimir conciliación</button><button class="secondary" onclick="exportFilteredAttendance()">Horas/fichajes</button><button class="secondary" onclick="exportFilteredTasks()">Tareas</button><button class="secondary" onclick="exportFilteredTaskTimes()">Tiempos</button><button class="secondary" onclick="exportFilteredInterruptions()">Interrupciones laborales</button><button class="secondary" onclick="exportFilteredBreaks()">Paradas personales</button><button class="secondary" onclick="exportPhoneUsageReport()">Teléfono / WhatsApp</button><button class="secondary" onclick="exportPurchasesFromWorkReport()">Compras</button><button class="secondary" onclick="exportFilteredWorkAudit()">Auditoría</button></div></details></div><details class="audit-details report-section" ${window.innerWidth>520?'open':''}><summary>Resumen del periodo</summary><div class="audit-card" id="reportPreview">${workReportPreview(uid,d.from,d.to,'')}</div></details><details class="audit-details report-section"><summary>Conciliación jornada / tareas</summary><div class="audit-card report-nested">${reconciliationPreviewHtml(uid)}</div></details><details class="audit-details report-section"><summary>Firma mensual</summary><div class="audit-card report-nested">${signaturePanelHtml(uid)}</div></details>`}

function teamStatusHtml(){const workers=db.people.filter(u=>u.role!=='invitado'),rows=workers.map(u=>{const att=db.attendance.find(x=>x.user_id===u.id&&!x.clock_out),br=openPersonalBreak(u.id),timer=db.taskTimes.find(x=>x.user_id===u.id&&!x.stopped_at),intr=db.interruptions.find(x=>x.user_id===u.id&&!x.ended_at),task=timer?db.tasks.find(t=>t.id===timer.task_id):intr?db.tasks.find(t=>t.id===intr.task_id):null,h=monthlyHourState(u.id),openCount=db.tasks.filter(t=>t.assigned_to===u.id&&!['done','cancelled'].includes(t.status)).length;return `<tr><td><b>${esc(u.name)}</b><div class="small">${esc(u.jobTitle||u.role||'')}</div></td><td>${att?`<span class="badge ok">FICHADO</span>${br?` <span class="badge warnb">${esc(breakName(br.break_type))}</span>`:''}<div class="small">${fmtDur(elapsedSec(att.clock_in))}</div>`:'<span class="badge warnb">FUERA</span>'}</td><td><b>${fmtHours(h.ordinary)}</b><div class="small">restan ${fmtHours(h.remaining)}</div></td><td><span class="badge ${h.additional>0?'warnb':'info'}">${fmtHours(h.additional)} extra</span></td><td>${task?`<b>${esc(task.title)}</b><div class="small">${esc(locationName(task.location_id))} · ${timer?fmtDur(elapsedSec(timer.started_at)):'Suspendida '+fmtDur(elapsedSec(intr.started_at))}</div>`:'<span class="small">Sin tarea activa</span>'}</td><td><b>${openCount}</b></td><td><div class="actions"><button class="ghost" onclick="openEmployeeAttendance('${u.id}')">Fichajes</button><button class="ghost" onclick="openEmployeeControl('${u.id}')">Control</button><button class="ghost" onclick="openEmployeeSchedule('${u.id}')">Horario</button></div></td></tr>`}).join('');return `<div class="card" style="margin-top:12px"><div class="section-head"><div><div class="eyebrow">Administración</div><h3>Estado del equipo</h3><div class="small">Fichaje, horas pendientes/adicionales, tarea activa y pendientes.</div></div><span class="badge info">${workers.length} trabajadores</span></div><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Empleado</th><th>Ahora</th><th>Ordinarias</th><th>Adicionales</th><th>Tarea activa</th><th>Pendientes</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="7" class="small">Sin usuarios activos.</td></tr>'}</tbody></table></div></div>`}

function tick(){const a=openAttendance(),t=openTaskTime(),intr=!t?openTaskInterruption():null,br=openPersonalBreak();const ac=document.getElementById('attendanceClock'),tc=document.getElementById('taskClock'),bc=document.getElementById('breakClock');if(ac)ac.textContent=a?fmtDur(elapsedSec(a.clock_in)):'00:00:00';if(tc)tc.textContent=t?fmtDur(elapsedSec(t.started_at)):intr?fmtDur(elapsedSec(intr.started_at)):'00:00:00';if(bc)bc.textContent=br?fmtDur(elapsedSec(br.started_at)):'00:00:00';const ab=document.getElementById('attendanceMainBtn'),tb=document.getElementById('taskMainBtn'),bb=document.getElementById('breakMainBtn');if(ab){ab.textContent=a?'Salir':'Entrar';ab.disabled=!canOperate()}if(tb){tb.disabled=!t&&!intr;tb.textContent='Ver tarea'}if(bb){bb.disabled=!canOperate()||(!a&&!br);bb.textContent=br?'Fin parada':'Parada'}const at=document.getElementById('attendanceDockTitle'),as=document.getElementById('attendanceDockSub'),tt=document.getElementById('taskDockTitle'),ts=document.getElementById('taskDockSub'),bt=document.getElementById('breakDockTitle'),bs=document.getElementById('breakDockSub');if(at)at.textContent=a?'Jornada en marcha':'Sin fichaje abierto';if(as)as.textContent=a?`Real ${dt(a.clock_in)} · computa desde ${dt(effectiveStart(a))}`:nextAttendanceHint();const task=t?db.tasks.find(x=>x.id===t.task_id):intr?db.tasks.find(x=>x.id===intr.task_id):null;if(tt)tt.textContent=task?`${task.title} · ${locationName(task.location_id)}`:'Sin tarea en marcha';if(ts)ts.textContent=t?'Contando desde '+dt(t.started_at):intr?`Suspendida · ${interruptionName(intr.reason_code)}`:'El reloj de tarea aparecerá aquí.';if(bt)bt.textContent=br?breakName(br.break_type):'Sin pausa personal';if(bs)bs.textContent=br?'Desde '+dt(br.started_at):'Cigarros, llamadas y pausas personales.';document.getElementById('attendanceDock')?.classList.toggle('dock-active',!!a);document.getElementById('taskDock')?.classList.toggle('dock-active',!!t);document.getElementById('breakDock')?.classList.toggle('dock-active',!!br);document.getElementById('breakDock')?.classList.toggle('dock-alert',!!br);document.getElementById('taskDock')?.classList.toggle('dock-alert',!!intr);applyDockWarnings();checkTaskOverrunLive(task,t)}

async function togglePersonalBreak(){if(!canOperate())return notifyMsg('Tu perfil es de solo lectura.','warn');const a=openAttendance(),b=openPersonalBreak();if(!a&&!b)return notifyMsg('Debes estar fichado para iniciar una parada personal.','warn');if(b){const {error}=await sb.rpc('attendance_break_stop');if(error)return notifyMsg(error.message,'bad');await reloadTeamData();tick();if(state.root==='tasks')renderTasks();return notifyMsg(`${breakName(b.break_type)} finalizada.`);}const opts=personalBreakTypes().map(x=>`<option value="${esc(x.code)}">${esc(x.label)} · NO COMPUTA</option>`).join('');modal(`<div class="section-head"><div><div class="eyebrow">Parada personal</div><h3>Registrar tiempo no computable</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="bad-note note" style="margin-top:10px"><b>NO COMPUTA.</b> Este tiempo se descuenta de la jornada. El reloj de tarea se detiene y la parada queda registrada con tipo, hora y duración.</div><div class="form-grid" style="margin-top:12px"><div class="span2"><label>Motivo</label><select id="breakType">${opts}</select></div><div class="span2"><label>Motivo / detalle</label><input id="breakNote" placeholder="En llamadas y WhatsApp es obligatorio indicar el motivo"></div></div><div class="actions" style="margin-top:12px"><button class="danger" onclick="startPersonalBreak()">Iniciar parada no computable</button></div>`)}

function workReportPreview(uid,from,to,loc){const users=filteredUsers(uid),ats=db.attendance.filter(x=>users.includes(x.user_id)&&(!loc||x.location_id===loc)&&intervalOverlapsReport(x.clock_in,x.clock_out,from,to)),tts=db.taskTimes.filter(x=>users.includes(x.user_id)&&intervalOverlapsReport(x.started_at,x.stopped_at,from,to)&&(!loc||db.tasks.find(t=>t.id===x.task_id)?.location_id===loc)),tasks=db.tasks.filter(x=>users.includes(x.assigned_to)&&(!loc||x.location_id===loc)&&taskOverlapsReport(x,from,to)),ints=db.interruptions.filter(x=>users.includes(x.user_id)&&x.counts_as_work!==false&&intervalOverlapsReport(x.started_at,x.ended_at,from,to)&&(!loc||db.tasks.find(t=>t.id===x.task_id)?.location_id===loc)),breaks=db.breaks.filter(x=>users.includes(x.user_id)&&!x.counts_as_work&&intervalOverlapsReport(x.started_at,x.ended_at,from,to)&&(!loc||db.attendance.find(e=>e.id===x.attendance_entry_id)?.location_id===loc));const [rangeStart,rangeEnd]=reportRangeBounds(from,to),worked=ats.reduce((a,e)=>a+attendanceNetMinutesBetween(e,rangeStart,rangeEnd),0),real=ats.reduce((a,e)=>a+intervalMinutesWithin(e.clock_in,e.clock_out,rangeStart,rangeEnd),0),taskMin=tts.reduce((a,x)=>a+intervalMinutesWithin(x.started_at,x.stopped_at,rangeStart,rangeEnd),0),breakMin=breaks.reduce((a,x)=>a+intervalMinutesWithin(x.started_at,x.ended_at,rangeStart,rangeEnd),0),workInt=ints.reduce((a,x)=>a+intervalMinutesWithin(x.started_at,x.ended_at,rangeStart,rangeEnd),0),phonePersonal=breaks.filter(x=>isPhoneActivityCode(x.break_type)).reduce((a,x)=>a+intervalMinutesWithin(x.started_at,x.ended_at,rangeStart,rangeEnd),0),phoneWork=ints.filter(x=>isPhoneActivityCode(x.reason_code)).reduce((a,x)=>a+intervalMinutesWithin(x.started_at,x.ended_at,rangeStart,rangeEnd),0),target=uid?monthlyTargetMinutes(uid,new Date(from+'T12:00:00')):0,ordinary=uid?Math.min(worked,target):worked,additional=uid?Math.max(0,worked-target):0,unassigned=Math.max(0,worked-taskMin-workInt);return `<div class="stats" style="margin-top:12px"><div class="stat"><small>Horas ordinarias</small><strong>${fmtHours(ordinary)}</strong></div><div class="stat"><small>Horas adicionales</small><strong>${fmtHours(additional)}</strong></div><div class="stat"><small>Presencia real</small><strong>${fmtHours(real)}</strong></div><div class="stat"><small>Paradas personales</small><strong>${fmtHours(breakMin)}</strong></div><div class="stat"><small>Teléfono/WhatsApp personal</small><strong>${fmtHours(phonePersonal)}</strong></div><div class="stat"><small>Teléfono/WhatsApp laboral</small><strong>${fmtHours(phoneWork)}</strong></div><div class="stat"><small>Tiempo en tareas</small><strong>${fmtHours(taskMin)}</strong></div><div class="stat"><small>Interrupciones laborales</small><strong>${fmtHours(workInt)}</strong></div><div class="stat"><small>Sin asignar a trabajo</small><strong>${fmtHours(unassigned)}</strong></div><div class="stat"><small>Tareas periodo</small><strong>${tasks.length}</strong></div></div>`}

function newTaskToday(){if(!isAdmin())return notifyMsg('Solo el administrador puede crear tareas.','warn');const loc=db.locations[0]?.id||null,cat=db.taskCategories.find(c=>c.active!==false)?.id||null;state.editTaskId=null;state.taskDraft={title:'',category_id:cat,description:'',starts_at:inputDT(new Date()),due_at:inputDT(new Date(Date.now()+3600000)),assigned_to:db.people.find(p=>p.role!=='admin'&&p.role!=='invitado')?.id||me().id,location_id:loc,priority:'normal',is_private:true,estimated_minutes:30,reminder_minutes:15,requires_evidence:false,recurrence:{enabled:false,frequency:'weekly',interval:1,weekdays:[weekday1(new Date())],until:null,count:0,occurrence:1}};state.root='tasks';state.sub='tasks';renderSubnav();renderTasks()}

function calendarNewTaskOn(date){if(!isAdmin())return;const st=new Date(date+'T09:00:00'),en=new Date(date+'T10:00:00');state.editTaskId=null;state.taskEditorContext='calendar';state.taskDraft={title:'',category_id:db.taskCategories.find(c=>c.active!==false)?.id||null,description:'',starts_at:inputDT(st),due_at:inputDT(en),assigned_to:db.people.find(p=>p.role!=='admin'&&p.role!=='invitado')?.id||me().id,location_id:state.calendarLocationId&&state.calendarLocationId!=='all'?state.calendarLocationId:(db.locations[0]?.id||null),priority:'normal',is_private:true,estimated_minutes:30,reminder_minutes:Number(db.settings.task_rules?.default_reminder_minutes||15),requires_evidence:false,recurrence:{enabled:false,frequency:'weekly',interval:1,weekdays:[weekday1(st)],until:null,count:0,occurrence:1}};modal(taskEditorHtml())}

function taskEditorHtml(){const x=state.taskDraft;if(!x)return'';const r=x.recurrence||{},locs=db.locations.filter(x=>x.active!==false),cats=db.taskCategories.filter(x=>x.active!==false);return `<div class="card task-editor" id="taskEditor"><div class="section-head"><div><div class="eyebrow">${state.editTaskId?'Editar':'Nueva'}</div><h3>${state.editTaskId?'Editar tarea':'Crear tarea'}</h3><div class="small">Completa los bloques en orden. Los campos marcados como obligatorios no pueden quedar vacíos.</div></div><button class="ghost" onclick="cancelTaskEdit()">Cerrar</button></div><div class="form-section"><div class="form-section-title"><b>1 · Qué hay que hacer</b><span>Contenido y clasificación</span></div><div class="form-grid"><div class="span2"><label>Título · obligatorio</label><input id="taskTitle" value="${esc(x.title||'')}" placeholder="Ej. Crear productos recibidos hoy"></div><div><label>Categoría · obligatoria</label><select id="taskCategory"><option value="">Selecciona…</option>${cats.map(c=>`<option value="${c.id}" ${x.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div><label>Prioridad</label><select id="taskPriority">${['low','normal','high','urgent'].map(v=>`<option value="${v}" ${x.priority===v?'selected':''}>${priorityName(v)}</option>`).join('')}</select></div><div class="span4"><label>Descripción / instrucciones</label><textarea id="taskDescription" placeholder="Qué debe hacerse, criterio de terminado, datos necesarios…">${esc(x.description||'')}</textarea></div></div></div><div class="form-section"><div class="form-section-title"><b>2 · Quién y dónde</b><span>Responsable y tienda</span></div><div class="form-grid"><div class="span2"><label>Responsable · obligatorio</label><select id="taskAssigned"><option value="">Selecciona…</option>${db.people.filter(p=>p.role!=='invitado').map(p=>`<option value="${p.id}" ${x.assigned_to===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="span2"><label>Tienda / centro · obligatorio</label><select id="taskLocation"><option value="">Selecciona…</option>${locs.map(l=>`<option value="${l.id}" ${x.location_id===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div></div></div><div class="form-section"><div class="form-section-title"><b>3 · Cuándo y cuánto</b><span>Planificación y control de tiempo</span></div><div class="form-grid"><div><label>Inicio</label><input id="taskStart" type="datetime-local" value="${esc(x.starts_at||'')}"></div><div><label>Vencimiento</label><input id="taskDue" type="datetime-local" value="${esc(x.due_at||'')}"></div><div><label>${helpLabel('Tiempo estimado · min','estimate')}</label><input id="taskEstimate" type="number" min="1" value="${Math.max(1,Number(x.estimated_minutes||30))}"></div><div><label>${helpLabel('Recordatorio · min antes','reminder')}</label><input id="taskReminder" type="number" min="0" max="10080" value="${Number(x.reminder_minutes||15)}"></div></div></div><div class="form-section"><div class="form-section-title"><b>4 · Foto / evidencia</b><span>Opcional por defecto</span></div><label class="evidence-toggle"><input id="taskEvidenceRequired" type="checkbox" ${x.requires_evidence?'checked':''}><span><b>Exigir foto para completar esta tarea</b><small>Si no lo marcas, la foto puede adjuntarse de forma opcional.</small></span></label></div><details class="form-section recurrence-section" ${r.enabled?'open':''}><summary><span><b>5 · Recurrente / repetición</b><small>${r.enabled?'Configurada':'Opcional'}</small></span>${helpIcon('recurrence','Cómo funciona la recurrencia')}</summary><div class="form-grid" style="margin-top:12px"><div><label>Recurrente / repetición</label><select id="taskRepeat" onchange="toggleRecurrenceFields()"><option value="none" ${!r.enabled?'selected':''}>No repetir</option><option value="daily" ${r.enabled&&r.frequency==='daily'?'selected':''}>Cada X días</option><option value="weekly" ${r.enabled&&r.frequency==='weekly'?'selected':''}>Cada X semanas</option><option value="hourly" ${r.enabled&&r.frequency==='hourly'?'selected':''}>Cada X horas</option></select></div><div id="recIntWrap" class="${r.enabled?'':'hidden'}"><label>Intervalo</label><input id="taskInterval" type="number" min="1" max="365" value="${Number(r.interval||1)}"></div><div id="recUntilWrap" class="${r.enabled?'':'hidden'}"><label>Repetir hasta</label><input id="taskUntil" type="date" value="${r.until?String(r.until).slice(0,10):''}"></div><div id="recCountWrap" class="${r.enabled?'':'hidden'}"><label>Nº total de ejecuciones</label><input id="taskCount" type="number" min="0" max="9999" value="${Math.max(0,Number(r.count||0))}"><div class="small">0 = sin límite</div></div><div class="span4 ${r.enabled&&r.frequency==='weekly'?'':'hidden'}" id="recDaysWrap"><label>Días de la semana</label><div class="weekday-picks">${WEEK.map((nm,i)=>`<label><input type="checkbox" class="taskWeekday" value="${i+1}" ${(r.weekdays||[]).map(Number).includes(i+1)?'checked':''}>${nm}</label>`).join('')}</div></div></div></details><div class="note" style="margin-top:12px">Solo administración planifica y reparte. El empleado controla su reloj y puede registrar una interrupción laboral con motivo. Si supera el tiempo autorizado deberá justificar la ampliación.</div><div class="actions sticky-actions"><button class="primary" onclick="saveTask()">${state.editTaskId?'Guardar cambios':'Crear tarea'}</button><button class="secondary" onclick="cancelTaskEdit()">Cancelar</button>${state.editTaskId?`<button class="danger" onclick="cancelTaskAdmin('${state.editTaskId}')">Cancelar tarea</button>`:''}</div></div>`}

async function saveTask(){if(!isAdmin())return notifyMsg('Solo el administrador puede crear o modificar tareas.','warn');const title=document.getElementById('taskTitle').value.trim(),assigned=document.getElementById('taskAssigned').value,location_id=document.getElementById('taskLocation').value,category_id=document.getElementById('taskCategory').value;if(!title||!assigned||!location_id||!category_id)return notifyMsg('Título, categoría, responsable y tienda son obligatorios.','warn');const startRaw=document.getElementById('taskStart').value,dueRaw=document.getElementById('taskDue').value;if(startRaw&&dueRaw&&new Date(dueRaw)<new Date(startRaw))return notifyMsg('La fecha de vencimiento no puede ser anterior al inicio.','warn');const rep=document.getElementById('taskRepeat').value,weekdays=[...document.querySelectorAll('.taskWeekday:checked')].map(x=>Number(x.value)),until=document.getElementById('taskUntil')?.value||null;if(rep!=='none'&&until&&startRaw&&until<String(startRaw).slice(0,10))return notifyMsg('La recurrencia no puede terminar antes de que empiece la tarea.','warn');const recurrence={enabled:rep!=='none',frequency:rep==='none'?null:rep,interval:Math.min(365,Math.max(1,Number(document.getElementById('taskInterval')?.value||1))),weekdays:rep==='weekly'?(weekdays.length?weekdays:[weekday1(new Date(startRaw||Date.now()))]):[],until,count:rep==='none'?0:Math.min(9999,Math.max(0,Number(document.getElementById('taskCount')?.value||0))),occurrence:Math.max(1,Number(state.taskDraft?.recurrence?.occurrence||1))};const row={title,category_id,description:document.getElementById('taskDescription').value.trim(),starts_at:isoFromInput(startRaw),due_at:isoFromInput(dueRaw),priority:document.getElementById('taskPriority').value,assigned_to:assigned,location_id,is_private:true,estimated_minutes:Math.max(1,Number(document.getElementById('taskEstimate').value||30)),reminder_minutes:Math.min(10080,Math.max(0,Number(document.getElementById('taskReminder').value||15))),requires_evidence:document.getElementById('taskEvidenceRequired')?.checked===true,recurrence};let res;if(state.editTaskId)res=await sb.from('team_tasks').update(row).eq('id',state.editTaskId);else res=await sb.from('team_tasks').insert({...row,created_by:me().id,status:'pending'});if(res.error)return notifyMsg(res.error.message,'bad');const ctx=state.taskEditorContext;state.editTaskId=null;state.taskDraft=null;state.taskEditorContext=null;if(ctx==='calendar')closeModal();await reloadTeamData();renderTasks();notifyMsg('Tarea guardada.') }

function taskCard(t){const p=person(t.assigned_to),mine=t.assigned_to===me().id,running=openTaskTime()?.task_id===t.id,suspended=openTaskInterruption(t.id,t.assigned_to),worked=taskWorkedSeconds(t.id,t.assigned_to),late=t.due_at&&new Date(t.due_at)<new Date()&&!['done','cancelled'].includes(t.status),hasHistory=db.taskTimes.some(x=>x.task_id===t.id),closed=['done','cancelled'].includes(t.status),ov=taskOverrunState(t),ev=taskEvidence(t.id),timeBadge=ov.enabled?`<span class="badge ${ov.left<=0?'badb':ov.left<=10?'warnb':'info'}">${ov.left<=0?'Tiempo agotado':Math.ceil(ov.left)+' min libres'}</span>`:'';return `<div class="task-card ${running?'running':''} ${suspended?'suspended':''}" id="task_${t.id}"><div class="task-title"><div class="grow"><b>${esc(t.title)}</b><div class="task-meta"><span class="badge ${badgeStatus(t.status)}">${taskStatusName(t.status)}</span><span class="badge ${t.priority==='urgent'?'badb':t.priority==='high'?'warnb':'info'}">${priorityName(t.priority)}</span><span class="badge info">${esc(locationName(t.location_id))}</span><span class="badge">${esc(taskCategoryName(t.category_id))}</span>${p?`<span class="badge">${esc(p.name)}</span>`:''}${t.recurrence?.enabled?`<span class="badge info">↻ ${esc(recurrenceText(t.recurrence))}</span>`:''}${t.requires_evidence?'<span class="badge warnb">📷 FOTO REQUERIDA</span>':ev.length?'<span class="badge ok">📷 EVIDENCIA</span>':''}${ev.length?`<span class="badge">${ev.length} archivo${ev.length===1?'':'s'}</span>`:''}${timeBadge}${suspended?'<span class="badge warnb">SUSPENDIDA</span>':''}</div></div><div class="num"><b>${fmtDur(worked)}</b><div class="small">tiempo trabajado</div></div></div>${t.description?`<div class="task-desc">${esc(t.description)}</div>`:''}<div class="meta">${t.starts_at?'Inicio '+dt(t.starts_at)+' · ':''}${t.due_at?(late?'⚠ Venció ':'Vence ')+dt(t.due_at):'Sin vencimiento'} · previsto ${Number(t.estimated_minutes||0)} min</div>${t.requires_evidence&&!ev.length&&!closed?'<div class="warn-note note">Esta tarea necesita una foto o evidencia antes de completarse.</div>':''}${suspended?`<div class="warn-note note"><b>${esc(interruptionName(suspended.reason_code))}</b> · suspendida ${fmtDur(elapsedSec(suspended.started_at))}</div>`:''}${ov.enabled&&ov.left<=0&&!closed&&mine?'<div class="bad-note note">Tiempo autorizado agotado. Debes justificar la ampliación antes de continuar o completar.</div>':''}<div class="task-actions">${mine&&!closed&&canOperate()?(running?`<button class="primary" onclick="stopTaskTimer()">Pausar</button><button class="secondary" onclick="resetTaskTimer()">Reiniciar tramo</button><button class="secondary" onclick="suspendTask('${t.id}')">Suspender con motivo</button>`:suspended?`<button class="primary" onclick="resumeTask('${t.id}')">Reanudar</button>`:`<button class="primary" onclick="startTaskTimer('${t.id}')">${hasHistory?'Reanudar':'Iniciar'}</button>`):''}${(mine||isAdmin())&&canOperate()?`<button class="secondary" onclick="openEvidenceUploader('${t.id}')">📷 Añadir foto</button>`:''}${ev.length?`<button class="ghost" onclick="openTaskEvidence('${t.id}')">Ver evidencias</button>`:''}${mine&&!closed&&canOperate()?`<button class="secondary" onclick="completeTask('${t.id}')">Completar</button>`:''}${mine&&!closed&&canOperate()&&ov.enabled&&ov.left<=0?`<button class="danger" onclick="justifyTaskOverrun('${t.id}')">Justificar ampliación</button>`:''}${isAdmin()?`<button class="ghost" onclick="editTask('${t.id}')">Gestionar</button>`:''}</div></div>`}

function taskEvidence(taskId){return (db.evidence||[]).filter(x=>x.task_id===taskId)}
function safeFileName(name){return String(name||'archivo').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9._-]+/g,'_').slice(-120)||'archivo'}
function openEvidenceUploader(taskId){const t=db.tasks.find(x=>x.id===taskId);if(!t)return;modal(`<div class="section-head"><div><div class="eyebrow">Evidencia de tarea</div><h3>${esc(t.title)}</h3><div class="small">La foto es opcional salvo que la tarea indique expresamente “foto requerida”.</div></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="grid g2" style="margin-top:12px"><label class="file-action"><b>📷 Hacer foto</b><span>Usa la cámara del móvil</span><input aria-label="Hacer foto" id="evidenceCamera" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" onchange="previewEvidenceFile(this)"></label><label class="file-action"><b>🖼 Elegir imagen</b><span>Selecciona de la galería</span><input aria-label="Elegir imagen" id="evidenceGallery" type="file" accept="image/jpeg,image/png,image/webp" onchange="previewEvidenceFile(this)"></label></div><div id="evidencePreview" class="evidence-preview hidden"></div><div style="margin-top:12px"><label>Comentario opcional</label><textarea id="evidenceCaption" maxlength="500" placeholder="Qué demuestra esta foto"></textarea></div><div class="actions" style="margin-top:12px"><button class="primary" onclick="submitEvidence('${taskId}')">Subir evidencia</button></div>`) }
function previewEvidenceFile(input){const file=input.files?.[0],box=document.getElementById('evidencePreview');if(!file||!box)return;document.querySelectorAll('#evidenceCamera,#evidenceGallery').forEach(x=>{if(x!==input)x.value=''});const url=URL.createObjectURL(file);box.innerHTML=`<img src="${url}" alt="Vista previa"><div><b>${esc(file.name)}</b><div class="small">${Math.round(file.size/1024)} KB</div></div>`;box.classList.remove('hidden')}
async function submitEvidence(taskId){const a=document.getElementById('evidenceCamera')?.files?.[0],b=document.getElementById('evidenceGallery')?.files?.[0],file=a||b;if(!file)return notifyMsg('Haz una foto o elige una imagen.','warn');if(file.size>10*1024*1024)return notifyMsg('La imagen supera 10 MB.','warn');if(!/^image\/(jpeg|png|webp)$/i.test(file.type))return notifyMsg('Formato no permitido. Usa JPG, PNG o WebP.','warn');const path=`${me().id}/${taskId}/${Date.now()}_${safeFileName(file.name)}`;const up=await sb.storage.from('task-evidence').upload(path,file,{upsert:false,contentType:file.type});if(up.error)return notifyMsg(up.error.message,'bad');const row={task_id:taskId,uploaded_by:me().id,file_path:path,file_name:file.name,file_type:file.type,file_size:file.size,caption:document.getElementById('evidenceCaption').value.trim()||null};const {error}=await sb.from('task_evidence').insert(row);if(error){await sb.storage.from('task-evidence').remove([path]);return notifyMsg(error.message,'bad')}closeModal();await reloadTeamData();renderTasks();notifyMsg('Evidencia guardada.')}
function openTaskEvidence(taskId){const t=db.tasks.find(x=>x.id===taskId),rows=taskEvidence(taskId);modal(`<div class="section-head"><div><div class="eyebrow">Evidencias</div><h3>${esc(t?.title||'Tarea')}</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="evidence-grid" style="margin-top:12px">${rows.map(x=>`<div class="card evidence-card"><b>${esc(x.file_name)}</b><div class="small">${dt(x.created_at)} · ${esc(person(x.uploaded_by)?.name||'')}</div>${x.caption?`<div class="note">${esc(x.caption)}</div>`:''}<div class="actions"><button class="secondary" onclick="openEvidenceFile('${x.id}')">Abrir</button><button class="secondary" onclick="downloadEvidenceFile('${x.id}')">Descargar</button>${isAdmin()?`<button class="danger" onclick="deleteEvidence('${x.id}')">Eliminar</button>`:''}</div></div>`).join('')||'<div class="small">Sin evidencias.</div>'}</div>`)}
async function openEvidenceFile(id){const x=db.evidence.find(v=>v.id===id);if(!x)return;const {data,error}=await sb.storage.from('task-evidence').createSignedUrl(x.file_path,300);if(error)return notifyMsg(error.message,'bad');window.open(data.signedUrl,'_blank','noopener')}
async function downloadEvidenceFile(id){const x=db.evidence.find(v=>v.id===id);if(!x)return;try{await downloadStorageFile('task-evidence',x.file_path,x.file_name||'evidencia')}catch(e){notifyMsg(e.message,'bad')}}
async function deleteEvidenceWithCompensation(x){const dl=await sb.storage.from('task-evidence').download(x.file_path);if(dl.error)throw new Error(`No se pudo preparar la eliminación segura: ${dl.error.message}`);const rm=await sb.storage.from('task-evidence').remove([x.file_path]);if(rm.error)throw new Error(rm.error.message);const {error}=await sb.from('task_evidence').delete().eq('id',x.id);if(error){const restore=await sb.storage.from('task-evidence').upload(x.file_path,dl.data,{upsert:true,contentType:x.file_type||dl.data.type||undefined});if(restore.error)throw new Error(`${error.message}. Además no se pudo reponer el archivo: ${restore.error.message}`);throw new Error(error.message)}return true}
async function deleteEvidence(id){if(!isAdmin())return;const x=db.evidence.find(v=>v.id===id);if(!x)return;if(!await askConfirm({title:'Eliminar evidencia',message:'Se eliminarán el archivo físico y su registro. Esta acción es irreversible.',confirmText:'Eliminar',danger:true}))return;try{await deleteEvidenceWithCompensation(x)}catch(e){return notifyMsg(e.message,'bad')}await reloadTeamData();closeModal();renderTasks();notifyMsg('Evidencia eliminada.')}

function leaveRequestRows(uid){return (db.leaveRequests||[]).filter(x=>x.user_id===uid)}
function leaveRequestStatus(s){return({pending:'Pendiente',approved:'Aprobada',rejected:'Rechazada',cancelled:'Cancelada'}[s]||s)}
function leaveRequestsHtml(uid,compact=false){const rows=leaveRequestRows(uid).slice(0,compact?4:100);return `<div class="leave-requests"><div class="section-head"><div><h4>Solicitudes</h4><div class="small">Las vacaciones solo pasan al calendario cuando administración las aprueba.</div></div>${uid===me().id&&canOperate()?'<button class="primary" onclick="newLeaveRequest()">+ Solicitar ausencia</button>':''}</div><div class="list">${rows.map(x=>`<div class="list-row"><div class="grow"><b>${esc(x.label||absenceTypeName(x.leave_type_code))}</b><div class="small">${d(x.start_date)} → ${d(x.end_date)} · ${Number(x.natural_days||0)} días naturales</div>${x.decision_note?`<div class="small">${esc(x.decision_note)}</div>`:''}</div><span class="badge ${x.status==='approved'?'ok':x.status==='rejected'?'badb':x.status==='cancelled'?'':'warnb'}">${leaveRequestStatus(x.status)}</span>${x.status==='pending'&&uid===me().id?`<button class="ghost" onclick="cancelLeaveRequest('${x.id}')">Cancelar</button>`:''}${isAdmin()&&x.status==='pending'?`<button class="primary" onclick="decideLeaveRequest('${x.id}','approved')">Aprobar</button><button class="danger" onclick="decideLeaveRequest('${x.id}','rejected')">Rechazar</button>`:''}</div>`).join('')||'<div class="small">Sin solicitudes.</div>'}</div></div>`}
function newLeaveRequest(){const types=(db.leaveTypes||[]).filter(x=>x.active!==false&&x.code!=='gift');modal(`<div class="section-head"><div><div class="eyebrow">Vacaciones y ausencias</div><h3>Nueva solicitud</h3><div class="small">Vacaciones se cuentan en días naturales, incluidos fines de semana y festivos.</div></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid" style="margin-top:12px"><div><label>Tipo</label><select id="reqLeaveType">${types.map(x=>`<option value="${esc(x.code)}">${esc(x.label)}</option>`).join('')}</select></div><div><label>Desde</label><input id="reqLeaveStart" type="date"></div><div><label>Hasta</label><input id="reqLeaveEnd" type="date"></div><div class="span4"><label>Motivo / notas</label><textarea id="reqLeaveNotes" maxlength="1500"></textarea></div></div><div class="actions" style="margin-top:12px"><button class="primary" onclick="submitLeaveRequest()">Enviar solicitud</button></div>`)}
async function submitLeaveRequest(){const leave_type_code=document.getElementById('reqLeaveType').value,start_date=document.getElementById('reqLeaveStart').value,end_date=document.getElementById('reqLeaveEnd').value,notes=document.getElementById('reqLeaveNotes').value.trim();if(!start_date||!end_date||end_date<start_date)return notifyMsg('Revisa las fechas.','warn');if(leave_type_code==='gift')return notifyMsg('Los días regalo solo puede asignarlos administración.','warn');const natural_days=naturalDaysOverlap(start_date,end_date,start_date,end_date);const label=(db.leaveTypes.find(x=>x.code===leave_type_code)?.label)||absenceTypeName(leave_type_code);const {error}=await sb.from('employee_leave_requests').insert({user_id:me().id,leave_type_code,start_date,end_date,label,notes:notes||null,status:'pending',natural_days});if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderTasks();notifyMsg('Solicitud enviada a administración.')}
async function cancelLeaveRequest(id){const x=db.leaveRequests.find(v=>v.id===id);if(!x||x.user_id!==me().id||x.status!=='pending')return;const {error}=await sb.from('employee_leave_requests').update({status:'cancelled',cancelled_at:new Date().toISOString(),cancel_reason:'Cancelada por el solicitante'}).eq('id',id);if(error)return notifyMsg(error.message,'bad');await reloadTeamData();renderTasks();notifyMsg('Solicitud cancelada.')}
async function decideLeaveRequest(id,decision){if(!isAdmin())return;let note='';if(decision==='rejected'){note=await askText('Motivo del rechazo','Indica por qué se rechaza la solicitud.');if(!note)return}const {error}=await sb.rpc('admin_decide_leave_request',{p_request_id:id,p_decision:decision,p_note:note||null});if(error)return notifyMsg(error.message,'bad');await reloadTeamData();renderTasks();notifyMsg(decision==='approved'?'Solicitud aprobada.':'Solicitud rechazada.')}
function askText(title,message){return new Promise(resolve=>{modal(`<div class="section-head"><div><div class="eyebrow">Administración</div><h3>${esc(title)}</h3></div></div><div class="note" style="margin-top:12px">${esc(message)}</div><textarea id="textAnswer" style="margin-top:12px" maxlength="1500"></textarea><div class="actions" style="margin-top:12px"><button class="primary" id="textOk">Guardar</button><button class="secondary" id="textCancel">Cancelar</button></div>`);document.getElementById('textOk').onclick=()=>{const v=document.getElementById('textAnswer').value.trim();if(v.length<3)return notifyMsg('Escribe un motivo.','warn');closeModal();resolve(v)};document.getElementById('textCancel').onclick=()=>{closeModal();resolve('')}})}

function myNotifications(uid){return (db.notifications||[]).filter(x=>x.target_user_id===uid&&x.status==='active'&&(!x.expires_at||new Date(x.expires_at)>new Date()))}
function notificationsPanelHtml(uid){const rows=myNotifications(uid).slice(0,8),pending=rows.filter(x=>!x.read_at||x.requires_ack&&!x.acknowledged_at).length;return `<div class="card panel-widget notifications-widget"><div class="section-head"><div><div class="eyebrow">Avisos</div><h3>Mensajes del administrador</h3></div><div class="actions"><span class="badge ${pending?'warnb':'ok'}">${pending} pendiente${pending===1?'':'s'}</span>${isAdmin()?`<button class="primary" onclick="newAdminNotification('${uid}')">+ Enviar aviso</button>`:''}</div></div><div class="notification-list">${rows.map(x=>{const linked=x.task_id?db.tasks.find(t=>t.id===x.task_id):null;return `<div class="notification-row ${x.notification_type} ${x.read_at?'read':''}"><div class="grow"><b>${esc(x.title)}</b><span>${esc(x.message)}</span><small>${dt(x.created_at)}${x.requires_ack?' · requiere confirmación':''}${linked?' · '+esc(linked.title):''}</small></div>${linked?`<button class="secondary" onclick="openTaskCard('${linked.id}')">Abrir tarea</button>`:''}${uid===me().id&&!x.read_at?`<button class="secondary" onclick="markNotification('${x.id}',false)">Leído</button>`:''}${uid===me().id&&x.requires_ack&&!x.acknowledged_at?`<button class="primary" onclick="markNotification('${x.id}',true)">Confirmar</button>`:''}${isAdmin()?`<button class="ghost" onclick="cancelNotification('${x.id}')">Cancelar</button>`:''}</div>`}).join('')||'<div class="empty-state compact"><b>Sin avisos activos</b><span>No hay mensajes pendientes.</span></div>'}</div></div>`}
function noticeTaskOptions(uid){const rows=db.tasks.filter(t=>t.assigned_to===uid&&!['done','cancelled'].includes(t.status)).sort((a,b)=>new Date(a.due_at||a.starts_at||0)-new Date(b.due_at||b.starts_at||0));return `<option value="">Sin tarea vinculada</option>`+rows.map(t=>`<option value="${t.id}">${esc(t.title)}${t.due_at?' · '+d(t.due_at):''}</option>`).join('')}
function refreshNoticeTaskOptions(){const u=document.getElementById('noticeUser'),t=document.getElementById('noticeTask');if(u&&t)t.innerHTML=noticeTaskOptions(u.value)}
function newAdminNotification(uid=''){if(!isAdmin())return;const initial=uid||db.people.find(p=>p.role!=='invitado')?.id||'';modal(`<div class="section-head"><div><div class="eyebrow">Avisos</div><h3>Enviar mensaje interno</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid" style="margin-top:12px"><div class="span2"><label>Destinatario</label><select id="noticeUser" onchange="refreshNoticeTaskOptions()">${db.people.filter(p=>p.role!=='invitado').map(p=>`<option value="${p.id}" ${initial===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="span2"><label>Tarea vinculada · opcional</label><select id="noticeTask">${noticeTaskOptions(initial)}</select></div><div><label>Tipo</label><select id="noticeType"><option value="recordatorio">Recordatorio</option><option value="aviso" selected>Aviso</option><option value="atencion">Toque de atención</option></select></div><div><label class="compact-check"><input id="noticeSound" type="checkbox" checked><span>Sonido</span></label><label class="compact-check"><input id="noticeAck" type="checkbox"><span>Confirmación obligatoria</span></label></div><div class="span4"><label>Título</label><input id="noticeTitle" maxlength="120"></div><div class="span4"><label>Mensaje</label><textarea id="noticeMessage" maxlength="1000"></textarea></div></div><div class="actions" style="margin-top:12px"><button class="primary" onclick="sendAdminNotification()">Enviar aviso</button></div>`)}
async function sendAdminNotification(){const target_user_id=document.getElementById('noticeUser').value,title=document.getElementById('noticeTitle').value.trim(),message=document.getElementById('noticeMessage').value.trim();if(title.length<3||message.length<3)return notifyMsg('Título y mensaje son obligatorios.','warn');const row={target_user_id,title,message,notification_type:document.getElementById('noticeType').value,sound:document.getElementById('noticeSound').checked,requires_ack:document.getElementById('noticeAck').checked,task_id:document.getElementById('noticeTask')?.value||null,created_by:me().id,status:'active'};const {error}=await sb.from('team_notifications').insert(row);if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderTasks();notifyMsg('Aviso enviado.')}
async function markNotification(id,ack=false){const {error}=await sb.rpc('mark_team_notification',{p_notification_id:id,p_acknowledge:ack});if(error)return notifyMsg(error.message,'bad');await reloadTeamData();renderTasks();notifyMsg(ack?'Aviso confirmado.':'Aviso marcado como leído.')}
async function cancelNotification(id){if(!isAdmin())return;const reason=await askText('Cancelar aviso','Indica el motivo de la cancelación.');if(!reason)return;const {error}=await sb.from('team_notifications').update({status:'cancelled',cancelled_at:new Date().toISOString(),cancelled_by:me().id,cancel_reason:reason}).eq('id',id);if(error)return notifyMsg(error.message,'bad');await reloadTeamData();renderTasks();notifyMsg('Aviso cancelado.')}

function questionsHtml(){const own=isAdmin()?db.questions:db.questions.filter(x=>x.asked_by===me().id||['answered','closed'].includes(x.status)),qv=(state.questionSearch||'').toLowerCase(),rows=own.filter(x=>state.questionStatus==='all'||x.status===state.questionStatus).filter(x=>!qv||[x.question,x.answer,person(x.asked_by)?.name,x.category].join(' ').toLowerCase().includes(qv));return `<div class="head"><div><div class="eyebrow">Consultas internas</div><h1>Preguntas y respuestas guardadas</h1><p>El equipo puede consultar; administración responde y el histórico queda disponible para futuras dudas.</p></div><button class="primary" onclick="newInternalQuestion()">+ Nueva consulta</button></div><div class="card"><div class="form-grid"><div class="span2"><label>Buscar</label><input id="questionSearch" value="${esc(state.questionSearch||'')}" placeholder="Pregunta, respuesta, persona…" oninput="state.questionSearch=this.value;renderLibrary()"></div><div><label>Estado</label><select onchange="state.questionStatus=this.value;document.getElementById('main').innerHTML=questionsHtml()"><option value="all" ${state.questionStatus==='all'?'selected':''}>Todos</option><option value="pending" ${state.questionStatus==='pending'?'selected':''}>Pendientes</option><option value="answered" ${state.questionStatus==='answered'?'selected':''}>Respondidos</option><option value="closed" ${state.questionStatus==='closed'?'selected':''}>Cerrados</option></select></div><div><label>Registros</label><div class="filter-count">${rows.length}</div></div></div></div><div class="list" style="margin-top:12px">${rows.map(x=>`<div class="card question-card"><div class="section-head"><div><span class="badge ${x.status==='pending'?'warnb':'ok'}">${x.status==='pending'?'PENDIENTE':x.status==='answered'?'RESPONDIDA':'CERRADA'}</span><h3>${esc(x.question)}</h3><div class="small">${esc(person(x.asked_by)?.name||'')} · ${dt(x.created_at)} · ${esc(x.category)}</div></div>${isAdmin()&&x.status==='pending'?`<button class="primary" onclick="answerInternalQuestion('${x.id}')">Responder</button>`:''}</div>${x.answer?`<div class="question-answer"><b>Respuesta</b><p>${esc(x.answer)}</p><small>${esc(person(x.answered_by)?.name||'Administración')} · ${dt(x.answered_at)}</small></div>`:''}</div>`).join('')||'<div class="empty-state big"><b>Sin consultas</b><span>No hay resultados para este filtro.</span></div>'}</div>`}
function newInternalQuestion(){modal(`<div class="section-head"><div><div class="eyebrow">Consulta interna</div><h3>Nueva pregunta</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="form-grid" style="margin-top:12px"><div><label>Categoría</label><select id="questionCategory"><option value="consulta">Consulta</option><option value="procedimiento">Procedimiento</option><option value="prestashop">PrestaShop</option><option value="producto">Producto</option><option value="tienda">Tienda</option><option value="otro">Otro</option></select></div><div class="span4"><label>Pregunta</label><textarea id="questionText" maxlength="2000" placeholder="Escribe la duda con suficiente detalle"></textarea></div></div><div class="actions"><button class="primary" onclick="submitInternalQuestion()">Guardar consulta</button></div>`)}
async function submitInternalQuestion(){const question=document.getElementById('questionText').value.trim();if(question.length<5)return notifyMsg('Escribe una pregunta más concreta.','warn');const {error}=await sb.from('internal_questions').insert({asked_by:me().id,category:document.getElementById('questionCategory').value,question,status:'pending'});if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderLibrary();notifyMsg('Consulta guardada.')}
function answerInternalQuestion(id){const x=db.questions.find(v=>v.id===id);if(!x||!isAdmin())return;modal(`<div class="section-head"><div><div class="eyebrow">Responder consulta</div><h3>${esc(x.question)}</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><textarea id="questionAnswer" maxlength="5000" style="margin-top:12px" placeholder="Respuesta para el equipo"></textarea><div class="actions" style="margin-top:12px"><button class="primary" onclick="saveInternalAnswer('${id}')">Guardar respuesta</button></div>`)}
async function saveInternalAnswer(id){const answer=document.getElementById('questionAnswer').value.trim();if(answer.length<3)return notifyMsg('Escribe la respuesta.','warn');const {error}=await sb.from('internal_questions').update({answer,status:'answered',answered_by:me().id,answered_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',id);if(error)return notifyMsg(error.message,'bad');closeModal();await reloadTeamData();renderLibrary();notifyMsg('Respuesta guardada en histórico.')}

const BACKUP_TABLES=['team_members','profiles','team_locations','team_app_settings','employee_schedules','employee_schedule_exceptions','location_opening_hours','location_opening_exceptions','attendance_break_types','task_categories','employee_monthly_targets','attendance_entries','attendance_breaks','team_tasks','task_time_entries','task_interruptions','task_overrun_justifications','work_report_signatures','employee_purchases','employee_leave_settings','employee_leave_periods','employee_leave_requests','employee_leave_types','team_holidays','team_notifications','task_evidence','internal_library','internal_questions','brands','families','products','product_variants','providers','product_provider_prices','product_competitor_prices','consultations','consultation_history','price_history','task_time_audit_log','team_task_audit_log','team_admin_audit_log','attendance_audit_log','employee_purchase_audit_log','internal_library_audit_log','team_user_audit_log','team_email_log','employee_leave_audit_log','admin_maintenance_log'];
const BACKUP_VERSION=2;
const BACKUP_FILE_BUCKETS=['task-evidence','internal-library','user-avatars'];
function bytesToBase64(bytes){let out='';for(let i=0;i<bytes.length;i+=0x8000)out+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(out)}
function base64ToBytes(s){const raw=atob(s),out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out}
async function sha256Text(text){const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return [...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('')}
function libraryBackupFileRefs(){const refs=new Map();for(const item of db.library||[]){if(item.file_path)refs.set(item.file_path,{path:item.file_path,type:item.file_type||null,name:item.file_name||null})}for(const a of db.libraryAudit||[]){let old=a.old_data||{};if(typeof old==='string'){try{old=JSON.parse(old)}catch{old={}}}if(old.file_path&&!refs.has(old.file_path))refs.set(old.file_path,{path:old.file_path,type:old.file_type||null,name:old.file_name||null})}return [...refs.values()]}
function avatarBackupFileRefs(data){const refs=new Map();for(const table of ['team_members','profiles'])for(const row of data?.[table]||[]){const path=row?.avatar_path;if(path&&!refs.has(path))refs.set(path,{path,type:null,name:path.split('/').pop()||null})}return [...refs.values()]}
async function collectBackupFiles(data){const out=[],seen=new Set(),collect=async(bucket,ref)=>{if(!ref?.path)return;const key=bucket+'|'+ref.path;if(seen.has(key))return;seen.add(key);const {data:blob,error}=await sb.storage.from(bucket).download(ref.path);if(error||!blob)throw new Error(`Backup incompleto: no se pudo leer ${bucket}/${ref.path}${error?': '+error.message:''}`);out.push({bucket,path:ref.path,type:ref.type||blob.type||'application/octet-stream',name:ref.name||null,data:bytesToBase64(new Uint8Array(await blob.arrayBuffer()))})};for(const item of db.evidence||[])await collect('task-evidence',{path:item.file_path,type:item.file_type,name:item.file_name});for(const ref of libraryBackupFileRefs())await collect('internal-library',ref);for(const ref of avatarBackupFileRefs(data))await collect('user-avatars',ref);return out}
async function buildPortableBackup(){if(!isAdmin())throw new Error('Solo administración puede crear backups completos');const data={};for(const table of BACKUP_TABLES)data[table]=await qAllBackup(table,'*');const files=await collectBackupFiles(data),rowCount=Object.values(data).reduce((n,a)=>n+(Array.isArray(a)?a.length:0),0),payload={format:'totusbackup',version:BACKUP_VERSION,created_at:new Date().toISOString(),created_by:me().id,scope:'full',manifest:{tables:BACKUP_TABLES.length,rows:rowCount,files:files.length,buckets:[...new Set(files.map(f=>f.bucket))],excludes:['Archivo histórico de backups privados (evita copias recursivas)']},data,files};payload.checksum=await sha256Text(JSON.stringify(payload));return payload}
function downloadBlob(name,blob){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function downloadPortableBackup(savePrivate=false){if(!isAdmin())return;notifyMsg('Preparando backup completo…');try{const payload=await buildPortableBackup(),text=JSON.stringify(payload),name=`TOTUS_${new Date().toISOString().replace(/[:.]/g,'-')}.totusbackup`;downloadBlob(name,new Blob([text],{type:'application/json'}));if(savePrivate)await saveBackupPrivate(payload,name,text);notifyMsg(savePrivate?'Backup descargado y guardado en Totus.':'Backup descargado.')}catch(e){notifyMsg(e.message||'No se pudo crear el backup completo.','bad')}}
async function saveBackupPrivate(payload,name,text=null){if(!isAdmin())throw new Error('Solo administración puede guardar backups');text=text||JSON.stringify(payload);const path=`${new Date().toISOString().slice(0,10)}/${Date.now()}_${safeFileName(name)}`,blob=new Blob([text],{type:'application/json'}),up=await sb.storage.from('totus-backups').upload(path,blob,{upsert:false,contentType:'application/json'});if(up.error)throw new Error(up.error.message);const {error}=await sb.from('admin_backups').insert({created_by:me().id,scope:'full',file_path:path,file_name:name,file_size:blob.size,notes:'Backup portable Totus'});if(error){await sb.storage.from('totus-backups').remove([path]);throw new Error(error.message)}await reloadTeamData();renderGeneralLog();return path}
function validBackupPath(path){return typeof path==='string'&&path.length>0&&path.length<=500&&!path.startsWith('/')&&!path.includes('\\')&&!path.split('/').some(p=>p===''||p==='.'||p==='..')}
function validateBackupPayload(obj){if(!obj||obj.format!=='totusbackup'||![1,BACKUP_VERSION].includes(Number(obj.version)))throw new Error('Formato o versión no reconocidos');if(!obj.data||typeof obj.data!=='object'||Array.isArray(obj.data))throw new Error('Bloque de datos no válido');const keys=Object.keys(obj.data),allowed=new Set(BACKUP_TABLES),unknown=keys.filter(k=>!allowed.has(k)),missing=BACKUP_TABLES.filter(k=>!keys.includes(k));if(unknown.length)throw new Error('El backup contiene tablas no autorizadas: '+unknown.join(', '));if(missing.length)throw new Error('El backup está incompleto; faltan tablas: '+missing.join(', '));for(const table of BACKUP_TABLES)if(!Array.isArray(obj.data[table]))throw new Error(`Datos no válidos en ${table}`);if(!Array.isArray(obj.files))throw new Error('Bloque de archivos no válido');const allowedBuckets=new Set(Number(obj.version)>=2?BACKUP_FILE_BUCKETS:['task-evidence','internal-library']),seen=new Set();for(const f of obj.files){if(!f||!allowedBuckets.has(f.bucket))throw new Error('Bucket de archivo no autorizado');if(!validBackupPath(f.path))throw new Error('Ruta de archivo no válida');const key=f.bucket+'|'+f.path;if(seen.has(key))throw new Error('Archivo duplicado en backup: '+f.path);seen.add(key);if(typeof f.data!=='string')throw new Error('Contenido binario no válido: '+f.path);try{base64ToBytes(f.data)}catch{throw new Error('Base64 no válido: '+f.path)}}return true}
async function loadBackupFile(input){const file=input.files?.[0];if(!file)return;try{const text=await file.text(),obj=JSON.parse(text);validateBackupPayload(obj);const check=obj.checksum;if(typeof check!=='string'||!/^[a-f0-9]{64}$/i.test(check))throw new Error('Checksum ausente o no válido');const canonical={...obj};delete canonical.checksum;const calc=await sha256Text(JSON.stringify(canonical));if(calc!==check)throw new Error('Checksum no válido');state.backupLoaded=obj;state.backupLoadedName=safeFileName(file.name||`TOTUS_CARGADO_${Date.now()}.totusbackup`);state.backupLoadedText=text;renderGeneralLog();notifyMsg('Backup validado correctamente.')}catch(e){state.backupLoaded=null;state.backupLoadedName='';state.backupLoadedText='';notifyMsg('Backup no válido: '+e.message,'bad')}finally{input.value=''}}
async function saveLoadedBackupPrivate(){if(!isAdmin()||!state.backupLoaded)return;try{await saveBackupPrivate(state.backupLoaded,state.backupLoadedName||`TOTUS_CARGADO_${Date.now()}.totusbackup`,state.backupLoadedText||JSON.stringify(state.backupLoaded));notifyMsg('Backup cargado guardado en la zona privada de Totus.')}catch(e){notifyMsg(e.message,'bad')}}
async function restoreLoadedBackup(){if(!isAdmin()||!state.backupLoaded)return;const ok=await askConfirm({title:'Restaurar backup',message:'Antes de tocar datos, Totus descargará y guardará una copia privada del estado actual. La restauración hace upsert y no borra automáticamente datos posteriores.',confirmText:'RESTAURAR',danger:true,requireText:'RESTAURAR'});if(!ok)return;notifyMsg('Creando backup de seguridad previo…');try{await createSafetyBackup('PRE_RESTORE')}catch(e){return notifyMsg('Restauración cancelada: no se pudo crear el backup previo. '+e.message,'bad')}const b=state.backupLoaded;try{validateBackupPayload(b)}catch(e){return notifyMsg('Backup no válido: '+e.message,'bad')}for(const table of BACKUP_TABLES){const rows=b.data?.[table];if(!Array.isArray(rows)||!rows.length)continue;const {error}=await sb.rpc('admin_restore_backup_table',{p_table:table,p_rows:rows});if(error)return notifyMsg(`Restauración detenida en ${table}: ${error.message}`,'bad')}const allowedBuckets=new Set(Number(b.version)>=2?BACKUP_FILE_BUCKETS:['task-evidence','internal-library']);for(const f of b.files||[]){if(!allowedBuckets.has(f.bucket)||!f.path)continue;const blob=new Blob([base64ToBytes(f.data)],{type:f.type||'application/octet-stream'});const up=await sb.storage.from(f.bucket).upload(f.path,blob,{upsert:true,contentType:f.type||undefined});if(up.error)return notifyMsg(`No se pudo restaurar ${f.path}: ${up.error.message}`,'bad')}await reloadTeamData();state.backupLoaded=null;state.backupLoadedName='';state.backupLoadedText='';renderGeneralLog();notifyMsg('Backup restaurado y copia previa guardada.')}
async function openStoredBackup(id){const x=db.backups.find(v=>v.id===id);if(!x)return;const {data,error}=await sb.storage.from('totus-backups').createSignedUrl(x.file_path,300);if(error)return notifyMsg(error.message,'bad');window.open(data.signedUrl,'_blank','noopener')}
function backupCoverageModal(){modal(`<div class="section-head"><div><div class="eyebrow">Backup portable</div><h3>Qué guarda Totus</h3></div><button class="ghost" onclick="closeModal()">Cerrar</button></div><div class="backup-coverage"><div><b>Equipo y configuración</b><span>Usuarios y perfiles, permisos, tiendas, reglas, categorías, horarios, temporadas, excepciones, festivos y objetivos.</span></div><div><b>Actividad e histórico</b><span>Tareas, tiempos, interrupciones, fichajes, pausas, compras, vacaciones, ausencias, avisos, consultas e historiales de auditoría.</span></div><div><b>Archivos reales</b><span>Fotos/evidencias de tareas, documentos y tutoriales internos y avatares de usuario. Se guardan dentro del .totusbackup, no solo sus rutas.</span></div><div><b>Seguridad de restauración</b><span>Checksum SHA-256, validación previa, lista cerrada de tablas y copia automática de seguridad antes de restaurar.</span></div></div><div class="note" style="margin-top:12px"><b>Exclusión intencionada:</b> el archivo histórico de backups privados no se mete dentro de cada nuevo backup para evitar una copia recursiva que crecería indefinidamente. El estado operativo, configuración e histórico de la herramienta sí queda incluido.</div>`)}
function maintenanceHtml(){if(!isAdmin())return '<div class="empty-state big"><b>Zona restringida</b><span>Solo administración puede acceder a mantenimiento.</span></div>';const loaded=state.backupLoaded;return `<div class="head"><div><div class="eyebrow">Administración</div><h1>Backup, informes y limpieza</h1><p>Copias portables con datos y archivos, restauración validada y limpiezas con confirmación fuerte.</p></div></div><div class="grid g2"><div class="card"><h3>Backup completo</h3><p class="small">Copia portable del estado operativo, configuración, histórico y archivos reales de Totus con checksum SHA-256.</p><div class="backup-scope-line"><span>Usuarios y permisos</span><span>Configuración</span><span>Histórico</span><span>Archivos y avatares</span></div><div class="actions"><button class="primary" onclick="downloadPortableBackup(false)">Descargar backup</button><button class="secondary" onclick="downloadPortableBackup(true)">Descargar + guardar en Totus</button><button class="ghost" onclick="backupCoverageModal()">¿Qué guarda?</button></div><label class="file-action" style="margin-top:12px"><b>⬆ Cargar backup</b><span>Selecciona un .totusbackup guardado anteriormente</span><input aria-label="Seleccionar backup" type="file" accept=".totusbackup,application/json" onchange="loadBackupFile(this)"></label>${loaded?`<div class="note ok-note"><b>Backup validado · versión ${Number(loaded.version||1)}</b><div class="small">${esc(loaded.created_at)} · ${(loaded.files||[]).length} archivos · ${Object.values(loaded.data||{}).reduce((n,a)=>n+(Array.isArray(a)?a.length:0),0)} registros</div><div class="actions" style="margin-top:8px"><button class="secondary" onclick="saveLoadedBackupPrivate()">Guardar copia en Totus</button><button class="danger" onclick="restoreLoadedBackup()">Restaurar este backup</button></div></div>`:''}</div><div class="card"><h3>Copias privadas</h3><div class="list">${db.backups.slice(0,12).map(x=>`<div class="list-row"><div><b>${esc(x.file_name)}</b><div class="small">${dt(x.created_at)} · ${Math.round(Number(x.file_size||0)/1024)} KB</div></div><button class="secondary" onclick="openStoredBackup('${x.id}')">Abrir</button></div>`).join('')||'<div class="small">Sin copias guardadas.</div>'}</div></div></div><div class="card" style="margin-top:12px"><div class="section-head"><div><h3>Limpieza controlada</h3><div class="small">Toda limpieza pide motivo y confirmación. El reset operativo conserva usuarios, tiendas, festivos, horarios y configuración.</div></div></div><div class="form-grid"><div><label>Antes de</label><input id="purgeBefore" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="span2"><label>Motivo</label><input id="purgeReason" placeholder="Motivo administrativo"></div></div><div class="actions" style="margin-top:12px"><button class="secondary" onclick="runPurge('logs')">Limpiar logs antiguos</button><button class="secondary" onclick="runPurge('notifications')">Avisos cancelados</button><button class="secondary" onclick="runPurge('requests')">Solicitudes resueltas</button><button class="secondary" onclick="cleanupClosedTaskEvidence()">Fotos antiguas de tareas cerradas</button><button class="danger" onclick="runPurge('library')">Vaciar biblioteca y consultas</button><button class="danger" onclick="runPurge('operational')">Reset actividad operativa</button></div></div><div class="card" style="margin-top:12px"><h3>Histórico de mantenimiento</h3><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Acción</th><th>Ámbito</th><th>Detalle</th></tr></thead><tbody>${db.maintenanceLog.slice(0,100).map(x=>`<tr><td>${dt(x.created_at)}</td><td>${esc(x.action)}</td><td>${esc(x.scope||'')}</td><td class="small">${esc(x.detail||'')}</td></tr>`).join('')||'<tr><td colspan="4" class="small">Sin operaciones.</td></tr>'}</tbody></table></div></div>`}
function purgeStorageTargets(scope){if(scope==='operational')return{'task-evidence':[...new Set((db.evidence||[]).map(x=>x.file_path).filter(Boolean))]};if(scope==='library')return{'internal-library':[...new Set(libraryBackupFileRefs().map(x=>x.path).filter(Boolean))]};return{}}
async function removeStoragePaths(bucket,paths){const list=[...new Set(paths||[])].filter(Boolean);for(let i=0;i<list.length;i+=100){const chunk=list.slice(i,i+100);let last=null;for(let attempt=0;attempt<3;attempt++){const r=await sb.storage.from(bucket).remove(chunk);if(!r.error){last=null;break}last=r.error;await new Promise(r=>setTimeout(r,200*(attempt+1)))}if(last)throw new Error(`${bucket}: ${last.message}`)}return list.length}
async function logStorageCleanupWarning(scope,detail){try{await sb.from('admin_maintenance_log').insert({actor_user_id:me().id,action:'PURGE_STORAGE_WARNING',scope,cutoff:new Date().toISOString(),detail})}catch{}}
async function createSafetyBackup(label='PRE_CLEANUP'){const payload=await buildPortableBackup(),text=JSON.stringify(payload),name=`${label}_${new Date().toISOString().replace(/[:.]/g,'-')}.totusbackup`;downloadBlob(name,new Blob([text],{type:'application/json'}));await saveBackupPrivate(payload,name,text);return payload}
async function runPurge(scope){if(!isAdmin())return;const reason=document.getElementById('purgeReason').value.trim(),before=document.getElementById('purgeBefore').value;if(reason.length<5)return notifyMsg('Indica un motivo administrativo de al menos 5 caracteres.','warn');const critical=['library','operational'].includes(scope),ok=await askConfirm({title:'Confirmar limpieza',message:`Ámbito: ${scope}. ${critical?'Esta operación es especialmente destructiva y Totus creará antes un backup completo descargado y privado.':''}`,confirmText:'EJECUTAR LIMPIEZA',danger:true,requireText:critical?'LIMPIAR':''});if(!ok)return;const targets=purgeStorageTargets(scope);if(critical){notifyMsg('Creando backup de seguridad previo…');try{await createSafetyBackup('PRE_CLEANUP')}catch(e){return notifyMsg('Limpieza cancelada: '+e.message,'bad')}}const {error}=await sb.rpc('admin_purge_totus',{p_scope:scope,p_before:before?new Date(before+'T23:59:59').toISOString():new Date().toISOString(),p_reason:reason});if(error)return notifyMsg(error.message,'bad');try{for(const [bucket,paths] of Object.entries(targets))await removeStoragePaths(bucket,paths)}catch(e){await logStorageCleanupWarning(scope,`Datos eliminados pero Storage requiere revisión: ${e.message}`);await reloadTeamData();renderGeneralLog();return notifyMsg('La limpieza de datos terminó, pero no se pudo completar Storage tras 3 intentos: '+e.message,'bad')}await reloadTeamData();renderGeneralLog();notifyMsg('Limpieza completada y registrada.')}
async function cleanupClosedTaskEvidence(){if(!isAdmin())return;const before=document.getElementById('purgeBefore').value,reason=document.getElementById('purgeReason').value.trim();if(reason.length<5)return notifyMsg('Indica un motivo administrativo.','warn');const cutoff=before?new Date(before+'T23:59:59'):new Date(),targets=db.evidence.filter(e=>new Date(e.created_at)<cutoff&&['done','cancelled'].includes(db.tasks.find(t=>t.id===e.task_id)?.status));if(!targets.length)return notifyMsg('No hay fotos antiguas de tareas cerradas para ese corte.');if(!await askConfirm({title:'Eliminar fotos antiguas',message:`Se eliminarán ${targets.length} archivo(s) de tareas cerradas. Las tareas abiertas quedan excluidas.`,confirmText:'Eliminar fotos',danger:true,requireText:'FOTOS'}))return;for(const x of targets){try{await deleteEvidenceWithCompensation(x)}catch(e){return notifyMsg(e.message,'bad')}}await sb.from('admin_maintenance_log').insert({actor_user_id:me().id,action:'PURGE_FILES',scope:'task-evidence',cutoff:cutoff.toISOString(),detail:`${reason} · ${targets.length} evidencias`});await reloadTeamData();renderGeneralLog();notifyMsg('Fotos antiguas eliminadas sin tocar tareas abiertas.')}

(async()=>{setupLoginForm();const recoveryAtStart=isPasswordRecoveryUrl();const {data}=await sb.auth.getSession();session=data.session;sb.auth.onAuthStateChange(async(event,s)=>{session=s;if(event==='SIGNED_OUT'){location.reload();return}if(event==='PASSWORD_RECOVERY'){await showPasswordRecoveryFlow()}});if(session){await bootstrap();if(recoveryAtStart)await showPasswordRecoveryFlow()}})();
